function heilfastenDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Heilfasten der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Ein neunt\u00e4giges Heilfasten kann als transformative Erfahrung im Rahmen des Prozessmodells des Enneagramms betrachtet werden, die auf verschiedene Weise mit den neun Enneagrammprinzipien interagiert. Jeder Fastentag tr\u00e4gt die Qualit\u00e4t eines anderen Prinzips.</p>
      <img src="./assets/heilfasten-der-9-typen.jpg" alt="Neunt\u00e4gige Fastenerfahrung im Rahmen des Enneagramm-Prozessmodells \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:var(--ink);">1. Fastentag \u2013 Enneagrammprinzip der Eins</h3>
        <p class="vb-intro"><strong>Gem\u00fctszustand:</strong> Strenge Selbstdisziplin und Fokus auf den richtigen Weg. <strong>Gedanken:</strong> Konzentration auf die Einhaltung der Fastenregeln und Selbstkritik bei Abweichungen. <strong>Gef\u00fchle:</strong> Stolz auf die Entscheidung zu fasten, begleitet von innerer Anspannung. <strong>K\u00f6rperempfindungen:</strong> Anfangsm\u00fcdigkeit und leichte Kopfschmerzen, verbunden mit einem Gef\u00fchl von Entschlossenheit.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:var(--ink);">2. Fastentag \u2013 Enneagrammprinzip der Zwei</h3>
        <p class="vb-intro"><strong>Gem\u00fctszustand:</strong> Empathie und Sorge um andere. <strong>Gedanken:</strong> \u00dcberlegung, wie das Fasten das eigene Wohlbefinden verbessert und anderen zugute kommt. <strong>Gef\u00fchle:</strong> Freude und Zufriedenheit, anderen durch Vorbildwirkung zu helfen, aber auch leichte Selbstaufopferung. <strong>K\u00f6rperempfindungen:</strong> Leichte k\u00f6rperliche Schw\u00e4che und Hungergef\u00fchle, begleitet von einem Wunsch nach sozialem Austausch.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:var(--ink);">3. Fastentag \u2013 Enneagrammprinzip der Drei</h3>
        <p class="vb-intro"><strong>Gem\u00fctszustand:</strong> Motivation und Zielorientierung. <strong>Gedanken:</strong> Fokussierung auf die positiven Ergebnisse des Fastens und pers\u00f6nliche Leistungsf\u00e4higkeit. <strong>Gef\u00fchle:</strong> Stolz auf Fortschritte, m\u00f6glicherweise mit einem Hauch von Ungeduld. <strong>K\u00f6rperempfindungen:</strong> Verbesserte Energie und Konzentration, aber auch m\u00f6gliche Schlaflosigkeit.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:var(--ink);">4. Fastentag \u2013 Enneagrammprinzip der Vier</h3>
        <p class="vb-intro"><strong>Gem\u00fctszustand:</strong> Tiefe Reflexion und Emotionalit\u00e4t. <strong>Gedanken:</strong> Auseinandersetzung mit den eigenen Gef\u00fchlen und der Bedeutung des Fastens. <strong>Gef\u00fchle:</strong> Intensive emotionale H\u00f6hen und Tiefen, begleitet von Kreativit\u00e4t und Selbstreflexion. <strong>K\u00f6rperempfindungen:</strong> Schwankende Energielevels, Gef\u00fchl von K\u00e4lte oder W\u00e4rme.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:var(--ink);">5. Fastentag \u2013 Enneagrammprinzip der F\u00fcnf</h3>
        <p class="vb-intro"><strong>Gem\u00fctszustand:</strong> Intellektuelle Klarheit und R\u00fcckzug. <strong>Gedanken:</strong> Analysieren der k\u00f6rperlichen und psychischen Ver\u00e4nderungen w\u00e4hrend des Fastens. <strong>Gef\u00fchle:</strong> Distanzierte Ruhe, eventuell kombiniert mit innerem R\u00fcckzug. <strong>K\u00f6rperempfindungen:</strong> Stabilisierung des Energielevels, geistige Klarheit und weniger Hungergef\u00fchle.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:var(--ink);">6. Fastentag \u2013 Enneagrammprinzip der Sechs</h3>
        <p class="vb-intro"><strong>Gem\u00fctszustand:</strong> Sorge und Wachsamkeit. <strong>Gedanken:</strong> Zweifel und Sicherheitsbedenken bez\u00fcglich der gesundheitlichen Auswirkungen des Fastens. <strong>Gef\u00fchle:</strong> Ambivalenz zwischen Vertrauen und Angst, begleitet von einem Bed\u00fcrfnis nach Unterst\u00fctzung. <strong>K\u00f6rperempfindungen:</strong> Leichte Nervosit\u00e4t, m\u00f6glicherweise Verdauungsbeschwerden. <em>Ab dem 6. Tag baut der K\u00f6rper im Rahmen der Autophagie zu 95 % Fett ab \u2014 in den ersten 5 Fastentagen je 50 % Fett und 50 % Protein.</em></p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:var(--ink);">7. Fastentag \u2013 Enneagrammprinzip der Sieben</h3>
        <p class="vb-intro"><strong>Gem\u00fctszustand:</strong> Optimismus und Freude. <strong>Gedanken:</strong> Planen von Aktivit\u00e4ten und Genie\u00dfen der Fastenerfahrung. <strong>Gef\u00fchle:</strong> Euphorie und Enthusiasmus, aber auch Tendenz zur Ablenkung. <strong>K\u00f6rperempfindungen:</strong> Hohe Energie und Bewegungsdrang, gelegentlich Unruhe.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:var(--ink);">8. Fastentag \u2013 Enneagrammprinzip der Acht</h3>
        <p class="vb-intro"><strong>Gem\u00fctszustand:</strong> Entschlossenheit und St\u00e4rke. <strong>Gedanken:</strong> Fokussierung auf Kontrolle und Durchhalteverm\u00f6gen. <strong>Gef\u00fchle:</strong> Gef\u00fchl von Kraft und \u00dcberlegenheit, m\u00f6glicherweise verbunden mit Aggressivit\u00e4t. <strong>K\u00f6rperempfindungen:</strong> Hohe k\u00f6rperliche Energie und Widerstandsf\u00e4higkeit.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:var(--ink);">9. Fastentag \u2013 Enneagrammprinzip der Neun</h3>
        <p class="vb-intro"><strong>Gem\u00fctszustand:</strong> Gelassenheit und Akzeptanz. <strong>Gedanken:</strong> Harmonie und Frieden durch die Fastenerfahrung. <strong>Gef\u00fchle:</strong> Innere Ruhe und Zufriedenheit, m\u00f6glicherweise leichtes Desinteresse. <strong>K\u00f6rperempfindungen:</strong> Stabile Energielevels und Wohlbefinden, insgesamt ausgeglichen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:var(--ink);">10. Tag \u2013 Das Fastenbrechen</h3>
        <p class="vb-intro">Das Fastenbrechen erfolgt traditionell durch das Essen eines Apfels \u2014 ein stiller, bewusster Moment des Wiederbeginns. Nach neun Tagen innerer Reise durch alle Enneagrammprinzipien kehrt der Fastende neu gestimmt in den Alltag zur\u00fcck.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:1rem;padding:1rem 1.2rem;background:var(--surface-2, rgba(0,0,0,0.04));border-radius:8px;">
        <p style="font-size:0.9rem;color:var(--muted);line-height:1.6;margin:0;"><strong>Anmerkung:</strong> Eine Fastenerfahrung im Rahmen der 27 Subtypen des Enneagramms kann sich je nach Subtypenvariante (Normaltyp, Verst\u00e4rkungstyp, Kontratyp) entweder entsprechend, verst\u00e4rkt oder auch genau gegenteilig ausdr\u00fccken. Ein neunt\u00e4giges Fasten kann f\u00fcr jeden Enneagrammtyp eine individuell unterschiedliche, aber dennoch universell transformative Erfahrung sein. Dennoch gibt es im Rahmen des Prozessmodells des Enneagramms 9 universelle Erfahrungen w\u00e4hrend des Fastens \u2014 unabh\u00e4ngig vom jeweiligen Typ oder Subtyp. Der Autor hat dieses 9-t\u00e4gige \u201eEnneagramm-Fasten" selbst unmittelbar vor dem Erstellen dieser \u00dcbersicht im Rahmen eines Heilfastens vom 01.08.2024 bis 09.08.2024 erlebt.</p>
      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"psychologisches-abwehrverhalten-der-9-typen", label:"Psychologisches Abwehrverhalten"},
        {route:"psychologische-verhaltensmuster-der-9-typen", label:"Psychologische Verhaltensmuster"},
        {route:"essverhalten-der-9-typen", label:"Essverhalten der 9 Typen"},
      ])}
    </div>
  `);
}

function psychologischeVerhaltensmuster9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Psychologische Verhaltensmuster der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Diese psychologischen Verhaltensmuster sind tief in der Pers\u00f6nlichkeit verwurzelt und beeinflussen, wie jeder der 9 Typen denkt, f\u00fchlt und handelt. Das Kreisdiagramm ordnet die Typen ihren drei Triaden zu: <strong>Bauchtriiade</strong> (Typen 8, 9, 1), <strong>Herztriade</strong> (Typen 2, 3, 4) und <strong>Kopftriade</strong> (Typen 5, 6, 7).</p>
      <img src="./assets/psychologische-verhaltensmuster-der-9-typen.jpg" alt="Psychologische Verhaltensmuster der 9 Enneagrammtypen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Zwanghaft-besessen (Bauchtriiade)</h3>
        <p class="vb-intro">Typ 1 hat eine starke Tendenz, alles richtig und fehlerfrei machen zu wollen \u2014 ein zwanghafter Drang nach Ordnung, der tief im Bauchzentrum verankert ist. Er neigt dazu, sich selbst und andere zu kritisieren, wenn die eigenen hohen Standards nicht erf\u00fcllt werden. Dahinter steckt ein starkes Bed\u00fcrfnis nach Selbstkontrolle und moralisch korrektem Handeln \u2014 der innere Richter schl\u00e4ft nie.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Abh\u00e4ngig-theatralisch (Herztriade)</h3>
        <p class="vb-intro">Typ 2 f\u00fchlt sich zu Menschen hingezogen, die Unterst\u00fctzung ben\u00f6tigen, und bietet ihnen oft Hilfe an \u2014 getrieben von einer tiefen Erl\u00f6sungssehnsucht. Er erwartet Dankbarkeit und emotionale Anerkennung f\u00fcr die geleistete Hilfe und kann dabei eigene Bed\u00fcrfnisse vernachl\u00e4ssigen, um f\u00fcr andere da zu sein. Das Herzzentrum des Typs 2 sucht unabl\u00e4ssig nach Best\u00e4tigung durch Geben.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Ungeduldig, ehrgeiziger Workaholic (Herztriade)</h3>
        <p class="vb-intro">Typ 3 hat ein starkes Bed\u00fcrfnis nach Anerkennung und Status durch Leistung. Er passt sich leicht an verschiedene Situationen an, um erfolgreich zu wirken \u2014 und zeigt sich dabei stets von seiner besten Seite, um bewundert zu werden. Im Herzzentrum liegt die treibende Kraft: Wer bin ich, wenn ich nicht leiste? Diese Frage treibt den Typ 3 unaufh\u00f6rlich vorw\u00e4rts.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Depressiv-masochistisch (Herztriade)</h3>
        <p class="vb-intro">Typ 4 sucht nach Individualit\u00e4t und ist stolz darauf, anders zu sein. Er erlebt Emotionen sehr tief und kann melancholisch oder dramatisch sein \u2014 das Herzzentrum ist bei ihm besonders empfindlich gestimmt. Typ 4 neigt zu intensiver Selbstreflexion \u00fcber die eigene Identit\u00e4t und die Frage: Wer bin ich wirklich? \u2014 eine Frage, die keine endg\u00fcltige Antwort findet und deshalb immer weitergeht.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Schizoid, vermeidend (Kopftriade)</h3>
        <p class="vb-intro">Typ 5 hat ein starkes Bed\u00fcrfnis, die Welt intellektuell zu verstehen und tief in Themen einzutauchen. Er bevorzugt Distanz und Unabh\u00e4ngigkeit und zieht sich zur\u00fcck, um Ressourcen zu sparen und emotionalen \u00dcberforderungen zu entgehen. Das Kopfzentrum des Typs 5 ist sein Heimatort \u2014 dort f\u00fchlt er sich sicher, dort braucht er niemanden.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 \u00c4ngstlich-paranoid (Kopftriade)</h3>
        <p class="vb-intro">Typ 6 hat ein starkes Bed\u00fcrfnis nach Sicherheit und Schutz \u2014 oft verbunden mit Misstrauen gegen\u00fcber Neuem und Unbekanntem. Er bindet sich an Gruppen, Autorit\u00e4ten oder Ideologien, um Stabilit\u00e4t zu finden, und neigt dazu, Entscheidungen sorgf\u00e4ltig auf m\u00f6gliche Risiken abzuw\u00e4gen und potenzielle Gefahren fr\u00fchzeitig zu erkennen. Das Kopfzentrum des Typs 6 denkt immer auch den schlimmsten Fall mit.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Narzisstisch (Kopftriade)</h3>
        <p class="vb-intro">Typ 7 versucht, unangenehme Gef\u00fchle durch st\u00e4ndige Suche nach Spa\u00df und Abwechslung zu vermeiden. Er hat eine positive Grundeinstellung und fokussiert sich auf die vielen M\u00f6glichkeiten des Lebens \u2014 und wechselt schnell zwischen Interessen, um Langeweile nicht aufkommen zu lassen. Das Kopfzentrum des Typs 7 plant immer schon die n\u00e4chste Freude, w\u00e4hrend die aktuelle noch andauert.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Soziopathisch-sadistisch (Bauchtriiade)</h3>
        <p class="vb-intro">Typ 8 hat ein starkes Bed\u00fcrfnis nach Macht und Kontrolle \u2014 \u00fcber sich selbst und andere. Er kommuniziert offen und konfrontativ, oft ohne R\u00fccksicht auf die Gef\u00fchle anderer, und verteidigt vehement sich selbst und die Menschen, die ihm wichtig sind. Das Bauchzentrum des Typs 8 ist reine Kraft: Wer mich bedroht, sp\u00fcrt Widerstand. Wer mir loyal ist, erh\u00e4lt Schutz.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Passiv-aggressiv (Bauchtriiade)</h3>
        <p class="vb-intro">Typ 9 hat ein starkes Bed\u00fcrfnis nach innerem und \u00e4u\u00dferem Frieden und vermeidet Auseinandersetzungen. Er neigt dazu, sich den W\u00fcnschen anderer anzupassen, um Harmonie zu bewahren \u2014 und kann dabei eigene Bed\u00fcrfnisse ignorieren, um Unruhe zu vermeiden. Das Bauchzentrum des Typs 9 ist zwar vorhanden, aber oft eingeschl\u00e4fert: Die eigene Kraft meldet sich \u2014 nur leise, und selten geh\u00f6rt.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"heilfasten-der-9-typen", label:"Heilfasten der 9 Typen"},
        {route:"auffaellige-merkmale-der-9-typen", label:"Auff\u00e4llige Merkmale der 9 Typen"},
        {route:"suchtverhalten-der-9-typen", label:"Suchtverhalten der 9 Typen"},
      ])}
    </div>
  `);
}

function frisurenDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Frisuren der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Auch die Haare sprechen. Wer wei\u00df, wonach er sucht, kann am Stil einer Frisur \u2014 ihrer Pflege, ihrer Strenge oder Lockerheit, ihrer Auff\u00e4lligkeit oder Unauff\u00e4lligkeit \u2014 oft erstaunlich viel \u00fcber den Enneagrammtyp ihres Tr\u00e4gers ablesen.</p>
      <img src="./assets/frisuren-der-9-typen.jpg" alt="Typische Frisuren der 9 Enneagrammtypen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Gepflegt und pr\u00e4zise</h3>
        <p class="vb-intro">Typ 1 tr\u00e4gt gepflegte, ordentliche Frisuren \u2014 oft klassische oder konservative Stile, die Pr\u00e4zision und Sorgfalt widerspiegeln. M\u00f6glicherweise streng zur\u00fcckgebundenes Haar oder akkurat geschnittene Frisuren. F\u00fcr den Perfektionisten ist kein Haar zuf\u00e4llig: Jeder Strand sitzt, wie er sitzen soll. Die Frisur ist keine Selbstdarstellung \u2014 sie ist Ausdruck von Ernsthaftigkeit und Respekt, sich selbst und anderen gegen\u00fcber.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Weich und einladend</h3>
        <p class="vb-intro">Typ 2 bevorzugt weiche, einladende Frisuren \u2014 h\u00e4ufig lockere, nat\u00fcrliche Stile, die W\u00e4rme und Freundlichkeit ausstrahlen. Eventuell auch Frisuren, die leicht zug\u00e4nglich und pflegeleicht sind. Die Frisur des Helfers soll keine Distanz schaffen \u2014 sie soll einladen, n\u00e4herkommen, vertrauen. Nichts Hartes, nichts Abweisendes. Das Haar des Typs 2 umarmt, noch bevor die Arme es tun.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Stilsicher und trendbewusst</h3>
        <p class="vb-intro">Typ 3 tr\u00e4gt stilvolle, modische Frisuren \u2014 gepflegte und pr\u00e4sentable Stile, die Selbstbewusstsein und Erfolg betonen. M\u00f6glicherweise Frisuren, die aktuellen Trends folgen, gegebenenfalls mit h\u00e4ufiger Nutzung von Haargel. Der Dynamiker wei\u00df: Der erste Eindruck z\u00e4hlt, und das Haar ist Teil der B\u00fchne. Die Frisur sitzt \u2014 immer. Und wenn sich ein Trend \u00e4ndert, \u00e4ndert der Typ 3 die Frisur.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Kreativ und unverwechselbar</h3>
        <p class="vb-intro">Typ 4 w\u00e4hlt kreative, einzigartige Frisuren \u2014 ungew\u00f6hnliche und k\u00fcnstlerische Stile, die Individualit\u00e4t und Besonderheit ausdr\u00fccken. H\u00e4ufig unkonventionelle, mitunter extravagante Farben oder Schnitte. Die Frisur des Individualisten ist keine Laune und keine Anpassung \u2014 sie ist Aussage. Sie sagt: Ich bin nicht wie alle anderen. Und das ist kein Aufschrei, sondern ein stilles, tiefes Bekenntnis zur eigenen Einzigartigkeit.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Funktional und unkompliziert</h3>
        <p class="vb-intro">Typ 5 bevorzugt funktionale, einfache Frisuren \u2014 h\u00e4ufig pflegeleichte Stile, die nicht viel Aufmerksamkeit erfordern. Eventuell auch Frisuren, die Praktikabilit\u00e4t betonen. Der Denker/Forscher m\u00f6chte kein Haar, das Pflege kostet, Aufmerksamkeit fordert oder Zeit verschlingt. Die Frisur soll funktionieren, nicht auffallen. Am liebsten: einmal geschnitten, lange vergessen \u2014 und wieder in Gedanken versinken.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Konservativ und verl\u00e4sslich</h3>
        <p class="vb-intro">Typ 6 tr\u00e4gt konservative, verl\u00e4ssliche Frisuren \u2014 klassische oder unauff\u00e4llige Stile, die Sicherheit und Stabilit\u00e4t vermitteln. M\u00f6glicherweise Frisuren, die in beruflichen oder sozialen Kontexten als angemessen gelten. Der loyale Skeptiker m\u00f6chte mit seinem Haar keine Aufmerksamkeit erregen, keinen Ansto\u00df geben, keinen Fehler machen. Die Frisur ist bew\u00e4hrt \u2014 und Bew\u00e4hrtes gibt Sicherheit.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Lebendig und experimentierfreudig</h3>
        <p class="vb-intro">Typ 7 tr\u00e4gt lebhafte, dynamische Frisuren \u2014 Stile, die Energie und Abenteuerlust ausdr\u00fccken. Eventuell wechselnde Frisuren oder experimentelle Stile. Der Enthusiast langweilt sich schnell \u2014 auch beim Haar. Was heute tr\u00e4gt, muss morgen nicht mehr stimmen. Frisurwechsel sind f\u00fcr ihn kein Aufwand, sondern Vergn\u00fcgen: Wieder etwas Neues, wieder ein frischer Anfang.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Stark und markant</h3>
        <p class="vb-intro">Typ 8 tr\u00e4gt starke, markante Frisuren \u2014 dominante Stile, die Selbstbewusstsein und St\u00e4rke betonen. M\u00f6glicherweise kurze oder kraftvolle Frisuren. Der Herausforderer braucht kein aufwendiges Haar \u2014 er braucht ein Haar, das seiner Pr\u00e4senz entspricht. Klar, entschieden, ohne Spielerei. Die Frisur des Typs 8 nimmt Raum ein, wie er selbst Raum einnimmt: selbstverst\u00e4ndlich und ohne Entschuldigung.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Entspannt und nat\u00fcrlich</h3>
        <p class="vb-intro">Typ 9 bevorzugt entspannte, nat\u00fcrliche Frisuren \u2014 h\u00e4ufig harmonische, unaufdringliche Stile, die Gelassenheit vermitteln. Eventuell Frisuren, die wenig Aufwand erfordern und pflegeleicht sind. Der Friedliche m\u00f6chte kein Haar, das Arbeit macht oder Aufmerksamkeit auf sich zieht. Am sch\u00f6nsten ist es, wenn das Haar einfach liegt \u2014 nat\u00fcrlich, ruhig, ohne dass man dar\u00fcber nachdenken muss.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"psychologische-verhaltensmuster-der-9-typen", label:"Psychologische Verhaltensmuster"},
        {route:"auffaellige-merkmale-der-9-typen", label:"Auff\u00e4llige Merkmale der 9 Typen"},
        {route:"superpower-der-9-typen", label:"Superpower der 9 Typen"},
      ])}
    </div>
  `);
}

function auffaelligeMerkmale9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Auff\u00e4llige k\u00f6rperliche Merkmale der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Das Resonanzprinzip \u201eWie innen so au\u00dfen" geht davon aus, dass unsere \u00e4u\u00dfere Realit\u00e4t ein Spiegelbild unserer inneren Zust\u00e4nde ist \u2014 auch \u201eSpiegelgesetz" genannt. Jeder Enneagrammtyp tr\u00e4gt seine innere Natur auf ganz charakteristische Weise nach au\u00dfen: in Gesichtsz\u00fcgen, Blick, Gestik und K\u00f6rperhaltung.</p>
      <img src="./assets/auffaellige-merkmale-der-9-typen.jpg" alt="Auff\u00e4llige k\u00f6rperliche Merkmale der 9 Enneagrammtypen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Prinzipienorientiert: Der Perfektionist</h3>
        <p class="vb-intro">Scharfe, klare, strenge und mitunter sehr angespannte Gesichtsz\u00fcge. Stirnrunzeln \u2014 der st\u00e4ndige Fokus auf Details verursacht eine vertikale Zornesfalte zwischen den Augen oder zusammengezogene Augenbrauen. Ein ernster, strenger oder stark konzentrierter Ausdruck (der \u201ezornige Zeigefinger"!), ein starrer, mitunter zorniger Blick, und eine sehr aufrechte, angespannte K\u00f6rperhaltung mit Spannung in Gesicht und Nacken. All das spiegelt die strukturierte und ordentliche, manchmal starre und kalte Natur von Typ 1 wider.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Liebesorientiert: Der Geber/Helfer</h3>
        <p class="vb-intro">Weiche, warme und sanfte Gesichtsz\u00fcge, offene Arme und Gesten. Freundliches, einladendes und h\u00e4ufiges L\u00e4cheln auf den Lippen, gewogene Mimik. Gro\u00dfe Augen, die oft Mitgef\u00fchl ausdr\u00fccken, und ein sanfter, einladender Blick, nach au\u00dfen gewendet. Diese Merkmale spiegeln die herzliche, f\u00fcrsorgliche, mitunter empathische, offene und warme Natur von Typ 2 wider \u2014 ein Mensch, der sich k\u00f6rperlich dem anderen zuwendet, bevor er auch nur ein Wort gesagt hat.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Erfolgsorientiert: Der Dynamiker</h3>
        <p class="vb-intro">Selbstbewusster, tatkr\u00e4ftiger und enthusiastischer Ausdruck. Ein gepflegtes, gut gestyltes und dynamisches Erscheinungsbild. Strahlendes, oft kaltes L\u00e4cheln \u2014 sehr pr\u00e4sentabel, energische Bewegungen. Ein durchsetzungsf\u00e4higer, sehr direkter und fokussierter Blick. Diese Merkmale spiegeln die zielstrebige, fokussierte, leistungsorientierte, manchmal etwas berechnende und k\u00fchle Natur von Typ 3 wider. Der Au\u00dfenauftritt ist kein Nebeneffekt \u2014 er ist Teil der Strategie.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Selbstorientiert: Der Individualist</h3>
        <p class="vb-intro">\u00c4sthetische, ebenm\u00e4\u00dfige und feine, grazi\u00f6se Gesichtsz\u00fcge, die Melancholie oder Tiefgr\u00fcndigkeit ausdr\u00fccken. Eine individuelle, elegante und intensive \u00e4u\u00dfere Erscheinung in Mimik und Auftreten. Geheimnisvoller, trauriger Ausdruck. Ein tief-emotionaler, ausdrucksstarker Blick \u2014 nach innen gewendet, mitunter dramatisch, je nach variabler Stimmung. Diese Merkmale spiegeln die emotionale Tiefe sowie die kreative und \u00e4sthetische Natur von Typ 4 wider.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Wissensorientiert: Der Denker/Forscher</h3>
        <p class="vb-intro">Unemotionale Gesichtsz\u00fcge mit neutraler, zur\u00fcckhaltender Mimik \u2014 das sogenannte \u201ePokerface" \u2014 und oft gedankenverlorener Ausdruck. Ein nachdenklicher, manchmal distanzierter, forschender Blick. Minimale, aber pr\u00e4zise Gestik. Zur\u00fcckhaltendes L\u00e4cheln. Ein analytischer, beobachtender und emotionskarger Blick nach innen gewendet, zur\u00fcckziehende, introvertierte, gelegentlich geb\u00fcckte K\u00f6rperhaltung. Diese Merkmale spiegeln das tiefgr\u00fcndige Denken und die forschende, objektiv-beobachtende Natur von Typ 5 wider.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Sicherheitsorientiert: Der loyale Skeptiker</h3>
        <p class="vb-intro">Aufmerksamer, fragender Gesichtsausdruck, freundliches, aber vorsichtiges L\u00e4cheln, abw\u00e4gende Mimik. Angespannte Kiefermuskulatur. Wachsame, vorsichtige, gelegentlich angespannte K\u00f6rperhaltung. Vorsichtiger, wacher oder besorgter Ausdruck, Anspannung um die Augen. Ein \u00e4ngstlicher, unsicherer Blick \u2014 st\u00e4ndig auf der Hut, schnell umherblickend. Diese Merkmale spiegeln die vorsichtige und sicherheitsmotivierte, mitunter skeptische Natur von Typ 6 wider.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Spa\u00dforientiert: Der Enthusiast/Optimist</h3>
        <p class="vb-intro">Strahlendes, mitunter breites und lebhaftes L\u00e4cheln, kindliche, naive Gesichtsz\u00fcge. Ein energiegeladener, offener, fr\u00f6hlicher Gesichtsausdruck mit schnellem Mimikwechsel. Schnelle, weit ausladende Bewegungen. Ein lebhafter, funkelnder Blick. Diese Merkmale spiegeln die optimistische, lustige, lebensbejahende, fr\u00f6hliche, leichte und begeisternde \u2014 mitunter schnell gelangweilte und leidvermeidende \u2014 Natur von Typ 7 wider.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Machtorientiert: Der Herausforderer</h3>
        <p class="vb-intro">Starke, markante, manchmal auch grobe (rohe) Gesichtsz\u00fcge. Eine durchsetzungsstarke, herausfordernde und pr\u00e4sente, kr\u00e4ftige K\u00f6rperhaltung. Furchtloser, dominanter Ausdruck. Durchdringender, oft intensiver Blick. Stark ausgepr\u00e4gte, energetische Gestik. Diese Merkmale spiegeln die dominante, entschlossene, selbstbewusste, pr\u00e4sente und machtvolle \u2014 manchmal gar einsch\u00fcchternde \u2014 Natur von Typ 8 wider.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Harmonieorientiert: Der Vermittler</h3>
        <p class="vb-intro">Sanfte, verschwommene und mitunter tr\u00e4ge Gesichtsz\u00fcge. Eine gelassene, selbstvergessene K\u00f6rperhaltung. Entspannter, harmonischer Ausdruck. Ruhiges, oft gelassenes und friedliches L\u00e4cheln. Ein peripherer, selbstvergessener, nichtfokussierter \u2014 mitunter nichtssagender \u2014 Blick. Diese Merkmale spiegeln die ruhige Gelassenheit und die friedliebende, weiche und nachgiebige Natur von Typ 9 wider.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:1rem;padding:1rem 1.2rem;background:var(--surface-2, rgba(0,0,0,0.04));border-radius:8px;">
        <p style="font-size:0.9rem;color:var(--muted);line-height:1.6;margin:0;"><strong>Anmerkung:</strong> Das Spiegelgesetz in Bezug auf die 9 Enneagrammprinzipien bzw. -typen kann sich im Rahmen der 27 Subtypen des Enneagramms je nach Subtypenvariante (Normaltyp, Verst\u00e4rkungstyp, Kontratyp) entweder entsprechend, verst\u00e4rkt oder auch genau gegenteilig ausdr\u00fccken. Au\u00dferdem spielt der jeweilige Bewusstseinsgrad des Individuums hierbei eine pr\u00e4gende Rolle.</p>
      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"frisuren-der-9-typen", label:"Frisuren der 9 Typen"},
        {route:"haendedrucke-der-9-typen", label:"H\u00e4ndedr\u00fccke der 9 Typen"},
        {route:"superpower-der-9-typen", label:"Superpower der 9 Typen"},
      ])}
    </div>
  `);
}

function haendedruckeDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("H\u00e4ndedr\u00fccke der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Jeder Enneagrammtyp hat aufgrund seiner Enneagramm-Pers\u00f6nlichkeit auch einen gewissen Lebensausdruck, der sich unter anderem auch in der charakteristischen Ausdrucksweise seines H\u00e4ndedrucks zeigen kann.</p>
      <img src="./assets/haendedrucke-der-9-typen.jpg" alt="Die H\u00e4ndedr\u00fccke der 9 Enneagrammtypen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Fest und pr\u00e4zise</h3>
        <p class="vb-intro">Typ 1 legt Wert auf Ordnung und Korrektheit, was sich in einem kontrollierten und festen H\u00e4ndedruck zeigt. Der Perfektionist reicht die Hand nicht beil\u00e4ufig \u2014 er tut es bewusst, mit der richtigen Dosierung von Kraft und W\u00fcrde. Zu lasch w\u00e4re unh\u00f6flich, zu fest w\u00e4re \u00fcbergriffig. Der H\u00e4ndedruck des Typs 1 ist eine kleine Visitenkarte seines Charakters: verl\u00e4sslich, klar und ohne Schn\u00f6rkel.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Herzlich und sanft</h3>
        <p class="vb-intro">Typ 2 ist warmherzig und f\u00fcrsorglich, was durch einen sanften, aber freundlichen H\u00e4ndedruck vermittelt wird. Der Helfer sch\u00fcttelt nicht einfach eine Hand \u2014 er empf\u00e4ngt sie. Manchmal legt er die zweite Hand dazu, h\u00e4lt einen Moment l\u00e4nger, schaut dabei in die Augen. Der H\u00e4ndedruck des Typs 2 ist eine kleine Umarmung: Du bist willkommen, ich bin f\u00fcr dich da.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Selbstbewusst und energisch</h3>
        <p class="vb-intro">Typ 3 strebt nach Anerkennung und Erfolg, was sich in einem kr\u00e4ftigen und selbstsicheren H\u00e4ndedruck widerspiegelt. Der Dynamiker wei\u00df, dass der erste Eindruck z\u00e4hlt \u2014 und sein H\u00e4ndedruck ist Teil der Inszenierung. Fest, direkt, mit Blickkontakt. Er signalisiert: Hier ist jemand, der wei\u00df, was er will. Der H\u00e4ndedruck des Typs 3 \u00f6ffnet T\u00fcren, bevor ein Wort gesprochen wurde.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Ausdrucksstark und variabel</h3>
        <p class="vb-intro">Typ 4 ist kreativ und emotional, was sich in einem manchmal wechselhaften, aber stets bewussten H\u00e4ndedruck \u00e4u\u00dfern kann. Der Individualist bringt auch im H\u00e4ndedruck seine Stimmung mit \u2014 mal intensiv und festhaltend, mal zart und zur\u00fcckhaltend, je nachdem, wie er sich in diesem Moment f\u00fchlt. Kein H\u00e4ndedruck des Typs 4 ist wie der andere. Er ist immer echt.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Zur\u00fcckhaltend und bedacht</h3>
        <p class="vb-intro">Typ 5 ist analytisch und zur\u00fcckgezogen, was sich in einem etwas z\u00f6gerlichen oder vorsichtigen H\u00e4ndedruck zeigt. Der Forscher sch\u00fcttelt H\u00e4nde, weil es erwartet wird \u2014 aber er tut es mit einer gewissen inneren Distanz. Der Kontakt ist kurz, korrekt, ohne \u00dcberschwang. Hinter der Zur\u00fcckhaltung steckt kein Desinteresse \u2014 nur der Wunsch, nicht mehr N\u00e4he anzubieten, als er gerade bereit ist zu geben.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Fest und vertrauensw\u00fcrdig</h3>
        <p class="vb-intro">Typ 6 sucht Sicherheit und Loyalit\u00e4t, was durch einen zuverl\u00e4ssigen und stabilen H\u00e4ndedruck ausgedr\u00fcckt wird. Der Loyale gibt einen H\u00e4ndedruck, dem man trauen kann \u2014 nicht zu hart, nicht zu weich, sondern verl\u00e4sslich. Es ist ein H\u00e4ndedruck, der sagt: Ich bin hier, ich stehe zu meinem Wort. F\u00fcr den Typ 6 ist der H\u00e4ndedruck auch eine Art stilles Versprechen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Lebendig und energisch</h3>
        <p class="vb-intro">Typ 7 ist abenteuerlustig und optimistisch, was sich in einem lebhaften und dynamischen H\u00e4ndedruck zeigt. Der Enthusiast sch\u00fcttelt H\u00e4nde mit Schwung \u2014 vielleicht sogar mit einem spontanen Schulterklopfen oder einem breiten L\u00e4cheln dazu. Sein H\u00e4ndedruck steckt an: Hier ist jemand, der froh ist, dich zu treffen, und der schon auf das n\u00e4chste Abenteuer gespannt ist.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Dominant und kr\u00e4ftig</h3>
        <p class="vb-intro">Typ 8 ist durchsetzungsf\u00e4hig und stark, was sich in einem kraftvollen und manchmal \u00fcberw\u00e4ltigenden H\u00e4ndedruck manifestiert. Der Herausforderer reicht die Hand wie eine Aussage: Ich bin pr\u00e4sent, ich bin stark, ich weiche nicht zur\u00fcck. Sein H\u00e4ndedruck f\u00fcllt den Raum. Kein Z\u00f6gern, keine halben Sachen \u2014 wer Typ 8 die Hand sch\u00fcttelt, sp\u00fcrt es noch einen Moment danach.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Sanft und beruhigend</h3>
        <p class="vb-intro">Typ 9 strebt nach Harmonie und Frieden, was durch einen ruhigen und sanften H\u00e4ndedruck verdeutlicht wird. Der Friedliebende reicht die Hand ohne Druck, ohne Dominanz \u2014 einladend, offen, entspannt. Sein H\u00e4ndedruck sagt: Alles ist gut, ich bin nicht bedrohlich, wir k\u00f6nnen in Ruhe miteinander sein. Es ist einer der angenehmsten H\u00e4ndedr\u00fccke \u00fcberhaupt \u2014 weil er nichts beweisen muss.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:1rem;padding:1rem 1.2rem;background:var(--surface-2, rgba(0,0,0,0.04));border-radius:8px;">
        <p style="font-size:0.9rem;color:var(--muted);line-height:1.6;margin:0;"><strong>Anmerkung:</strong> Das Handdruckverhalten im Rahmen der 27 Subtypen des Enneagramms kann sich je nach Subtypenvariante (Normaltyp, Verst\u00e4rkungstyp, Kontratyp) entweder entsprechend, verst\u00e4rkt oder auch genau gegenteilig ausdr\u00fccken. Au\u00dferdem spielt der jeweilige Bewusstseinsgrad dabei eine wichtige Rolle. Je bewusster ein Mensch ist, desto erf\u00fcllender und harmonischer ist auch der Ausdruck seines Handdruckverhaltens im Rahmen seines jeweiligen Typspektrums.</p>
      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"auffaellige-merkmale-der-9-typen", label:"Auff\u00e4llige Merkmale der 9 Typen"},
        {route:"suchtverhalten-der-9-typen", label:"Suchtverhalten der 9 Typen"},
        {route:"niesverhalten-der-9-typen", label:"Niesverhalten der 9 Typen"},
      ])}
    </div>
  `);
}

function suchtverhalteDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Suchtverhalten der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Jeder Mensch kennt Muster, die sich wiederholen \u2014 Verhaltensweisen, nach denen man greift, wenn der Druck zu gro\u00df wird oder die innere Leere sich meldet. Das Enneagramm zeigt, welche typspezifischen Suchtstrukturen hinter diesen Mustern stecken.</p>
      <img src="./assets/suchtverhalten-der-9-typen.jpg" alt="Das Suchtverhalten der 9 Enneagrammtypen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Zwanghafter Perfektionismus</h3>
        <p class="vb-intro">Typ 1 kann dazu neigen, sich zwanghaft auf Ordnung, Disziplin und Kontrolle zu fixieren. Dies kann sich in einem ungesunden Perfektionismus \u00e4u\u00dfern, der Stress und Burnout zur Folge haben kann. Manchmal greifen Einser auch zu Substanzen, um den Druck ihrer hohen Standards zu bew\u00e4ltigen. Der innere Richter, der nie ruht, wird zur eigentlichen Sucht \u2014 die Suche nach dem Fehlerfreien, nach dem endlich Richtigen, nach dem Moment, in dem man sich endlich gut genug f\u00fchlt.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Co-Abh\u00e4ngigkeit und emotionales Essen</h3>
        <p class="vb-intro">Typ 2 kann eine Tendenz zur Co-Abh\u00e4ngigkeit entwickeln, indem er sich \u00fcberm\u00e4\u00dfig auf die Bed\u00fcrfnisse anderer konzentriert und seine eigenen vernachl\u00e4ssigt. Typ 2 kann auch zu emotionalem Essen oder Substanzmissbrauch neigen, um seine eigenen emotionalen Bed\u00fcrfnisse zu stillen, wenn er sich nicht pers\u00f6nlich wertgesch\u00e4tzt f\u00fchlt. Die Sucht des Helfers ist oft die Sucht nach Best\u00e4tigung \u2014 nach dem Moment, in dem jemand sagt: Ich brauche dich. Ohne diese R\u00fcckmeldung greift er zu Ersatzmitteln.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Workaholismus und Leistungssucht</h3>
        <p class="vb-intro">Typ 3 kann s\u00fcchtig nach Erfolg, Anerkennung und Status sein. Dreier neigen dazu, sich in Arbeit und Leistung zu verlieren und k\u00f6nnen zu Workaholics werden. In extremen F\u00e4llen greifen sie gar zu leistungssteigernden Substanzen, um ihre Ziele zu erreichen \u2014 das sogenannte \u201eLance Armstrong-Syndrom". Die eigentliche Sucht ist die nach Best\u00e4tigung durch Leistung: Wenn ich genug erreiche, bin ich es wert. Ein Kreislauf, der sich von alleine dreht.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Emotionale Intensit\u00e4t und innere Leere</h3>
        <p class="vb-intro">Typ 4 kann dazu tendieren, sich in seinen Emotionen und seiner Sehnsucht nach Authentizit\u00e4t zu verlieren. Vierer k\u00f6nnen Substanzen oder Verhaltensweisen verwenden, um intensivere emotionale Erfahrungen zu suchen oder sich von ihrer inneren Leere abzulenken. Der \u00c4sthet ist manchmal s\u00fcchtig nach dem Gef\u00fchl selbst \u2014 nach der Tiefe, der Leidenschaft, dem Schmerz, der wenigstens zeigt, dass man lebt. Das Gew\u00f6hnliche f\u00fchlt sich f\u00fcr ihn wie Bet\u00e4ubung an.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Isolation und intellektuelle Flucht</h3>
        <p class="vb-intro">Typ 5 kann eine Neigung zur Isolation und zum R\u00fcckzug entwickeln, oft in eine Welt von Wissen und Information. F\u00fcnfer k\u00f6nnen auch s\u00fcchtig nach bestimmten intellektuellen Besch\u00e4ftigungen oder digitalen Medien werden, um soziale Interaktionen zu vermeiden. Die Sucht des Denkers ist die Sucht nach dem sicheren Innen: Solange ich denke und beobachte, muss ich mich nicht einbringen. Das Wissen selbst wird zur Festung, hinter der man sich verschanzt.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Angstbew\u00e4ltigung und Sicherheitssucht</h3>
        <p class="vb-intro">Typ 6 kann durch seine Angst und sein Bed\u00fcrfnis nach Sicherheit getrieben werden. Sechser k\u00f6nnen Substanzen oder Verhaltensweisen verwenden, um ihre \u00c4ngste zu bet\u00e4uben oder sich allgemein sicherer zu f\u00fchlen. Dies kann zu einer Abh\u00e4ngigkeit von beruhigenden Mitteln oder von Sicherheitsritualen f\u00fchren. Die tiefste Sucht des Skeptikers ist die Sucht nach Gewissheit \u2014 nach dem endg\u00fcltigen Beweis, dass alles gut wird. Den gibt es nicht, und so dreht sich das Rad weiter.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Exzessiver Konsum und Ablenkung</h3>
        <p class="vb-intro">Typ 7 kann s\u00fcchtig nach neuen Erfahrungen, Vergn\u00fcgungen und Abenteuern sein. Siebener neigen dazu, exzessiv zu konsumieren \u2014 sei es Essen, Alkohol, Drogen oder Unterhaltung \u2014 um Negatives, Langeweile und innere Leere zu vermeiden. Die Sucht des Enthusiasten ist die Sucht vor der Sucht: Wenn ich mich nur schnell genug bewege, hole ich mich nicht ein. Der n\u00e4chste Kick kommt, bevor der letzte verarbeitet ist.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Kontroll- und Machtsucht</h3>
        <p class="vb-intro">Typ 8 kann s\u00fcchtig nach Kontrolle, Macht und Intensit\u00e4t sein. Achter neigen dazu, risikoreiche Verhaltensweisen zu suchen, und k\u00f6nnen auch zu Substanzen greifen, die ihnen ein Gef\u00fchl der St\u00e4rke, Dominanz und Unbesiegbarkeit geben. Die eigentliche Sucht des Herausforderers ist die Sucht nach Unverwundbarkeit \u2014 nach dem Gef\u00fchl, nichts und niemanden f\u00fcrchten zu m\u00fcssen. Die Verletzlichkeit, die darunter liegt, bleibt dabei unber\u00fchrt.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Komfortsucht und Konfliktflucht</h3>
        <p class="vb-intro">Typ 9 kann s\u00fcchtig nach Komfort und Vermeidung von Konflikten sein. Neuner tendieren dazu, sich mit Fernsehen, digitalen Medien, Essen oder anderen beruhigenden Aktivit\u00e4ten abzulenken, um sich von unangenehmen Gef\u00fchlen und Spannungen zu distanzieren. Die Sucht des Vermittlers ist die Sucht nach dem Frieden \u2014 auch wenn dieser Frieden erkauft ist durch das Einschlafen des eigenen Willens und der eigenen Lebendigkeit.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:1rem;padding:1rem 1.2rem;background:var(--surface-2, rgba(0,0,0,0.04));border-radius:8px;">
        <p style="font-size:0.9rem;color:var(--muted);line-height:1.6;margin:0;"><strong>Anmerkung:</strong> Das Suchtverhalten im Rahmen der 27 Subtypen des Enneagramms kann sich je nach Subtypenvariante (Normaltyp, Verst\u00e4rkungstyp, Kontratyp) entweder entsprechend, verst\u00e4rkt oder auch genau gegenteilig ausdr\u00fccken. Au\u00dferdem spielt der jeweilige Bewusstseinsgrad dabei eine wichtige Rolle. Je bewusster ein Mensch ist, desto weniger tendiert er zu Suchtverhalten im Rahmen seines jeweiligen Typspektrums. Die gr\u00f6\u00dfte Sucht ist \u2014 allgemein betrachtet \u2014 und bleibt die Sucht des Egos nach Denken, F\u00fchlen und Handeln, entsprechend der 3 Triaden des Enneagramms: Kopf (Typen 5, 6, 7), Herz (Typen 2, 3, 4) und Bauch (Typen 8, 9, 1).</p>
      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"haendedrucke-der-9-typen", label:"H\u00e4ndedr\u00fccke der 9 Typen"},
        {route:"niesverhalten-der-9-typen", label:"Niesverhalten der 9 Typen"},
        {route:"gifte-des-geistes", label:"Gifte des Geistes"},
      ])}
    </div>
  `);
}

function niesverhalteDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Niesverhalten der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Mithilfe des Niesens f\u00fchrt der K\u00f6rper vordergr\u00fcndig eine k\u00f6rperliche, hintergr\u00fcndig eine energetische Selbstreinigung durch. Es werden dadurch k\u00f6rperliche und psychische Blockaden gel\u00f6st und Energie kann insgesamt besser flie\u00dfen. H\u00e4ufiges Niesen bewirkt manchmal auch einen gewissen Neustart. Die unterschiedlichen Enneatypen reagieren sehr unterschiedlich auf den unwillk\u00fcrlichen, unerwarteten Niesreflex, der zum explosionsartigen Aussto\u00df von Luft durch die Nase, oft zugleich auch durch den Mund f\u00fchrt.</p>
      <img src="./assets/niesverhalten-der-9-typen.jpg" alt="Das Niesverhalten der 9 Enneagrammtypen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Pr\u00e4zises Niesen</h3>
        <p class="vb-intro">Typ 1 l\u00e4sst einen einzelnen, gut kontrollierten Nieser los \u2014 dem danach eine ordentliche Entschuldigung folgt. Kein unkontrolliertes Niesen; immer vorbereitet mit einem Taschentuch. Der Perfektionist niest nicht einfach so: Selbst dieser unwillk\u00fcrliche Reflex wird so weit wie m\u00f6glich geordnet vollzogen. Die Entschuldigung danach ist aufrichtig gemeint \u2014 man will ja niemandem zur Last fallen. Und das Taschentuch? Das lag nat\u00fcrlich l\u00e4ngst bereit.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 R\u00fccksichtsvolles Niesen</h3>
        <p class="vb-intro">Typ 2 niest leise, fast entschuldigend \u2014 blo\u00df niemanden st\u00f6ren. Sofort wird Hilfe angeboten: \u201eKann ich dir ein Taschentuch geben?" Der Helfer dreht den Nieser reflexartig in eine Geste der F\u00fcrsorge um. Kaum ist der eigene Reflex vorbei, gilt die Aufmerksamkeit schon wieder den anderen. Ob jemand mitgeniest hat? Ob jemand ein Taschentuch braucht? Die eigene kleine Unannehmlichkeit wird zur Gelegenheit, pr\u00e4sent und hilfsbereit zu sein.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Eindrucksvolles Niesen</h3>
        <p class="vb-intro">Typ 3 niest laut und kr\u00e4ftig \u2014 mit Wirkung. Danach folgt ein selbstbewusster Kommentar \u00fcber das eigene Niesen, um das Bild der Kontrolle und Effizienz zu wahren. Der Dynamiker l\u00e4sst auch beim Niesen keine Schw\u00e4che durchscheinen. Was andere als peinlichen Moment erleben w\u00fcrden, wird souver\u00e4n in Szene gesetzt: \u201eEntschuldigung \u2014 aber effizient, oder?" Ein Nieser mit Markenzeichen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Dramatisches Niesen</h3>
        <p class="vb-intro">Typ 4 begleitet sein Niesen mit einem kreativen Ausdruck der \u00dcberraschung und Dramatik. Danach folgt ein tiefes Nachsinnen \u00fcber die Einzigartigkeit dieses Niesens. Der Individualist erlebt selbst den Niesreflex als etwas Besonderes. War das wirklich nur ein Nieser \u2014 oder steckt da mehr dahinter? Vielleicht ein Zeichen. Vielleicht der K\u00f6rper, der sich ausdr\u00fcckt. Auf jeden Fall: ein Moment, der es wert ist, einen kurzen Augenblick lang gesp\u00fcrt zu werden.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Analytisches Niesen</h3>
        <p class="vb-intro">Typ 5 niest diskret und leise \u2014 gefolgt von einem gedankenvollen Moment, um \u00fcber die Ursache und die gesundheitlichen Implikationen des Niesens nachzudenken. Der Forscher l\u00e4sst sich auch von einem Niesreflex nicht aus dem Konzept bringen. Stattdessen: kurze innere Analyse. Woher kommt das? Staub? Allergien? Ein Fr\u00fchzeichen einer Erk\u00e4ltung? Der Nieser ist bereits vergessen \u2014 das Nachdenken hat gerade erst begonnen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Vorsichtiges Niesen</h3>
        <p class="vb-intro">Typ 6 bedeckt sein Niesen stets mit der Hand oder einem Taschentuch \u2014 um sicherzustellen, dass keine Keime verbreitet werden. Danach wird die Umgebung auf m\u00f6gliche Allergene \u00fcberpr\u00fcft. Der Loyale nimmt auch beim Niesen keine Risiken: Hygiene ist Pflicht, Vorsicht ist Tugend. Und wer wei\u00df \u2014 vielleicht steckt da etwas in der Luft? Besser die Situation im Blick behalten, bevor man weitermacht.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Spontanes Niesen</h3>
        <p class="vb-intro">Typ 7 niest fr\u00f6hlich und unerwartet \u2014 oft begleitet von einem Lachen oder einem scherzhaften Kommentar. Es st\u00f6rt nicht die Begeisterung f\u00fcr das n\u00e4chste Abenteuer. Der Enthusiast macht aus dem Nieser spontan einen kleinen Spa\u00df. \u201eGesundheit mir selbst!" \u2014 und weiter geht's. Kein Innehalten, kein Nachgr\u00fcbeln. Der Moment ist schon wieder vorbei, und das n\u00e4chste Erlebnis wartet bereits.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Dominantes Niesen</h3>
        <p class="vb-intro">Typ 8 niest kr\u00e4ftig und dominant \u2014 nimmt dabei R\u00e4umlichkeit ein und erregt Aufmerksamkeit. Es gibt keine Entschuldigungen: ein selbstbewusster Ausdruck der physischen Pr\u00e4senz. Der Herausforderer niest, wie er alles tut: mit voller Kraft, ohne Z\u00f6gern, ohne R\u00fccksicht auf m\u00f6gliche Blicke. Der K\u00f6rper hat gesprochen \u2014 und das ist vollkommen in Ordnung so. Wer sich davon st\u00f6ren l\u00e4sst, hat ein Problem. Nicht er.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Sanftes Niesen</h3>
        <p class="vb-intro">Typ 9 niest leise und friedlich \u2014 kaum zu bemerken. Danach folgt ein entschuldigender Blick, um sicherzustellen, dass niemand gest\u00f6rt wurde. Der Friedliebende versucht, selbst beim Niesen so wenig Raum wie m\u00f6glich einzunehmen. Der Reflex kam \u2014 er konnte nichts daf\u00fcr \u2014 aber der entschuldigende Blick danach zeigt: Ich hoffe, das hat niemanden aus dem Gleichgewicht gebracht. Alles soll ruhig bleiben, auch nach einem Nieser.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:1rem;padding:1rem 1.2rem;background:var(--surface-2, rgba(0,0,0,0.04));border-radius:8px;">
        <p style="font-size:0.9rem;color:var(--muted);line-height:1.6;margin:0;"><strong>Anmerkung:</strong> Das Niesverhalten im Rahmen der 27 Subtypen des Enneagramms kann sich je nach Subtypenvariante (Normaltyp, Verst\u00e4rkungstyp, Kontratyp) entweder entsprechend, verst\u00e4rkt oder auch genau gegenteilig ausdr\u00fccken. Au\u00dferdem spielt der jeweilige Bewusstseinsgrad dabei eine wichtige Rolle. Je bewusster ein Mensch ist, desto erf\u00fcllender und harmonischer ist auch der Ausdruck seines Niesverhaltens im Rahmen seines jeweiligen Typspektrums.</p>
      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"suchtverhalten-der-9-typen", label:"Suchtverhalten der 9 Typen"},
        {route:"essverhalten-der-9-typen", label:"Essverhalten der 9 Typen"},
        {route:"arbeitsverhalten-der-9-typen", label:"Arbeitsverhalten der 9 Typen"},
      ])}
    </div>
  `);
}

function essverhalteDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Essverhalten der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Was und wie wir essen, ist selten nur eine Frage des Geschmacks. Es spiegelt unsere innere Struktur, unsere \u00c4ngste, unsere Sehns\u00fcchte \u2014 und unseren Enneagrammtyp. Jeder Typ bringt seine ganz eigene Haltung zum Essen mit an den Tisch.</p>
      <img src="./assets/essverhalten-der-9-typen.jpg" alt="Das Essverhalten der 9 Enneagrammtypen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Diszipliniert und kontrolliert</h3>
        <p class="vb-intro">Typ 1 tendiert dazu, sehr diszipliniert und kontrolliert zu essen. Er achtet auf gesunde und ausgewogene Ern\u00e4hrung und kann sich selbst strenge Di\u00e4ten auferlegen, um seinen hohen Standards gerecht zu werden. Essen ist f\u00fcr den Perfektionisten kein purer Genuss, sondern auch eine Frage der Tugend: Was ist richtig? Was ist gesund? Was sollte ich mir erlauben? Diese innere Latte kann befreiend sein \u2014 oder zur stillen Last werden, wenn jeder Bissen unter Beobachtung steht.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Emotional und f\u00fcrsorglich</h3>
        <p class="vb-intro">Typ 2 neigt dazu, emotional zu essen, besonders wenn er sich gestresst oder pers\u00f6nlich nicht gesch\u00e4tzt f\u00fchlt. Er kann dazu neigen, andere mit Essen zu verw\u00f6hnen und sich selbst dabei in den Hintergrund zu stellen. F\u00fcr den Helfer ist die K\u00fcche oft ein Ort der Liebe \u2014 er kocht f\u00fcr andere, deckt den Tisch, sorgt daf\u00fcr, dass alle satt werden. Was er dabei manchmal vergisst: sich selbst zu fragen, was er eigentlich m\u00f6chte.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Bewusst und leistungsorientiert</h3>
        <p class="vb-intro">Typ 3 achtet auf sein Aussehen und seine Leistungsf\u00e4higkeit, was sich oft in einer bewussten und manchmal restriktiven Ern\u00e4hrungsweise zeigt. Er kann dazu neigen, Nahrung als Mittel zur Leistungssteigerung zu betrachten. Der Leistungsmensch isst strategisch: Was bringt mir Energie? Was schadet meiner Figur? Was passt zum Image? Essen als Optimierungswerkzeug \u2014 und manchmal auch als B\u00fchne, auf der man zeigt, wie diszipliniert man ist.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Individuell und stimmungsabh\u00e4ngig</h3>
        <p class="vb-intro">Typ 4 hat oft ein sehr individuelles Essverhalten, das stark von seinen emotionalen Zust\u00e4nden beeinflusst wird. Er kann zu extremen Ern\u00e4hrungsweisen neigen, wie z.B. exotischen Di\u00e4ten oder besonderen Ern\u00e4hrungsformen, um seine Einzigartigkeit zu betonen. F\u00fcr den \u00c4stheten ist Essen Ausdruck \u2014 von Stimmung, Identit\u00e4t, Zugeh\u00f6rigkeit zu sich selbst. Ein gew\u00f6hnliches Mittagessen in der Kantine kann sich f\u00fcr den Typ 4 wie eine Absage an das eigene Wesen anf\u00fchlen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Pragmatisch und zweckorientiert</h3>
        <p class="vb-intro">Typ 5 kann eine eher pragmatische und manchmal nachl\u00e4ssige Haltung gegen\u00fcber dem Essen haben. Er k\u00f6nnte Mahlzeiten \u00fcberspringen oder einfache, leicht zuzubereitende Lebensmittel bevorzugen, um mehr Zeit f\u00fcr seine intellektuellen Interessen zu haben. Essen ist f\u00fcr den Denker vor allem eines: notwendig. Es unterbricht den Gedankenstrom, kostet Zeit und Energie \u2014 und so wird die Mahlzeit gerne so effizient wie m\u00f6glich gestaltet, damit man schnell wieder zum Wesentlichen kommt.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Traditionell und vertraut</h3>
        <p class="vb-intro">Typ 6 hat oft ein eher traditionelles Essverhalten und kann sich an bew\u00e4hrte Ern\u00e4hrungsgewohnheiten halten. Er bevorzugt gewohnte, vertraute Speisen und z\u00f6gert tendenziell, neue oder unbekannte Lebensmittel auszuprobieren. Das Vertraute ist f\u00fcr den Skeptiker nicht Langeweile \u2014 es ist Sicherheit. Ein Gericht, das man kennt, kann nicht entt\u00e4uschen. Und im Kreis der Familie oder Freunde schmeckt das Altbekannte noch einmal so gut.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Vielf\u00e4ltig und genussorientiert</h3>
        <p class="vb-intro">Typ 7 liebt Vielfalt und Genuss, auch beim Essen. Er kann dazu neigen, exzessiv zu essen, besonders wenn er gestresst oder gelangweilt ist, und liebt es, neue und aufregende Lebensmittel zu probieren. F\u00fcr den Enthusiasten ist das Essen ein Abenteuer \u2014 am liebsten die neue K\u00fcche, das unbekannte Restaurant, das Gericht, das man noch nie probiert hat. Der Teller als Erlebnisraum. Die Herausforderung: auch dann innezuhalten, wenn es nicht mehr um Genuss geht, sondern um Ablenkung.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Kraftvoll und genussvoll</h3>
        <p class="vb-intro">Typ 8 hat oft ein kraftvolles und intensives Essverhalten. Er bevorzugt reichhaltige, herzhafte Mahlzeiten und hat oft eine gro\u00dfe Portionenkontrolle. Er neigt dazu, das Essen mit Genuss und als Ausdruck seiner St\u00e4rke zu betrachten. Der Herausforderer isst, wie er lebt: mit voller Pr\u00e4senz, ohne Z\u00f6gern, ohne halbe Sachen. Ein gutes Essen ist f\u00fcr ihn ein Fest \u2014 und er l\u00e4sst sich nicht von Schuldgef\u00fchlen begleiten, w\u00e4hrend er genie\u00dft.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Tr\u00f6stend und nachl\u00e4ssig</h3>
        <p class="vb-intro">Typ 9 kann zu einem tr\u00f6stenden und manchmal nachl\u00e4ssigen Essverhalten neigen. Er kann emotional essen, um sich zu beruhigen, und bevorzugt oft vertraute, beruhigende und einfache Lebensmittel. Essen ist f\u00fcr den Vermittler Komfort \u2014 es beruhigt, es verbindet, es schafft Frieden. In stressigen Momenten wird gerne zum Bekannten gegriffen, das verl\u00e4sslich gut tut. Die Herausforderung liegt darin, auch beim Essen bewusst pr\u00e4sent zu bleiben und nicht im Autopilot zu verschwinden.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:1rem;padding:1rem 1.2rem;background:var(--surface-2, rgba(0,0,0,0.04));border-radius:8px;">
        <p style="font-size:0.9rem;color:var(--muted);line-height:1.6;margin:0;"><strong>Anmerkung:</strong> Das Essverhalten im Rahmen der 27 Subtypen des Enneagramms kann sich je nach Subtypenvariante (Normaltyp, Verst\u00e4rkungstyp, Kontratyp) entweder entsprechend, verst\u00e4rkt oder auch genau gegenteilig ausdr\u00fccken. Au\u00dferdem spielt der jeweilige Bewusstseinsgrad dabei eine wichtige Rolle. Je bewusster ein Mensch ist, desto authentischer ist auch der Ausdruck seines Essverhaltens im Rahmen seines jeweiligen Typspektrums.</p>
      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"niesverhalten-der-9-typen", label:"Niesverhalten der 9 Typen"},
        {route:"arbeitsverhalten-der-9-typen", label:"Arbeitsverhalten der 9 Typen"},
        {route:"verhaeltnis-zu-geld-der-9-typen", label:"Verh\u00e4ltnis zu Geld"},
      ])}
    </div>
  `);
}

function arbeitsverhalteDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Arbeitsverhalten der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Wie jemand arbeitet, verr\u00e4t fast alles \u00fcber seinen Enneagrammtyp: Was antreibt ihn, was bremst ihn, wie verh\u00e4lt er sich im Team, wor\u00fcber ger\u00e4t er in Konflikt? Jeder Typ bringt seine ganz eigene Energie an den Arbeitsplatz.</p>
      <img src="./assets/arbeitsverhalten-der-9-typen.jpg" alt="Das Arbeitsverhalten der 9 Enneagrammtypen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Gewissenhaft und detailorientiert</h3>
        <p class="vb-intro">Typ 1 arbeitet gewissenhaft, organisiert und detailorientiert. Er strebt nach hohen Standards und ist oft kritisch gegen\u00fcber seiner eigenen und der Arbeit anderer. Er ist zuverl\u00e4ssig und hat einen starken Drang, Dinge richtig zu machen. Der innere Richter des Typs 1 ist auch am Schreibtisch pr\u00e4sent: Gut ist nicht gut genug, wenn es noch besser geht. Das macht ihn zum verl\u00e4sslichsten Kollegen im Team \u2014 aber auch zum h\u00e4rtesten Kritiker, vor allem sich selbst gegen\u00fcber.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Unterst\u00fctzend und hilfsbereit</h3>
        <p class="vb-intro">Typ 2 ist unterst\u00fctzend und hilfsbereit. Er neigt dazu, die Bed\u00fcrfnisse seiner Kollegen \u00fcber seine eigenen zu stellen und sucht oft Best\u00e4tigung durch Anerkennung und Dankbarkeit. Er ist gut darin, Beziehungen aufzubauen und im Team zu arbeiten. Der Helfer gedeiht in Arbeitsumgebungen, in denen seine F\u00fcrsorge gesehen und gesch\u00e4tzt wird \u2014 ohne diese R\u00fcckmeldung kann er sich ausgebrannt und unsichtbar f\u00fchlen, obwohl er alles f\u00fcr andere gibt.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Zielorientiert und effizient</h3>
        <p class="vb-intro">Typ 3 ist zielorientiert, effizient und ehrgeizig. Er strebt nach Erfolg und Anerkennung und arbeitet oft hart, um seine Ziele zu erreichen. Er ist gut darin, sich selbst und andere zu motivieren und kann in F\u00fchrungspositionen sehr effektiv sein. F\u00fcr den Leistungsmensch ist Arbeit der nat\u00fcrlichste Ausdruck seines Wesens \u2014 er lebt f\u00fcr Ergebnisse, f\u00fcr Meilensteine, f\u00fcr den Moment, in dem das Projekt abgeschlossen ist und alle applaudieren.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Kreativ und bedeutungssuchend</h3>
        <p class="vb-intro">Typ 4 bringt Kreativit\u00e4t und Originalit\u00e4t in seine Arbeit ein. Er sucht nach tiefer Bedeutung und Authentizit\u00e4t in seinen Aufgaben. Er kann jedoch auch stimmungsabh\u00e4ngig sein und Schwierigkeiten haben, sich anzupassen, wenn die Arbeit seine kreativen Bed\u00fcrfnisse nicht erf\u00fcllt. Der \u00c4sthet braucht das Gef\u00fchl, dass seine Arbeit etwas bedeutet \u2014 ein Routinejob ohne Sinngehalt ist f\u00fcr ihn eine Art innerer Tod. Gibt man ihm Raum zur Entfaltung, liefert er Unvergleichliches.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Analytisch und selbstst\u00e4ndig</h3>
        <p class="vb-intro">Typ 5 ist analytisch, fokussiert und selbstst\u00e4ndig. Er bevorzugt es, in Ruhe und ohne Unterbrechungen zu arbeiten. Er sammelt und analysiert Informationen gr\u00fcndlich, bevor er Entscheidungen trifft, und ist oft Experte auf seinem Gebiet. Der Denker braucht R\u00fcckzug, um produktiv zu sein \u2014 zu viel Teamdynamik und Smalltalk kostet ihn Energie, die er lieber in tiefes Durchdenken investiert. Hat er seinen Raum, liefert er Analysen von unvergleichlicher Gr\u00fcndlichkeit.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Zuverl\u00e4ssig und sicherheitsorientiert</h3>
        <p class="vb-intro">Typ 6 ist zuverl\u00e4ssig, gewissenhaft und sicherheitsorientiert. Er ist gut darin, Risiken zu bewerten und Voraussicht in seine Arbeit einzubringen. Er sch\u00e4tzt Stabilit\u00e4t und klare Strukturen und arbeitet gut in unterst\u00fctzenden und kooperativen Umgebungen. Der Skeptiker ist der Typ, der die Schwachstellen im Plan findet, bevor sie zum Problem werden \u2014 ein unsch\u00e4tzbarer Wert im Team, wenn er lernt, seiner eigenen Kompetenz zu vertrauen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Vielseitig und ideenreich</h3>
        <p class="vb-intro">Typ 7 ist vielseitig, ideenreich und energisch. Er liebt Abwechslung sowie neue positive Impulse und bringt oft frische, innovative Ideen ein. Er kann jedoch auch dazu neigen, sich zu verzetteln und Schwierigkeiten haben, Projekte abzuschlie\u00dfen. Der Enthusiast ist der Z\u00fcndfunken jedes Teams \u2014 er begeistert, er inspiriert, er \u00f6ffnet T\u00fcren, die andere noch nicht einmal gesehen haben. Die Herausforderung liegt im Bleiben, wenn die anf\u00e4ngliche Begeisterung nachl\u00e4sst.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Durchsetzungsstark und f\u00fchrungsorientiert</h3>
        <p class="vb-intro">Typ 8 ist durchsetzungsstark, entschlossen und f\u00fchrungsorientiert. Er \u00fcbernimmt gerne Verantwortung und hat keine Angst vor Konfrontationen. Er arbeitet effizient und direkt, setzt sich f\u00fcr seine \u00dcberzeugungen ein und besch\u00fctzt sein Team. Der Herausforderer f\u00fchrt nicht durch Hierarchie, sondern durch St\u00e4rke und Pr\u00e4senz \u2014 er sieht Probleme als Gegner, die es zu besiegen gilt, und rei\u00dft andere in seiner Entschlossenheit mit.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Kooperativ und ausgleichend</h3>
        <p class="vb-intro">Typ 9 ist kooperativ, geduldig und anpassungsf\u00e4hig. Er schafft eine harmonische Arbeitsumgebung und ist gut darin, in Konflikten zu vermitteln. Er kann jedoch manchmal Schwierigkeiten haben, die eigenen Bed\u00fcrfnisse und Meinungen durchzusetzen. Der Vermittler ist der Kitt im Team \u2014 er sorgt daf\u00fcr, dass alle geh\u00f6rt werden und niemand auf der Strecke bleibt. Seine Herausforderung: den eigenen Standpunkt genauso klar vertreten wie die Positionen aller anderen.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:1rem;padding:1rem 1.2rem;background:var(--surface-2, rgba(0,0,0,0.04));border-radius:8px;">
        <p style="font-size:0.9rem;color:var(--muted);line-height:1.6;margin:0;"><strong>Anmerkung:</strong> Das Arbeitsverhalten im Rahmen der 27 Subtypen des Enneagramms kann sich je nach Subtypenvariante (Normaltyp, Verst\u00e4rkungstyp, Kontratyp) entweder entsprechend, verst\u00e4rkt oder auch genau gegenteilig ausdr\u00fccken. Au\u00dferdem spielt der jeweilige Bewusstseinsgrad dabei eine wichtige Rolle. Je bewusster ein Mensch ist, desto erf\u00fcllender und harmonischer ist auch der Ausdruck seines Arbeitsverhaltens im Rahmen seines jeweiligen Typspektrums.</p>
      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"essverhalten-der-9-typen", label:"Essverhalten der 9 Typen"},
        {route:"verhaeltnis-zu-geld-der-9-typen", label:"Verh\u00e4ltnis zu Geld"},
        {route:"superpower-der-9-typen", label:"Superpower der 9 Typen"},
      ])}
    </div>
  `);
}

function verhaeltnisZuGeldDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Verh\u00e4ltnis zu Geld der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Geld ist nie nur Geld \u2014 es ist ein Spiegel. Was wir damit machen, wie wir es festhalten oder loslassen, ob es uns Angst macht oder befl\u00fcgelt: All das verr\u00e4t etwas \u00fcber unseren Enneagrammtyp. Jeder Typ bringt seine eigenen Muster, \u00c4ngste und Sehns\u00fcchte in den Umgang mit Geld ein.</p>
      <img src="./assets/verhaeltnis-zu-geld-der-9-typen.jpg" alt="Das Verh\u00e4ltnis zu Geld der 9 Enneagrammtypen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Ordnung und ethische Sorgfalt</h3>
        <p class="vb-intro">Typ 1 sieht Geld oft als Mittel zur Schaffung von Ordnung und Sicherheit. Er ist diszipliniert und sorgf\u00e4ltig im Umgang mit Geld, vermeidet Verschwendung und legt Wert auf eine gerechte und ethische Verwendung von Ressourcen. Der innere Richter des Typs 1 wacht auch \u00fcber das Konto: Wird dieses Geld auf die richtige Art ausgegeben? Kann ich das wirklich verantworten? Diese Haltung macht ihn verl\u00e4sslich und vorausschauend \u2014 manchmal aber auch unn\u00f6tig rigide gegen\u00fcber sich selbst.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Geben als Lebenshaltung</h3>
        <p class="vb-intro">Typ 2 kann dazu neigen, Geld auszugeben, um anderen zu helfen und sich um sie zu k\u00fcmmern. Er findet Erf\u00fcllung darin, Geld f\u00fcr wohlt\u00e4tige Zwecke oder Geschenke auszugeben \u2014 kann aber manchmal Schwierigkeiten damit haben, die eigenen finanziellen Bed\u00fcrfnisse zu priorisieren. Hinter diesem Muster steckt oft die tiefe \u00dcberzeugung: Mein Wert liegt darin, was ich f\u00fcr andere tue. Wer Geld f\u00fcr sich selbst beh\u00e4lt, ist selbsts\u00fcchtig. Die Heilung des Typs 2 liegt auch hier: Geben darf keine Einbahnstra\u00dfe sein.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Erfolg und Status</h3>
        <p class="vb-intro">Typ 3 sieht Geld oft als Symbol f\u00fcr Erfolg und Status. Er ist bereit, hart zu arbeiten, um finanziellen Wohlstand zu erreichen, und investiert gerne in Dinge, die seinen Status und seine Leistung widerspiegeln. Er kann jedoch auch dazu neigen, Geld zu sparen, um langfristige Ziele zu erreichen. F\u00fcr den Leistungsmensch ist Geld weniger Selbstzweck als R\u00fcckmeldung: Es zeigt, dass er angekommen ist, dass seine Arbeit gesehen wird, dass er z\u00e4hlt.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Ambivalenz und Bedeutung</h3>
        <p class="vb-intro">Typ 4 hat oft eine ambivalente Einstellung zu Geld. Er kann Geld als Mittel zur Erf\u00fcllung \u00e4sthetischer und emotionaler Bed\u00fcrfnisse betrachten und neigt dazu, es f\u00fcr einzigartige und bedeutungsvolle Erfahrungen und Objekte auszugeben. Er kann jedoch auch Schwierigkeiten haben, finanziell diszipliniert zu sein. Der \u00c4sthet will, dass Geld Ausdruck seines Inneren ist \u2014 Routine-Ausgaben f\u00fcr Allt\u00e4gliches f\u00fchlen sich f\u00fcr ihn oft bedeutungslos an, w\u00e4hrend ein perfektes Erlebnis oder ein besonderes St\u00fcck jeden Preis wert erscheint.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Sparsamkeit und Unabh\u00e4ngigkeit</h3>
        <p class="vb-intro">Typ 5 ist in der Regel vorsichtig und sparsam im Umgang mit Geld. Er neigt dazu, Geld zu sparen und klug zu investieren, um finanzielle Sicherheit zu gew\u00e4hrleisten. Er bevorzugt es, Geld f\u00fcr Dinge auszugeben, die ihm Wissen und praktische Vorteile bringen. Geld bedeutet f\u00fcr den Denker vor allem eines: Unabh\u00e4ngigkeit. Wer finanziell abgesichert ist, muss nicht auf andere angewiesen sein \u2014 und das ist f\u00fcr den Typ 5 ein zutiefst erstrebenswerter Zustand.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Sicherheit und Vorsorge</h3>
        <p class="vb-intro">Typ 6 hat oft ein sicherheitsorientiertes Verh\u00e4ltnis zu Geld. Er legt Wert auf finanzielle Stabilit\u00e4t und ist vorsichtig bei Investitionen. Er neigt dazu, Geld zu sparen und Risiken zu minimieren, um sich gegen unsichere Zukunftsszenarien abzusichern. Der Skeptiker denkt beim Geld immer ein paar Schritte voraus: Was, wenn etwas schiefl\u00e4uft? Was, wenn das Einkommen wegbricht? Diese Vorsorge ist eine seiner gro\u00dfen St\u00e4rken \u2014 solange sie nicht in l\u00e4hmende Angst \u00fcbergeht.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Freiheit und Erlebnis</h3>
        <p class="vb-intro">Typ 7 genie\u00dft es, Geld f\u00fcr neue Erfahrungen und Vergn\u00fcgungen auszugeben. Er neigt dazu, impulsiv zu sein und f\u00fcr Reisen, Freizeitaktivit\u00e4ten und andere lustvolle Erlebnisse Geld in die Hand zu nehmen. Er kann Schwierigkeiten haben, Geld zu sparen oder langfristige Pl\u00e4ne zu machen. F\u00fcr den Enthusiasten ist Geld Freiheitskapital \u2014 es kauft Optionen, Abenteuer, die n\u00e4chste M\u00f6glichkeit. Der Gedanke, es auf einem Konto liegen zu lassen, f\u00fchlt sich f\u00fcr ihn an wie verschenkte Lebenszeit.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Macht und Unabh\u00e4ngigkeit</h3>
        <p class="vb-intro">Typ 8 sieht Geld als Mittel zur Macht und Unabh\u00e4ngigkeit. Er ist oft erfolgreich im Erwerb von Geld und hat keine Angst, es einzusetzen, um seine Ziele zu erreichen und seine Position zu st\u00e4rken. Er ist entschlossen und selbstbewusst im Umgang mit finanziellen Angelegenheiten. Der Herausforderer verhandelt, investiert und k\u00e4mpft um Ressourcen \u2014 nicht aus Gier, sondern weil Geld f\u00fcr ihn Handlungsf\u00e4higkeit bedeutet. Wer Geld hat, kann gestalten. Wer keines hat, ist abh\u00e4ngig. Und Abh\u00e4ngigkeit ist f\u00fcr den Typ 8 das Schlimmste.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Komfort und Entspanntheit</h3>
        <p class="vb-intro">Typ 9 kann ein entspanntes und oft nachl\u00e4ssiges Verh\u00e4ltnis zu Geld haben. Er legt Wert auf Komfort und kann dazu neigen, Geld f\u00fcr Dinge auszugeben, die ihm ein Gef\u00fchl von Frieden und Wohlbefinden geben. Probleme hat er gegebenenfalls damit, sich auf langfristige finanzielle Ziele zu konzentrieren oder klare finanzielle Entscheidungen zu treffen. Der Vermittler m\u00f6chte keinen Streit \u2014 auch nicht mit dem eigenen Kontostand. Solange es reicht und alles ruhig bleibt, ist er zufrieden. Die Herausforderung liegt darin, sich aktiv um die eigene finanzielle Zukunft zu k\u00fcmmern, auch wenn es unbequem ist.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:1rem;padding:1rem 1.2rem;background:var(--surface-2, rgba(0,0,0,0.04));border-radius:8px;">
        <p style="font-size:0.9rem;color:var(--muted);line-height:1.6;margin:0;"><strong>Anmerkung:</strong> Das Verh\u00e4ltnis zu Geld im Rahmen der 27 Subtypen des Enneagramms kann sich je nach Subtypenvariante (Normaltyp, Verst\u00e4rkungstyp, Kontratyp) entweder entsprechend, verst\u00e4rkt oder auch genau gegenteilig ausdr\u00fccken. Au\u00dferdem spielt der jeweilige Bewusstseinsgrad dabei eine wichtige Rolle. Je bewusster ein Mensch ist, desto erf\u00fcllender und harmonischer ist auch der Ausdruck seines Verh\u00e4ltnisses zu Geld im Rahmen seines jeweiligen Typspektrums.</p>
      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"arbeitsverhalten-der-9-typen", label:"Arbeitsverhalten der 9 Typen"},
        {route:"sexualverhalten-der-9-typen", label:"Sexualverhalten der 9 Typen"},
        {route:"superpower-der-9-typen", label:"Superpower der 9 Typen"},
      ])}
    </div>
  `);
}

function sexualverhaltenDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Sexualverhalten der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Der bekannte Enneagrammlehrer Claudio Naranjo hat das Sexualverhalten im Kontext der Enneagrammtypen untersucht. Jeder Typ bringt seine eigenen charakteristischen Muster, \u00c4ngste und Sehns\u00fcchte in sein Sexualverhalten ein.</p>
      <img src="./assets/sexualverhalten-der-9-typen.jpg" alt="Das Sexualverhalten der 9 Enneagrammtypen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Strukturiert und kontrolliert</h3>
        <p class="vb-intro">Der Typ 1 kann beim Sex nach Perfektion streben, was zu Kontrollverhalten und Selbstkritik f\u00fchren kann. Der Perfektionist bringt seine innere Richterlinie auch in die Intimit\u00e4t mit \u2014 er m\u00f6chte alles richtig machen, den Partner nicht entt\u00e4uschen, keine Fehler begehen. Das kann hemmend wirken, aber auch sehr achtsam: Der Typ 1 kann sich sehr diszipliniert und zugewandt auf das Wohl des Partners konzentrieren, wenn er lernt, den inneren Kritiker zum Schweigen zu bringen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Warmherzig und f\u00fcrsorglich</h3>
        <p class="vb-intro">Der Typ 2 setzt oft den Partner an erste Stelle und kann beim Sex sehr gebend und f\u00fcrsorglich sein. Der Helfer sucht in der Intimit\u00e4t emotionale Best\u00e4tigung und Wertsch\u00e4tzung \u2014 er gibt sich vollst\u00e4ndig hin und hofft, durch dieses Geben Liebe zur\u00fcckzubekommen. Sein Sexualverhalten ist warmherzig und zugewandt, aber oft auch mit einem stillen Bed\u00fcrfnis verbunden: Siehst du, wie sehr ich f\u00fcr dich da bin? Werde ich das zur\u00fcckbekommen?</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Zielgerichtet und effektiv</h3>
        <p class="vb-intro">Der Typ 3 kann Sex als eine Leistung betrachten und strebt danach, als guter Liebhaber wahrgenommen zu werden. Der Leistungsmensch bringt seine Grundorientierung auch ins Schlafzimmer: Er m\u00f6chte gl\u00e4nzen, beeindrucken, der Beste sein. Das kann sehr stimulierend wirken \u2014 aber es birgt auch die Frage, ob hinter der Inszenierung echte Hingabe steckt. Je bewusster der Typ 3, desto mehr l\u00f6st sich die Leistungshaltung auf und macht Platz f\u00fcr echte Verbindung.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Intensiv und emotional</h3>
        <p class="vb-intro">Der Typ 4 erlebt Sexualit\u00e4t oft intensiv und leidenschaftlich, mit einer Tendenz zur Dramatik und emotionaler Tiefe. Der \u00c4sthet sucht in der k\u00f6rperlichen Begegnung nach einer tiefen, bedeutungsvollen Verbindung \u2014 Sexualit\u00e4t ist f\u00fcr ihn kein fl\u00fcchtiger Moment, sondern ein Raum, in dem das Innerste sichtbar wird. Er kann hingebungsvoll und leidenschaftlich sein, braucht aber Echtheit: Oberfl\u00e4chlichkeit oder Routine sind f\u00fcr den Typ 4 das Ende jeder Erotik.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Zur\u00fcckhaltend und analytisch</h3>
        <p class="vb-intro">Der Typ 5 kann distanziert und analytisch an Sexualit\u00e4t herangehen, oft mit einem Bed\u00fcrfnis nach emotionalem Abstand. Der Denker kann Schwierigkeiten haben, sich v\u00f6llig hinzugeben \u2014 er bevorzugt, wenn m\u00f6glich, intellektuelle Intimit\u00e4t. K\u00f6rperliche N\u00e4he erfordert von ihm Vertrauen und Sicherheit, die er sich langsam erarbeitet. Wenn dieser Schritt gelingt, \u00f6ffnet sich hinter der k\u00fchlen Fassade ein Mensch, der mit gro\u00dfer Aufmerksamkeit und Z\u00e4rtlichkeit da sein kann.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Z\u00f6gerlich und unsicher</h3>
        <p class="vb-intro">Der Typ 6 kann beim Sex Unsicherheit und Zweifel erleben, sucht aber gleichzeitig nach Sicherheit und Vertrauen. Der Skeptiker bringt seine Grundangst auch in die Intimit\u00e4t: Bin ich gut genug? Ist das sicher? Kann ich mich fallen lassen? Er kann sexuell z\u00f6gerlich sein und ben\u00f6tigt Best\u00e4tigung und Stabilit\u00e4t vom Partner. Hat er diese Sicherheit gefunden, \u00f6ffnet er sich mit einer Treue und Verl\u00e4sslichkeit, die seinesgleichen sucht.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Spontan und verspielt</h3>
        <p class="vb-intro">Der Typ 7 geht oft spielerisch und abenteuerlustig mit Sexualit\u00e4t um, mit einer Vorliebe f\u00fcr Vielfalt und neue Erfahrungen. Der Enthusiast sieht Sex als Spa\u00df und Vergn\u00fcgen \u2014 er bringt Leichtigkeit, Humor und Entdeckungsfreude mit. Er kann Schwierigkeiten haben, sich zu binden und neigt dazu, Tiefe durch Abwechslung zu ersetzen. Je bewusster der Typ 7, desto mehr entdeckt er, dass die gr\u00f6\u00dfte Freiheit nicht in der Flucht liegt \u2014 sondern im vollst\u00e4ndigen Ankommen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Kraftvoll und dominant</h3>
        <p class="vb-intro">Der Typ 8 hat ein starkes und intensives Sexualverhalten, oft gepr\u00e4gt von Dominanz und Kontrolle. Der Herausforderer kann sehr leidenschaftlich und direkt sein und sucht oft nach Macht und Einfluss in der sexuellen Dynamik. Hinter dieser Intensit\u00e4t steckt aber eine tiefe Sehnsucht: geliebt zu werden, ohne Schw\u00e4che zeigen zu m\u00fcssen. Wem es gelingt, dem Typ 8 diesen sicheren Raum zu geben, erlebt einen Menschen, der sich mit beeindruckender Verletzlichkeit \u00f6ffnen kann.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Sanft und harmonisch</h3>
        <p class="vb-intro">Der Typ 9 hat ein entspanntes und harmonisches Sexualverhalten, das auf die Bed\u00fcrfnisse des Partners eingeht. Der Vermittler neigt dazu, Konflikte zu vermeiden, und sucht nach Frieden und Verbindung in der sexuellen Beziehung. Er kann sich dabei selbst vergessen \u2014 seine eigenen W\u00fcnsche zur\u00fcckstellen, um den anderen gl\u00fccklich zu machen. Je bewusster der Typ 9, desto mehr lernt er, auch die eigene Stimme einzubringen: Verbindung entsteht zwischen zwei Anwesenden, nicht zwischen einem und seinem Echo.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:1rem;padding:1rem 1.2rem;background:var(--surface-2, rgba(0,0,0,0.04));border-radius:8px;">
        <p style="font-size:0.9rem;color:var(--muted);line-height:1.6;margin:0;"><strong>Anmerkung:</strong> Das Sexualverhalten im Rahmen der 27 Subtypen des Enneagramms kann sich je nach Subtypenvariante (Normaltyp, Verst\u00e4rkungstyp, Kontratyp) entweder entsprechend, verst\u00e4rkt oder auch genau gegenteilig ausdr\u00fccken. Au\u00dferdem spielt der jeweilige Bewusstseinsgrad dabei eine wichtige Rolle. Je bewusster ein Mensch ist, desto erf\u00fcllender und harmonischer ist auch der Ausdruck seines Sexualverhaltens im Rahmen seines jeweiligen Typspektrums.</p>
      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"verhaeltnis-zu-geld-der-9-typen", label:"Verh\u00e4ltnis zu Geld"},
        {route:"kussverhalten-der-9-typen", label:"Kussverhalten der 9 Typen"},
        {route:"superpower-der-9-typen", label:"Superpower der 9 Typen"},
      ])}
    </div>
  `);
}

function kussverhaltenDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Kussverhalten der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Der ber\u00fchmte Enneagrammlehrer Claudio Naranjo hat einmal in den 80er-Jahren innerhalb eines Seminars in Berkeley, Californien, eine interessante Perspektive auf das Kussverhalten im Kontext der Enneagrammtypen entwickelt. Laut Naranjo kann das Kussverhalten eines Menschen Einblick in dessen Enneagrammtyp geben.</p>
      <img src="./assets/kussverhalten-der-9-typen.jpg" alt="Das Kussverhalten der 9 Enneagrammtypen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Strukturiert und kontrolliert</h3>
        <p class="vb-intro">Der Typ 1 k\u00fcsst strukturiert und kontrolliert \u2014 m\u00f6glicherweise zur\u00fcckhaltend, um Perfektion zu wahren. F\u00fcr den Perfektionisten ist auch ein Kuss kein spontaner Moment der Hingabe, sondern eine Handlung, die mit Bedacht vollzogen wird. Er bringt sich vollst\u00e4ndig ein, aber auf seine Weise: pr\u00e4zise, respektvoll, ohne \u00fcbergriffige Geste. Der Kuss des Typs 1 ist ein stilles Versprechen \u2014 er dr\u00fcckt nicht Leidenschaft durch Intensit\u00e4t aus, sondern durch Verl\u00e4sslichkeit. Wer von einem Typ 1 gek\u00fcsst wird, sp\u00fcrt: Das meint er ernst.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Warmherzig und f\u00fcrsorglich</h3>
        <p class="vb-intro">Der Typ 2 k\u00fcsst warmherzig und f\u00fcrsorglich \u2014 ein Kuss, der N\u00e4he und Verbundenheit ausdr\u00fcckt. Im Kuss des Helfers steckt das ganze Wesen dieses Typs: Er gibt sich hin, vollst\u00e4ndig und ohne Vorbehalt. Sein Kuss ist eine Umarmung in konzentrierter Form \u2014 er will, dass der andere f\u00fchlt: Du bist willkommen, du bist geliebt, du bist bei mir sicher. Der Typ 2 k\u00fcsst nicht f\u00fcr sich \u2014 er k\u00fcsst f\u00fcr den anderen. Und genau das macht seinen Kuss so unverwechselbar warm.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Zielgerichtet und effektiv</h3>
        <p class="vb-intro">Der Typ 3 k\u00fcsst zielgerichtet und effektiv \u2014 m\u00f6glicherweise etwas demonstrativ. Der Leistungsmensch bringt auch in den intimsten Momenten seine Grundstruktur mit: Er wei\u00df, was er will, und er setzt es um. Sein Kuss ist kein Tastversuch, sondern eine Aussage. Er kann beeindruckend sein \u2014 voller Selbstsicherheit, mit klarer Intention. Und doch liegt die Frage im Raum: K\u00fcsst er, weil er f\u00fchlt \u2014 oder weil er wei\u00df, wie man k\u00fcsst? Je bewusster der Typ 3, desto echter wird die Antwort.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Intensiv und emotional</h3>
        <p class="vb-intro">Der Typ 4 k\u00fcsst intensiv und emotional \u2014 ein Kuss, der Tiefe und Leidenschaft vermittelt. F\u00fcr den \u00c4stheten ist ein Kuss nie Routine. Er ist Ausdruck, Offenbarung, Kunst. Der Typ 4 k\u00fcsst so, wie er f\u00fchlt: mit allem, was er hat. Er bringt die gesamte Tiefe seines Innenlebens in diesen Moment \u2014 die Sehnsucht, die Sch\u00f6nheit, den Schmerz. Wer von einem Typ 4 gek\u00fcsst wird, vergisst es nicht. Es ist kein Kuss unter vielen \u2014 es ist der eine, der z\u00e4hlt.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Zur\u00fcckhaltend und analytisch</h3>
        <p class="vb-intro">Der Typ 5 k\u00fcsst zur\u00fcckhaltend und analytisch \u2014 eher vorsichtig und distanziert. Das bedeutet nicht, dass er nicht f\u00fchlt \u2014 es bedeutet, dass N\u00e4he f\u00fcr ihn kostbar und daher selten ist. Der Denker n\u00e4hert sich auch k\u00f6rperlicher Intimit\u00e4t mit einer gewissen inneren Beobachtung: Was passiert hier? Was bedeutet das? Sein Kuss ist selten, aber wenn er kommt, dann mit Bewusstsein. Und wer geduldig genug ist, die Distanz zu \u00fcberwinden, entdeckt dahinter eine Z\u00e4rtlichkeit, die die wenigsten ahnen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Z\u00f6gerlich und vertrauenssuchend</h3>
        <p class="vb-intro">Der Typ 6 k\u00fcsst z\u00f6gerlich und unsicher \u2014 ein Kuss, der die Suche nach Sicherheit und Vertrauen widerspiegelt. F\u00fcr den Skeptiker ist Intimit\u00e4t immer auch Verletzlichkeit \u2014 und Verletzlichkeit erfordert Vertrauen. Sein Z\u00f6gern ist kein Desinteresse, sondern eine Form der Ehrlichkeit: Er \u00f6ffnet sich nur, wenn er sich sicher f\u00fchlt. Wer den Typ 6 dazu gebracht hat, diesen Schritt zu wagen, hat etwas Seltenes errungen. Und der Kuss, der dann folgt, ist aufrichtig \u2014 ohne Pose, ohne Spiel.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Spontan und verspielt</h3>
        <p class="vb-intro">Der Typ 7 k\u00fcsst spontan und verspielt \u2014 ein Kuss, der Freude und Abenteuerlust zeigt. F\u00fcr den Enthusiasten ist ein Kuss ein Fest \u2014 ungeplant, \u00fcberschw\u00e4nglich, mit einem L\u00e4cheln darin. Er k\u00fcsst, weil der Moment es verlangt, weil es sch\u00f6n ist, weil es ihn freut. Sein Kuss ist selten schwer \u2014 er tr\u00e4gt die Leichtigkeit des Augenblicks in sich. Manchmal fl\u00fcchtig, manchmal mitrei\u00dfend, aber immer lebendig. Wer mit einem Typ 7 k\u00fcsst, k\u00fcsst mit jemandem, der noch nie vergessen hat, wie es sich anf\u00fchlt, das erste Mal.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Kraftvoll und dominant</h3>
        <p class="vb-intro">Der Typ 8 k\u00fcsst kraftvoll und dominant \u2014 ein Kuss, der Intensit\u00e4t und Kontrolle ausdr\u00fcckt. Der Herausforderer bringt in jeden Moment seiner Begegnung mit anderen seine Grundenergie mit: St\u00e4rke, Direktheit, unverstellte Pr\u00e4senz. Sein Kuss ist keine Frage \u2014 er ist eine Aussage. Und doch: Hinter dieser Kraft liegt eine Verletzlichkeit, die der Typ 8 selten zeigt. Wer tief genug schaut, findet in seinem Kuss auch Schutz \u2014 die stille Botschaft: Ich lasse dich nah, weil ich dir vertraue.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Sanft und harmonisch</h3>
        <p class="vb-intro">Der Typ 9 k\u00fcsst sanft und harmonisch \u2014 ein Kuss, der Frieden und Verbindung betont. Der Vermittler bringt in seine Intimit\u00e4t das, was ihn ausmacht: eine tiefe Sehnsucht nach Verbundenheit ohne Spannung, nach N\u00e4he ohne Drama. Sein Kuss ist ein Moment der Stille zu zweit \u2014 weich, ruhig, mit einer W\u00e4rme, die sich langsam ausbreitet. Er will nicht beeindrucken, er will ankommen. Und wer sich darauf einl\u00e4sst, findet in ihm einen der tiefsten K\u00fcsse, die es gibt \u2014 weil er ganz da ist, ohne Agenda.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:1rem;padding:1rem 1.2rem;background:var(--surface-2, rgba(0,0,0,0.04));border-radius:8px;">
        <p style="font-size:0.9rem;color:var(--muted);line-height:1.6;margin:0;"><strong>Anmerkung:</strong> Das Kussverhalten im Rahmen der 27 Subtypen des Enneagramms kann sich je nach Subtypenvariante (Normaltyp, Verst\u00e4rkungstyp, Kontratyp) entweder entsprechend, verst\u00e4rkt oder auch genau gegenteilig ausdr\u00fccken. Au\u00dferdem spielt der jeweilige Bewusstseinsgrad dabei eine wichtige Rolle. Je bewusster ein Mensch ist, desto erf\u00fcllender und harmonischer ist auch der Ausdruck seines Kussverhaltens im Rahmen seines jeweiligen Typspektrums.</p>
      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"sexualverhalten-der-9-typen", label:"Sexualverhalten der 9 Typen"},
        {route:"hochsensibilitaet-der-9-typen", label:"Hochsensibilit\u00e4t der 9 Typen"},
        {route:"superpower-der-9-typen", label:"Superpower der 9 Typen"},
      ])}
    </div>
  `);
}

function hochsensibilitaetDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Hochsensibilit\u00e4t der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Diese Eigenschaften sind bei hochsensiblen Menschen h\u00e4ufig in starker Form ausgepr\u00e4gt, da sich hier die universellen Ur-Prinzipien in einem Menschen \u00fcberm\u00e4\u00dfig einseitig intensiv manifestieren. Diese Qualit\u00e4ten k\u00f6nnen im Einzelfall Segen und Fluch zugleich sein.</p>
      <img src="./assets/hochsensibilitaet-der-9-typen.jpg" alt="Hochsensibilit\u00e4t der 9 Enneagrammtypen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Feinwahrnehmung, Perfektionismus, Gerechtigkeitssinn</h3>
        <p class="vb-intro">Der hochsensible Typ 1 besitzt eine au\u00dfergew\u00f6hnliche F\u00e4higkeit, Feinheiten auf einfache Weise detailreich herauszuh\u00f6ren, wiederzugeben und in Worte zu fassen. Er ist von Natur aus gewissenhaft \u2014 sein innerer Sensor registriert jede Abweichung vom Ideal, jede Ungereimtheit, jede Schieflage. Diese Feinf\u00fchligkeit ist sein gr\u00f6\u00dftes Geschenk: Sie macht ihn zum unbestechlichen Beobachter, zum verl\u00e4sslichen Korrektor, zum Menschen, der Qualit\u00e4t erkennt, bevor andere sie auch nur ahnen. Die Schattenseite ist die innere Ersch\u00f6pfung durch st\u00e4ndige Reizfilterung \u2014 der Typ 1 h\u00f6rt immer alles, auch das, was andere l\u00e4ngst ausgeblendet haben. Segen und Fluch zugleich: wer alles wahrnimmt, kann die Welt verbessern \u2014 und kann sich in ihr nicht erholen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Ausgepr\u00e4gter Altruismus und emotionale Resonanz</h3>
        <p class="vb-intro">Der hochsensible Typ 2 f\u00fchlt und \u00fcbermittelt au\u00dfergew\u00f6hnliche Emotionen mit einer Einf\u00fchlsamkeit, die andere kaum nachvollziehen k\u00f6nnen. Er erkennt fremde Gef\u00fchle, bevor sie ausgesprochen werden \u2014 ein Blick, eine K\u00f6rperhaltung, eine Pause im Gespr\u00e4ch reichen ihm, um zu wissen, was der andere gerade braucht. Diese Qualit\u00e4t macht ihn zum nat\u00fcrlichen Helfer, Tr\u00f6ster und emotionalen Anker f\u00fcr andere. Die Kehrseite: Er saugt die Emotionen seiner Umgebung auf wie ein Schwamm und tr\u00e4gt oft Gef\u00fchle, die gar nicht seine eigenen sind \u2014 ohne zu wissen, wo die Grenze zwischen ihm und dem anderen verl\u00e4uft. Segen und Fluch: wer alles f\u00fchlt, kann heilen \u2014 und kann sich selbst dabei verlieren.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Intensives emotionales Ersp\u00fcren in Beziehungen</h3>
        <p class="vb-intro">Der hochsensible Typ 3 nimmt Beziehungen und Reize tief und emotional intensiv wahr \u2014 weit mehr, als sein nach au\u00dfen oft k\u00fchl wirkendes Auftreten vermuten l\u00e4sst. Hinter der Fassade des Erfolgsorientierten lebt ein Mensch, der Verbindungen mit gro\u00dfer Intensit\u00e4t erlebt und auf emotionale Signale in seinem sozialen Umfeld \u00e4u\u00dferst fein reagiert. Diese Sensibilit\u00e4t erm\u00f6glicht ihm ein intuitives Gesp\u00fcr f\u00fcr die Dynamiken zwischen Menschen \u2014 er liest R\u00e4ume, bevor andere die T\u00fcr aufgemacht haben. Die Gefahr: Er \u00fcberarbeitet sich, weil er die emotionale Last seiner Umgebung sp\u00fcrt und gleichzeitig nach au\u00dfen St\u00e4rke zeigen will. Segen und Fluch: wer alles ersp\u00fcrt und trotzdem liefert, kann Gro\u00dfes bewegen \u2014 und brennt dabei von innen aus.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Empathie und langer emotionaler Nachklang</h3>
        <p class="vb-intro">Der hochsensible Typ 4 ist sehr empathisch und kann seine Mitmenschen auf einer Tiefe verstehen, die anderen verschlossen bleibt. Erlebnisse klingen in ihm lange nach \u2014 Musik, Kunst, Begegnungen, Trennungen hinterlassen Spuren, die sich nicht einfach aufl\u00f6sen. Diese Tiefe ist sein k\u00fcnstlerisches Kapital: Sie speist seine Kreativit\u00e4t, seine Ausdruckskraft, seine F\u00e4higkeit, das Unsagbare in Sprache oder Bild zu verwandeln. Die Schattenseite ist die emotionale \u00dcberflutung: Was andere als vergangen abhaken, lebt im Typ 4 weiter \u2014 manchmal als Sch\u00f6nheit, manchmal als Schmerz, oft als beides gleichzeitig. Segen und Fluch: wer so tief f\u00fchlt, kann Kunst schaffen, die Menschen ber\u00fchrt \u2014 und findet selbst keinen Abschalter.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Langzeitged\u00e4chtnis und systemisches Denken</h3>
        <p class="vb-intro">Der hochsensible Typ 5 besitzt ein sehr ausgepr\u00e4gtes Langzeitged\u00e4chtnis und die F\u00e4higkeit, in gr\u00f6\u00dferen Zusammenh\u00e4ngen zu denken \u2014 er ist ein tiefsinniger Denker mit ausgepr\u00e4gten, weitverzweigten Gedankeng\u00e4ngen. Er verkn\u00fcpft Informationen, die andere l\u00e4ngst vergessen haben, zu neuen Mustern und Erkenntnissen. Diese Qualit\u00e4t macht ihn zum Analytiker, Forscher, Vision\u00e4r. Die Kehrseite: Er ist reiz\u00fcberflutet in einer Welt, die st\u00e4ndig auf ihn einprasselt, und zieht sich daher weit zur\u00fcck \u2014 nicht aus K\u00e4lte, sondern aus dem tiefen Bed\u00fcrfnis nach Stille, um \u00fcberhaupt denken zu k\u00f6nnen. Segen und Fluch: wer so weit denkt, kann Zusammenh\u00e4nge erkennen, die andere nie sehen \u2014 und braucht daf\u00fcr eine Einsamkeit, die nicht jeder versteht.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Vertrauen und Sicherheit schaffend</h3>
        <p class="vb-intro">Der hochsensible Typ 6 ist sehr zuverl\u00e4ssig, hilfsbereit und freundschaftlich-loyal \u2014 ein Mensch, in dessen N\u00e4he andere sich sicher f\u00fchlen, weil er Vertrauen nicht nur verspricht, sondern verk\u00f6rpert. Sein feines Gesp\u00fcr f\u00fcr Risiken, Unstimmigkeiten und versteckte Gefahren macht ihn zum nat\u00fcrlichen W\u00e4chter und Vertrauensanker in Gruppen. Er bemerkt, wenn etwas nicht stimmt \u2014 lange bevor es offensichtlich wird. Die Schattenseite: Diese Wachheit ersch\u00f6pft ihn. Ein hochsensibler Typ 6 tr\u00e4gt die Sorgen seiner Umgebung mit, auch wenn niemand ihn darum gebeten hat. Segen und Fluch: wer so wachsam ist, h\u00e4lt Gemeinschaften zusammen \u2014 und findet selbst kaum einen Moment echter Ruhe.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Begeisterungsf\u00e4higkeit, Fantasie und Schmerzempfindlichkeit</h3>
        <p class="vb-intro">Der hochsensible Typ 7 ist optimistisch, lacht und weint leicht und besitzt eine erh\u00f6hte Schmerzempfindlichkeit \u2014 er lebt an der Oberfl\u00e4che der Gef\u00fchle mit einer Intensit\u00e4t, die andere mitrei\u00dft. Seine hohe Begeisterungsf\u00e4higkeit, seine vielseitigen Interessen und seine gro\u00dfe Fantasie machen ihn zum kreativen Motor in jedem Umfeld. Er entz\u00fcndet sich an Ideen und entz\u00fcndet andere damit. Die Kehrseite: Er f\u00fchlt Schmerz \u2014 k\u00f6rperlich wie seelisch \u2014 mit einer Unmittelbarkeit, die ihn manchmal \u00fcberrollt. Sein Optimismus ist oft auch eine Schutzstrategie gegen das, was er so intensiv wahrnimmt. Segen und Fluch: wer so hell brennt, beleuchtet alles um sich herum \u2014 und braucht viel Raum, um sich zu erholen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Psychische Stabilit\u00e4t und Selbstst\u00e4ndigkeit</h3>
        <p class="vb-intro">Der hochsensible Typ 8 ist meist psychisch sehr stabil, sehr selbstst\u00e4ndig und f\u00fchlt sich auch dann gut, wenn er alleine ist \u2014 er braucht keine Best\u00e4tigung von au\u00dfen, um sich seiner selbst sicher zu sein. Diese innere Festigkeit ist seine besondere Form der Hochsensibilit\u00e4t: W\u00e4hrend andere in emotionalen St\u00fcrmen schwanken, bleibt er geerdet. Gleichzeitig nimmt er Ungerechtigkeit, Schw\u00e4che und Bedrohung mit einer Unmittelbarkeit wahr, die ihn sofort in Aktion versetzt. Sein K\u00f6rpergef\u00fchl ist intensiv \u2014 er sp\u00fcrt sich und seine Grenzen sehr klar. Segen und Fluch: wer so geerdet ist, kann anderen Halt geben \u2014 und \u00fcbersieht dabei manchmal die eigene Verletzlichkeit, die tief im Inneren verborgen liegt.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Stille, Wesentlichkeit und verbindende Pr\u00e4senz</h3>
        <p class="vb-intro">Der hochsensible Typ 9 sucht oft die Stille und kann auf einfache Weise das Wesentliche erkennen \u2014 er verf\u00fcgt \u00fcber ein ausgepr\u00e4gtes Harmoniebed\u00fcrfnis und ist sehr vermittelnd, freundlich und verbindend. Unter all dem L\u00e4rm der Welt h\u00f6rt er, was wirklich wichtig ist. Diese stille Wahrnehmung macht ihn zum nat\u00fcrlichen Vermittler: Er sieht alle Perspektiven gleichzeitig und kann Br\u00fccken bauen, wo andere nur Gr\u00e4ben sehen. Die Kehrseite: Reiz\u00fcberflutung trifft ihn hart \u2014 er zieht sich dann in sich zur\u00fcck und wirkt abwesend, obwohl er eigentlich nur \u00fcberfordert ist. Segen und Fluch: wer das Wesentliche so klar sieht, kann Frieden stiften \u2014 und verliert dabei manchmal seine eigene Mitte aus dem Blick.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"kussverhalten-der-9-typen", label:"Kussverhalten der 9 Typen"},
        {route:"superpower-der-9-typen", label:"Superpower der 9 Typen"},
        {route:"empfindliche-punkte", label:"Empfindliche Punkte"},
      ])}
    </div>
  `);
}

function superpowerDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Superpower der 9 Typen", "Schaubilder \u00b7 Spirituelle Sicht")}
      <p class="psycho-intro">Suche nicht mehr im Au\u00dfen nach deinem vermeintlichen Gl\u00fcck \u2014 erkenne dein Verlangen (deine Kernmotivation), im Au\u00dfen nach dir selbst zu suchen. Indem du dir deiner intrinsischen Motivation nach und nach immer bewusster wirst, erkennst du den verzweifelten Versuch deiner Egostruktur und gibst ihn auf: den Holzweg, auf dem Rahmen der \u00e4u\u00dferen Lebensumst\u00e4nde Liebe zu erhalten, dabei aber genau das Gegenteil zu bewirken.</p>
      <img src="./assets/superpower-der-9-typen.jpg" alt="Superpower der 9 Enneatypen aus spiritueller Sicht \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Superpower: Wahre Perfektion</h3>
        <p class="vb-intro">Erkenne, dass die wahre Perfektion bereits hier und jetzt in dir liegt \u2014 denn das ist deine wahre innere St\u00e4rke. Der Typ 1 sucht Vollkommenheit im Au\u00dfen: in Regeln, Strukturen, Korrektheit. Die spirituelle Erkenntnis ist, dass diese Vollkommenheit keine Leistung ist, die erarbeitet werden muss, sondern eine Qualit\u00e4t, die bereits da ist \u2014 im Moment, in der Stille, im Sein. Perfektion ist nicht das Ergebnis von Verbesserung, sondern die Natur des Wesens selbst. Wenn der Typ 1 aufh\u00f6rt, die Welt zu korrigieren, und anf\u00e4ngt, sie so zu sehen wie sie ist, entdeckt er in jedem Augenblick eine Ordnung, die er nie h\u00e4tte erschaffen k\u00f6nnen. Das ist seine Superpower: die F\u00e4higkeit, das Vollkommene im Unvollkommenen zu erkennen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Superpower: Wahre Liebe</h3>
        <p class="vb-intro">Erkenne, dass die wahre Liebe bereits hier und jetzt in dir liegt \u2014 denn das ist deine wahre innere St\u00e4rke. Der Typ 2 sucht Liebe durch Geben, durch Gebrauchtwerden, durch das Spiegeln im Dankblick des anderen. Die spirituelle Erkenntnis ist, dass Liebe nicht verdient werden muss \u2014 sie ist die Substanz, aus der er gemacht ist. Wenn der Typ 2 aufh\u00f6rt, Liebe durch F\u00fcrsorge zu gewinnen, und beginnt, sie als seinen eigentlichen Wesenskern zu erkennen, wird seine F\u00fcrsorge frei: kein Tausch mehr, sondern reines Str\u00f6men. Das ist seine Superpower: Liebe nicht als Mittel, sondern als Ursprung.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Superpower: Wahrer Erfolg</h3>
        <p class="vb-intro">Erkenne, dass der wahre Erfolg bereits hier und jetzt in dir liegt \u2014 denn das ist deine wahre innere St\u00e4rke. Der Typ 3 misst seinen Wert am Ergebnis: an Titeln, Anerkennung, sichtbarem Vorankommen. Die spirituelle Erkenntnis ist, dass der Wert des Menschen nicht erarbeitet werden kann, weil er nicht verloren gegangen ist. Wenn der Typ 3 aufh\u00f6rt, sich durch Leistung zu beweisen, und beginnt, aus seinem Wert heraus zu handeln, wird sein Tun kraftvoller, echter und nachhaltiger. Das ist seine Superpower: Erfolg nicht als Ziel, sondern als nat\u00fcrlicher Ausdruck des inneren Reichtums.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Superpower: Wahre Individualit\u00e4t</h3>
        <p class="vb-intro">Erkenne, dass die wahre Individualit\u00e4t bereits hier und jetzt in dir liegt \u2014 denn das ist deine wahre innere St\u00e4rke. Der Typ 4 sucht sich selbst in der Tiefe der Gef\u00fchle, in der Einzigartigkeit der Erfahrung, in der Sehnsucht nach dem, was fehlt. Die spirituelle Erkenntnis ist, dass er nicht einzigartig werden muss \u2014 er ist es, unrettbar und unwiderruflich. Keine Arbeit an sich selbst macht ihn mehr zu dem, was er schon ist. Wenn der Typ 4 aufh\u00f6rt, seine Unverwechselbarkeit zu suchen und anf\u00e4ngt, sie einfach zu verk\u00f6rpern, entsteht Kunst, die bewegt. Das ist seine Superpower: Einzigartigkeit als Geschenk, nicht als Aufgabe.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Superpower: Wahres Wissen</h3>
        <p class="vb-intro">Erkenne, dass das wahre Wissen bereits hier und jetzt in dir liegt \u2014 denn das ist deine wahre innere St\u00e4rke. Der Typ 5 sammelt Wissen als Schutz: Je mehr er versteht, desto sicherer f\u00fchlt er sich in einer Welt, die er als fordernd und ersch\u00f6pfend erlebt. Die spirituelle Erkenntnis ist, dass das tiefste Wissen nicht aus B\u00fcchern kommt, sondern aus der direkten Erfahrung des Bewusstseins selbst. Wenn der Typ 5 aufh\u00f6rt, Wissen zu akkumulieren, und beginnt, sich dem unmittelbaren Erleben zu \u00f6ffnen, entdeckt er eine Intelligenz, die gr\u00f6\u00dfer ist als jedes Konzept. Das ist seine Superpower: Wissen als lebendige Gegenwart, nicht als Archiv.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Superpower: Wahre Sicherheit</h3>
        <p class="vb-intro">Erkenne, dass die wahre Sicherheit bereits hier und jetzt in dir liegt \u2014 denn das ist deine wahre innere St\u00e4rke. Der Typ 6 sucht Sicherheit in Strukturen, Autorit\u00e4t, Vertr\u00e4gen und treuen Verb\u00fcndeten \u2014 in allem, was verl\u00e4sslich erscheint. Die spirituelle Erkenntnis ist, dass keine \u00e4u\u00dfere Sicherheit je vollst\u00e4ndig sein kann, weil das Leben selbst unvorhersehbar ist. Die einzige Sicherheit, die nicht weggenommen werden kann, ist die des eigenen Grundes \u2014 die stille Gewissheit im Inneren, die bleibt, wenn alles andere sich ver\u00e4ndert. Das ist seine Superpower: Vertrauen nicht als Naivit\u00e4t, sondern als innere Verankerung.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Superpower: Wahre Lebensfreude</h3>
        <p class="vb-intro">Erkenne, dass die wahre Lebensfreude bereits hier und jetzt in dir liegt \u2014 denn das ist deine wahre innere St\u00e4rke. Der Typ 7 sucht Freude im n\u00e4chsten Erlebnis, im n\u00e4chsten Plan, im n\u00e4chsten Horizont \u2014 immer ein Schritt vor der Gegenwart. Die spirituelle Erkenntnis ist, dass Freude kein Ziel ist, das man erreichen kann, sondern die Natur des Bewusstseins selbst im Zustand der Offenheit. Wenn der Typ 7 aufh\u00f6rt zu suchen und beginnt, sich dem jetzigen Moment vollst\u00e4ndig hinzugeben, findet er dort eine Freude, die keine \u00e4u\u00dfere Ursache braucht. Das ist seine Superpower: Lebensfreude als Grundton, nicht als Errungenschaft.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Superpower: Wahre Macht</h3>
        <p class="vb-intro">Erkenne, dass die wahre Macht bereits hier und jetzt in dir liegt \u2014 denn das ist deine wahre innere St\u00e4rke. Der Typ 8 sucht Macht durch Kontrolle, Einfluss und die F\u00e4higkeit, die Welt zu gestalten \u2014 er will nicht abh\u00e4ngig sein, nicht ausgeliefert. Die spirituelle Erkenntnis ist, dass die gr\u00f6\u00dfte Macht nicht die Kontrolle \u00fcber andere ist, sondern die Herrschaft \u00fcber sich selbst: die F\u00e4higkeit, inmitten von Chaos ruhig zu bleiben, inmitten von Verlockung weise zu entscheiden. Wenn der Typ 8 aufh\u00f6rt, St\u00e4rke zu demonstrieren und beginnt, sie zu sein, entsteht eine Autorit\u00e4t, die keine Lautst\u00e4rke braucht. Das ist seine Superpower: Macht aus dem Inneren heraus, nicht \u00fcber das Au\u00dfen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Superpower: Wahre Harmonie</h3>
        <p class="vb-intro">Erkenne, dass die wahre Harmonie bereits hier und jetzt in dir liegt \u2014 denn das ist deine wahre innere St\u00e4rke. Der Typ 9 sucht Harmonie durch Anpassung, Konfliktmeidung und das stille Verschmelzen mit dem, was andere brauchen. Die spirituelle Erkenntnis ist, dass Harmonie kein Zustand ist, der durch Nachgeben hergestellt werden muss \u2014 sie ist die Grundschwingung des Seins selbst. Wenn der Typ 9 aufh\u00f6rt, sich selbst aufzul\u00f6sen, um Frieden zu schaffen, und beginnt, aus seinem eigenen Zentrum heraus zu leben, tr\u00e4gt er eine Stille in sich, die andere tats\u00e4chlich befriedet \u2014 nicht durch Anpassung, sondern durch Pr\u00e4senz. Das ist seine Superpower: Harmonie als inneres Sein, das ausstrahlt.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"hochsensibilitaet-der-9-typen", label:"Hochsensibilit\u00e4t der 9 Typen"},
        {route:"wolkenformationen-der-9-typen", label:"Wolkenformationen der 9 Typen"},
        {route:"gifte-des-geistes", label:"Gifte des Geistes"},
      ])}
    </div>
  `);
}

function wolkenformationenDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Wolkenformationen der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Die Zuordnung von neun Wolkenformationen zu den neun Enneagrammprinzipien ist eine kreative Methode, um die vielf\u00e4ltigen Aspekte und Charakteristika dieser Wolken und deren Merkmale mit den verschiedenen Pers\u00f6nlichkeitstypen des Enneagramms zu verbinden. Der Himmel spiegelt in seinen unz\u00e4hligen Formen das gesamte Spektrum menschlicher Wesensarten \u2014 von klarer Struktur bis zur stillen Decke aus Gleichmut.</p>
      <img src="./assets/wolkenformationen-der-9-typen.jpg" alt="Wolkenformationen der 9 Typen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Cumuluswolken: Ordnung und moralische Integrit\u00e4t</h3>
        <p class="vb-intro">Cumuluswolken sind oft symmetrisch und gut definiert, was dem Streben des Perfektionisten nach Ordnung und Klarheit entspricht. Sie symbolisieren die hohe moralische Integrit\u00e4t und die Strebsamkeit von Typ 1. Die Cumuluswolke ist die Bilderbuch-Wolke: klar umrissen, wei\u00df leuchtend, in die H\u00f6he strebend. Sie entsteht durch aufsteigende Warmluft, die sich zu einem klar definierten K\u00f6rper formt \u2014 Chaos, das sich selbst Struktur gibt. Meteorologen nutzen Cumuluswolken als verl\u00e4ssliche Indikatoren: An ihrer Form l\u00e4sst sich das Wetter des Tages ablesen. Sie l\u00fcgen nicht. Die Leidenschaft des Zorns zeigt sich als innere Spannung, wenn der Horizont unordentlich wird und die Konturen verschwimmen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Strato-Cumuluswolken: F\u00fcrsorge und Geborgenheit</h3>
        <p class="vb-intro">Stratocumuluswolken sind oft gro\u00dffl\u00e4chig und geben ein Gef\u00fchl von Schutz und Geborgenheit \u2014 \u00e4hnlich wie der Helfer, der sich um das Wohl anderer k\u00fcmmert und Unterst\u00fctzung bietet. Stratocumuluswolken bedecken den Himmel in weichen, ineinandergreifenden Schichten \u2014 keine Kante, keine Sch\u00e4rfe, alles flie\u00dft ineinander. Sie sind die h\u00e4ufigste Wolkenform der Erde: Millionen Quadratkilometer Himmel werden t\u00e4glich von ihnen bedeckt, ein stilles Dach \u00fcber der Welt. Unter ihnen f\u00fchlt sich der Tag ged\u00e4mpft und geborgen an. Die Leidenschaft des Stolzes zeigt sich als das tiefe Bed\u00fcrfnis, die sch\u00fctzende Schicht zu sein, die andere vor der K\u00e4lte bewahrt.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Altocumuluswolken: Effizienz und Anerkennung</h3>
        <p class="vb-intro">Altocumuluswolken sind in regelm\u00e4\u00dfigen Mustern angeordnet und k\u00f6nnen auf sonnige, klare Tage hindeuten. Sie repr\u00e4sentieren den Erfolgsorientierten, der durch seine Effizienz und Zielstrebigkeit besticht und ein hohes Ma\u00df an Anerkennung anstrebt. Altocumuluswolken bilden in mittlerer H\u00f6he pr\u00e4zise Reihen und Muster \u2014 das sogenannte \u201eSch\u00e4fchenwolken"-Muster, das Meteorologen als Zeichen atmosph\u00e4rischer Stabilit\u00e4t und geordneter Str\u00f6mungen lesen. Sie sind \u00e4sthetisch, geordnet und k\u00fcndigen in ihrer Regelm\u00e4\u00dfigkeit oft gutes Wetter an. Die Leidenschaft der Eitelkeit zeigt sich als Freude daran, ein sch\u00f6nes, geordnetes Bild zu abgeben \u2014 das Muster, das alle bewundern.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Lenticulariswolken: Einzigartigkeit und innere Tiefe</h3>
        <p class="vb-intro">Lenticulariswolken sind selten und besitzen eine ungew\u00f6hnliche, oft linsenf\u00f6rmige Erscheinung. Diese einzigartigen Wolken spiegeln die Besonderheit und Kreativit\u00e4t des Individualisten wider, der sich von der Masse abheben m\u00f6chte. Lenticulariswolken entstehen, wenn Luftstr\u00f6mungen auf Berge oder Gebirgsz\u00fcge treffen und in stehenden Wellen oszillieren \u2014 das Ergebnis sind linsenf\u00f6rmige, glatte, manchmal mehrst\u00f6ckige Gebilde, die so aussehen, als w\u00e4ren sie gemalt. Sie bewegen sich nicht, obwohl der Wind durch sie hindurchbl\u00e4st. Piloten meiden sie wegen extremer Turbulenzen in ihrem Inneren. Die Leidenschaft des Neids zeigt sich als der Wunsch, so unverwechselbar zu sein wie diese Wolke \u2014 gesehen, aber nicht erkl\u00e4rt.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Cirruswolken: Distanz und analytische Klarheit</h3>
        <p class="vb-intro">Cirruswolken sind hoch am Himmel und oft fein und faserig. Sie symbolisieren den Beobachter, der analytisch ist und seine Gedanken oft in h\u00f6here Sph\u00e4ren lenkt. Cirruswolken existieren in H\u00f6hen von acht bis dreizehn Kilometern \u2014 dort, wo die meisten anderen Wolken nicht mehr existieren k\u00f6nnen. Sie bestehen nicht aus Wassertropfen, sondern aus winzigen Eiskristallen, die das Sonnenlicht in feinen Schleiern brechen. Von dort oben ist der Blick klar und weit. Cirruswolken k\u00fcndigen oft Wetterver\u00e4nderungen an, die erst Tage sp\u00e4ter eintreten \u2014 ein Wissen, das nur aus der Distanz m\u00f6glich ist. Die Leidenschaft des Geizes zeigt sich als Sparsamkeit mit N\u00e4he: sch\u00f6n anzuschauen, aber unerreichbar.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Nimbostratuswolken: Loyalit\u00e4t und Verl\u00e4sslichkeit</h3>
        <p class="vb-intro">Nimbostratuswolken sind weit verbreitet, oft verbunden mit lang anhaltendem Regen. Sie symbolisieren die Best\u00e4ndigkeit und Verl\u00e4sslichkeit des Loyalisten, der auch in schwierigen Zeiten standh\u00e4lt, auch wenn die Umst\u00e4nde schwierig sind. Nimbostratuswolken bedecken den gesamten Himmel in einem einheitlichen, dichten Grau \u2014 keine L\u00fccken, keine Variation, kein Ende in Sicht. Sie bringen keinen dramatischen Sturzregen, sondern anhaltenden, gleichm\u00e4\u00dfigen Dauerregen \u2014 stundenlang, manchmal tagelang. Man kann sich auf sie verlassen: Wenn Nimbostratus da ist, bleibt er. Die Leidenschaft der Angst zeigt sich als das Gef\u00fchl, den Himmel im Blick behalten zu m\u00fcssen \u2014 was, wenn der Regen nicht aufh\u00f6rt?</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Cumulonimbuswolken: Energie und Abenteuerlust</h3>
        <p class="vb-intro">Cumulonimbuswolken sind beeindruckend und energetisch, oft verbunden mit heftigen Wetterph\u00e4nomenen. Sie repr\u00e4sentieren den Enthusiasten, der lebendig, abenteuerlustig und auf der Suche nach neuen Erfahrungen ist. Der Cumulonimbus ist die gr\u00f6\u00dfte Wolkenformation der Erde: Er reicht von wenigen Hundert Metern \u00fcber dem Boden bis in die Stratosph\u00e4re \u2014 bis zu 18 Kilometer hoch. In seinem Inneren toben Aufwinde von \u00fcber 200 km/h, es blitzt und donnert, Hagelk\u00f6rner bilden sich und schmelzen und formen sich erneut. Der Cumulonimbus ist das Gegenteil von Stille: Er ist Spektakel, Energie, Verwandlung. Die Leidenschaft der V\u00f6llerei zeigt sich als uners\u00e4ttliche Aufw\u00e4rtsbewegung.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Wall Clouds (Mauerwolken): Macht und Durchsetzungsf\u00e4higkeit</h3>
        <p class="vb-intro">Wall Clouds sind tiefh\u00e4ngende, bedrohlich wirkende Wolken, die oft starke Wetterereignisse ank\u00fcndigen. Sie symbolisieren die Macht und Durchsetzungsf\u00e4higkeit des Herausforderers, der konfrontativ und stark ist. Mauerwolken entstehen an der Basis von Superzellen-Gewittern \u2014 rotierenden Sturmsystemen, die zu den m\u00e4chtigsten Wetterph\u00e4nomenen der Erde geh\u00f6ren. Sie h\u00e4ngen tief und dunkel herab, oft mit sichtbarer Rotation, als w\u00fcrde der Himmel selbst eine Faust ballen. Ihr Erscheinen ist ein unmissverst\u00e4ndliches Signal: Hier kommt etwas, das keiner aufhalten kann. Die Leidenschaft der Gier zeigt sich als Wille, die gesamte atmosph\u00e4rische Energie in sich zu konzentrieren.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Stratuswolken: Harmonie und stille Ausgeglichenheit</h3>
        <p class="vb-intro">Stratuswolken sind gleichm\u00e4\u00dfig und bedecken oft den gesamten Himmel, was ein Gef\u00fchl von Stabilit\u00e4t vermittelt. Sie repr\u00e4sentieren den Friedensstifter, der nach Harmonie und Ausgeglichenheit strebt. Stratuswolken sind die ruhigsten aller Wolken: eine gleichm\u00e4\u00dfige, niedrige Schicht, die den Himmel wie eine weiche Decke bedeckt \u2014 kein Drama, keine Konturen, keine Bewegung. Sie bringen h\u00f6chstens feinen Nieselregen oder Nebel. Unter Stratuswolken wird die Welt leise: kein harter Schatten, kein grelles Licht, alles ist diffus und gleichm\u00e4\u00dfig erhellt. Die Leidenschaft der Tr\u00e4gheit zeigt sich als der tiefe Wunsch, diese Decke zu sein \u2014 alles zu d\u00e4mpfen, alles zu gl\u00e4tten, nichts eskalieren zu lassen.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"superpower-der-9-typen", label:"Superpower der 9 Typen"},
        {route:"wolfsarten-der-9-typen", label:"Wolfsarten der 9 Typen"},
        {route:"eulenarten-der-9-typen", label:"Eulenarten der 9 Typen"},
      ])}
    </div>
  `);
}

function wolfsartenDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Wolfsarten der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Die Zuordnung von neun Wolfsarten zu den neun Enneagrammprinzipien ist eine kreative Methode, um die vielf\u00e4ltigen Aspekte und Charakteristika dieser W\u00f6lfe und deren Merkmale mit den verschiedenen Pers\u00f6nlichkeitstypen des Enneagramms zu verbinden. Der Wolf steht seit Urzeiten f\u00fcr Instinkt, Gemeinschaft und innere St\u00e4rke \u2014 jede Art auf ihre ganz eigene Weise.</p>
      <img src="./assets/wolfsarten-der-9-typen.jpg" alt="Wolfsarten der 9 Typen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Grauwolf: Ordnung und Struktur im Rudel</h3>
        <p class="vb-intro">Der Grauwolf zeigt ein starkes Territorialverhalten und soziale Hierarchie innerhalb des Rudels, was auf eine Ordnung und Struktur hinweist, die dem Typ 1 sehr \u00e4hnlich ist. Der Grauwolf ist der Architekt des Rudels: Er kennt die Grenzen seines Reviers auf den Meter genau, markiert sie regelm\u00e4\u00dfig und verteidigt sie konsequent. Die Hierarchie im Rudel ist klar geregelt \u2014 nicht durch rohe Gewalt, sondern durch eine soziale Ordnung, die alle anerkennen. Grauw\u00f6lfe fressen zuletzt und trinken zuerst nur, wenn die Situation es erlaubt: Pflicht vor Privileg. Die Leidenschaft des Zorns zeigt sich als innere Spannung, wenn Ordnung und Gerechtigkeit verletzt werden.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Polarwolf: F\u00fcrsorge und kooperatives Miteinander</h3>
        <p class="vb-intro">Der Polarwolf lebt in extremen Umgebungen und zeigt starkes kooperatives Verhalten innerhalb des Rudels \u2014 was dem Bed\u00fcrfnis von Typ 2 entspricht, f\u00fcr andere zu sorgen. Der Polarwolf \u00fcberlebt die Arktis nur durch radikale Kooperation: Die gesamte Gruppe k\u00fcmmert sich gemeinsam um den Nachwuchs, teilt Beute auch mit schw\u00e4cheren Rudelmitgliedern und h\u00e4lt auch bei extremem Frost zusammen. Jeder im Rudel hat eine Rolle, aber niemand wird allein gelassen. Der Polarwolf ist wei\u00df wie Schnee \u2014 kein Versteck, volle Sichtbarkeit: Ich bin hier, ich helfe, ich geh\u00f6re dazu. Die Leidenschaft des Stolzes zeigt sich als tiefer Wunsch, unverzichtbar f\u00fcr das \u00dcberleben anderer zu sein.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Rotwolf: Anpassungsf\u00e4higkeit und \u00dcberlebenswille</h3>
        <p class="vb-intro">Der Rotwolf ist bekannt f\u00fcr seine Anpassungsf\u00e4higkeit und \u00dcberlebensf\u00e4higkeiten, was den Erfolg und die Anerkennung widerspiegelt, die den Typ 3 antreiben. Der Rotwolf ist einer der seltensten W\u00f6lfe der Welt \u2014 und ein Meister der Anpassung. Er hat Jahrhunderte der Verfolgung \u00fcberlebt, indem er sein Verhalten, sein Revier und seine Jagdstrategie der jeweiligen Situation anpasste. Heute existiert er fast nur noch in Gefangenschaftszuchtprogrammen \u2014 ein Zeuge davon, wie weit \u00dcberlebenswille reichen kann. Der Rotwolf sucht keine Konfrontation, er findet Wege. Die Leidenschaft der Eitelkeit zeigt sich als Identifikation mit dem eigenen Erfolg \u2014 der Wille, trotz allem zu bestehen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 M\u00e4hnenwolf: Einzigartigkeit und seltenes Wesen</h3>
        <p class="vb-intro">Der M\u00e4hnenwolf zeichnet sich durch sein markantes Aussehen, seine spezielle Lebensweise und sein sehr individuelles Verhalten aus \u2014 was der Besonderheit von Typ 4 entspricht. Der M\u00e4hnenwolf ist kein echter Wolf und kein Fuchs \u2014 er ist einzigartig: die einzige Art seiner Gattung. Mit langen schwarzen Beinen, rotbraunem Fell und einer schwarzen M\u00e4hne ist er unverwechselbar. Er lebt als Einzelg\u00e4nger in den Cerrado-Savannen Brasiliens und streift weitr\u00e4umig und allein durch sein Territorium. Er meidet andere M\u00e4hnenw\u00f6lfe, au\u00dfer zur Paarungszeit. Die Leidenschaft des Neids zeigt sich als Sehnsucht nach tiefer Verbindung bei gleichzeitigem Festhalten an der eigenen Andersartigkeit.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Arabischer Wolf: R\u00fcckzug und stille Beobachtung</h3>
        <p class="vb-intro">Der arabische Wolf lebt in extremen W\u00fcstenregionen und zeigt ein zur\u00fcckhaltendes Verhalten, das dem Typ 5 entspricht. Der Arabische Wolf ist der kleinste Wolf der Welt \u2014 und der einsamste. Er lebt meist als Einzelg\u00e4nger oder in kleinen Paaren in den W\u00fcsten der Arabischen Halbinsel und Israels, und hat sich an Hitze und Trockenheit angepasst wie kein anderer Canide. Er jagt nachts, h\u00e4lt sich tags\u00fcber verborgen und braucht wenig, um zu \u00fcberleben: minimale Ressourcen, maximale Effizienz. Die Leidenschaft des Geizes zeigt sich als \u00e4u\u00dferste Sparsamkeit mit allem \u2014 Energie, Raum, Vertrauen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Eurasischer Wolf: Loyalit\u00e4t und Rudelzusammenhalt</h3>
        <p class="vb-intro">Der eurasische Wolf zeigt innerhalb des Rudels starke soziale Bindungen, gro\u00dfe Loyalit\u00e4t, gute Zusammenarbeit und ein intensives Sicherheitsverhalten, sehr \u00e4hnlich dem Typ 6. Der Eurasische Wolf ist der Wolf Europas und Asiens \u2014 verbreitet, ausdauernd, sozial tief verwurzelt. Sein Rudel ist eine Gemeinschaft mit klaren Rollen und starker gegenseitiger Abh\u00e4ngigkeit: Die Sicherheit des Einzelnen h\u00e4ngt vom Zusammenhalt aller ab. Bedrohungen werden kollektiv registriert und kollektiv beantwortet. Der Eurasische Wolf ist wachsam, aber nie unbesonnen. Die Leidenschaft der Angst zeigt sich als Hyperaufmerksamkeit f\u00fcr alles, was die Sicherheit des Rudels bedrohen k\u00f6nnte.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Indischer Wolf: Neugier und Lebhaftigkeit</h3>
        <p class="vb-intro">Der indische Wolf lebt meist in Rudeln und zeigt eine gro\u00dfe Neugier in verschiedensten Lebensr\u00e4umen \u2014 bekannt f\u00fcr die abenteuerliche und begeisterte Natur des Typ 7. Der Indische Wolf ist kleiner und leichter als seine europ\u00e4ischen Verwandten \u2014 und beweglicher. Er bewohnt offene Grassteppen und Halbw\u00fcsten Indiens und hat sich an ein Leben angepasst, das st\u00e4ndige Bewegung erfordert: weite Streifz\u00fcge, wechselnde Jagdgr\u00fcnde, neue Territorien. Er ist verspielter als andere Wolfsarten und zeigt selbst als Erwachsener h\u00e4ufig spielerisches Verhalten. Die Leidenschaft der V\u00f6llerei zeigt sich als unstillbarer Appetit auf neue R\u00e4ume und Erfahrungen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Timberwolf: Dominanz und F\u00fchrungsst\u00e4rke</h3>
        <p class="vb-intro">Der Timberwolf ist der gr\u00f6\u00dfte wildlebende Wolf der Welt, lebt in stark strukturierten Rudeln, die aus einem Alpha-Paar und dessen Nachkommen bestehen \u2014 Eigenschaften, die der Durchsetzungsf\u00e4higkeit des Typs 8 entsprechen. Der Timberwolf der nordamerikanischen W\u00e4lder ist ein Wolf, der Landschaften pr\u00e4gt: Wo er lebt, reguliert er die Best\u00e4nde der Huftiere und damit die gesamte \u00d6kologie seines Lebensraums \u2014 der sogenannte trophische Kaskaden-Effekt. Er braucht kein Einverst\u00e4ndnis, er gestaltet. Im Rudel f\u00fchrt das Alpha-Paar mit einer Kombination aus St\u00e4rke und Erfahrung, die nicht hinterfragt wird. Die Leidenschaft der Gier zeigt sich als ungestillter Wille zur Kontrolle und zum Gestalten.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Iberischer Wolf: Harmonie und Ausgleich</h3>
        <p class="vb-intro">Der iberische Wolf zeigt oft ein ruhiges und zur\u00fcckhaltendes Verhalten und lebt harmonisch in kleineren Rudeln \u2014 was dem friedliebenden und ausgleichenden Wesen von Typ 9 entspricht. Der Iberische Wolf ist kleiner und scheuer als der Grauwolf \u2014 ein Tier, das \u00fcber Jahrhunderte der Verfolgung gelernt hat, m\u00f6glichst unsichtbar zu sein. Er meidet Konflikte mit Menschen, lebt in kleinen Familienrudeln und h\u00e4lt sich in Bergregionen Portugals und Spaniens verborgen. Sein Territorium verteidigt er still und ohne unn\u00f6tige Eskalation. Die Leidenschaft der Tr\u00e4gheit zeigt sich als tiefer Wunsch, den Frieden des Waldes nicht zu st\u00f6ren \u2014 einfach zu sein, im Verborgenen.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"wolkenformationen-der-9-typen", label:"Wolkenformationen der 9 Typen"},
        {route:"eulenarten-der-9-typen", label:"Eulenarten der 9 Typen"},
        {route:"baerenarten-der-9-typen", label:"B\u00e4renarten der 9 Typen"},
      ])}
    </div>
  `);
}

function wetterNaturphaenomeneDer9TypenPage() {
  const bild = (datei, alt) => `<img src="./assets/${datei}" alt="${alt}"
        style="width:100%;max-width:640px;display:block;margin:1rem auto 1.2rem;border-radius:12px;cursor:zoom-in;" />`;
  return shell(`
    <div class="page-container">
      ${pageHeader("Wetter- und Naturph\u00e4nomene der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <h1 style="font-family:'EB Garamond',serif;font-size:2rem;color:var(--ink);margin:1.2rem 0 0.5rem;line-height:1.2;">Wetter- und Naturph\u00e4nomene der 9 Typen</h1>
      <p class="psycho-intro">Die Natur dr\u00fcckt die neun Ur-Energien des Enneagramms in ihren eigenen Zyklen aus: Frost und Regen, Sonne und Nebel, Sternennacht und Sturm, Regenbogen und Vulkan, der stille See. Jedes Wetterph\u00e4nomen tr\u00e4gt ein eigenes Prinzip in sich \u2013 eine eigene Bewegung, eine eigene Qualit\u00e4t von Kraft, Ruhe oder Wandel. Neun Naturph\u00e4nomene, neun Enneagrammprinzipien.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Der Frost / Die Kristallbildung: Erstarrte Form</h3>
      ${bild("wetter-1-frost.jpg", "Rauhreif-Kristalle an gefrorenen Zweigen")}
      <p class="vb-intro">Frost entsteht, wenn Feuchtigkeit unter fallender Temperatur nicht chaotisch gefriert, sondern sich zu einer exakten, geometrisch reinen Struktur ordnet \u2013 jede Eiskristallnadel folgt demselben inneren Bauplan, nichts ist zuf\u00e4llig, nichts wirkt "unordentlich". Genau das ist die Signatur von Typ 1: der innere Drang, Chaos in eine korrekte, makellose Form zu bringen, bevor sie als "fertig" gelten darf. Frost ist au\u00dferdem kalt und hart, solange er nicht erw\u00e4rmt wird \u2013 ein Bild f\u00fcr die Strenge, mit der Einser zun\u00e4chst sich selbst, dann die Welt bewerten: nichts darf schmelzen, solange die Form nicht stimmt. Und so, wie Rauhreif bei den ersten Sonnenstrahlen in klares, flie\u00dfendes Wasser \u00fcbergeht, l\u00f6st sich auch die Strenge der Einser, sobald sie sich selbst mit W\u00e4rme statt mit Kritik begegnen \u2013 die Perfektion wird dann nicht aufgegeben, sondern lebendig.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Der warme Fr\u00fchlingsregen: N\u00e4hrend</h3>
      ${bild("wetter-2-fruehlingsregen.jpg", "Regentropfen auf frischem Fr\u00fchlingsgras")}
      <p class="vb-intro">Fr\u00fchlingsregen f\u00e4llt nicht als Unwetter, sondern sanft und beharrlich \u2013 er weckt das Wachstum in allem, was er ber\u00fchrt, ohne selbst sichtbar zu bleiben. Er sickert in den Boden, dorthin, wo die Wurzeln sind, und wirkt im Verborgenen weiter, lange nachdem die Wolken schon weitergezogen sind. Das ist die Kernbewegung der Zwei: sich in den Dienst des Wachstums anderer stellen, oft unbemerkt, ohne daf\u00fcr Anerkennung zu verlangen \u2013 N\u00e4he geben, die den anderen aufbl\u00fchen l\u00e4sst. Die Kehrseite zeigt sich, wenn Regen nicht mehr aufh\u00f6rt: Ein Boden, der st\u00e4ndig \u00fcbergossen wird, kann \u00fcberfluten, Wurzeln k\u00f6nnen faulen. Die Tendenz der Zweier, so viel zu geben, dass die eigenen Grenzen verschwimmen, tr\u00e4gt dasselbe Risiko \u2013 sie selbst trocknen aus, weil sie sich nie "gie\u00dfen" lassen. Reife bei Typ 2 hei\u00dft: den eigenen Regen auch f\u00fcr sich selbst fallen lassen.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Die Mittagssonne: Volle Strahlkraft</h3>
      ${bild("wetter-3-mittagssonne.jpg", "Sonnenblume in voller Bl\u00fcte im hellen Sonnenlicht")}
      <p class="vb-intro">Die Sonne im Zenit ist der Moment maximaler Sichtbarkeit und Kraft \u2013 Schatten werden minimal, jede Form, jede Farbe, jede Leistung wird sichtbar. Eine Sonnenblume folgt dieser Sonne den ganzen Tag \u00fcber, dreht sich ihr entgegen, \u00f6ffnet sich ihr voll \u2013 sie ist auf Strahlkraft hin gebaut. Genau das spiegelt den Antrieb der Drei: strahlen, gl\u00e4nzen, Erfolg und F\u00e4higkeit sichtbar machen, sich der Anerkennung entgegendrehen wie die Bl\u00fcte dem Licht. Doch Mittagssonne blendet auch: In ihrem grellen Licht verschwimmen die feinen Konturen, man sieht weniger klar, gerade weil das Licht so intensiv ist. Ebenso kann die Selbstdarstellung der Dreier verdecken, wer sie "im eigenen Schatten", jenseits der Leistung und der B\u00fchne, eigentlich sind. Die Reife dieses Typs entsteht, wenn er auch bei bew\u00f6lktem Himmel wei\u00df, dass er wertvoll ist.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Der Nebel / Der Herbst: Melancholisch, geheimnisvoll</h3>
      ${bild("wetter-4-nebel-herbst.jpg", "Herbstlicher Nebelsee mit gespiegelten B\u00e4umen")}
      <p class="vb-intro">Nebel \u00fcber einem herbstlichen See verwischt die Grenzen zwischen Wasser, Ufer und Himmel \u2013 Vertrautes wird fremd und zugleich poetisch, weil man die Konturen der Welt nur ahnt, nicht klar sieht. Der Herbst als Jahreszeit des \u00dcbergangs, der Verg\u00e4nglichkeit in voller Farbenpracht, spricht die Vier unmittelbar an: Das Gef\u00fchl von Tiefe entsteht bei diesem Typ gerade aus dem Bewusstsein des Verlusts, aus dem Wissen, dass jede Sch\u00f6nheit auch vergeht. Die ged\u00e4mpfte, gold-braune Stimmung eines Nebelmorgens im Herbst tr\u00e4gt genau diese Mischung aus Sehnsucht, Wehmut und stiller Sch\u00f6nheit, die f\u00fcr Vierer zum eigentlichen Lebensgef\u00fchl wird. Nebel hebt sich aber auch \u2013 und dahinter liegt oft \u00fcberraschende Klarheit. Ein Bild daf\u00fcr, dass die emotionale Intensit\u00e4t der Vierer kein Endzustand sein muss, sondern ein Durchgang zu echter, undramatischer Pr\u00e4senz.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Die Sternennacht / Polarnacht: Stille, Tiefe</h3>
      ${bild("wetter-5-polarnacht.jpg", "Sternenhimmel mit Polarlicht in der Polarnacht")}
      <p class="vb-intro">Die Polarnacht ist Stille, Distanz, unendliche Weite \u2013 ein Raum, in dem man tagelang beobachten kann, ohne selbst gesehen zu werden, in dem R\u00fcckzug kein Mangel, sondern die Bedingung f\u00fcr Klarheit ist. Genau das trifft den R\u00fcckzugsimpuls der F\u00fcnf: Abstand schaffen, um zu verstehen, bevor man sich einl\u00e4sst; die Dinge erst in Ruhe durchdenken, dann erst handeln. Die Sterne und das Polarlicht selbst stehen f\u00fcr das, was die F\u00fcnf sammelt \u2013 Wissen, Muster, Einsicht, aus sicherer Entfernung betrachtet, ohne den L\u00e4rm des Tages, der die feinen Lichter am Himmel \u00fcberstrahlen w\u00fcrde. Die Herausforderung dieses Bildes: eine Nacht, die zu lange dauert, in der niemand mehr zur\u00fcckkehrt ins Tageslicht der Verbindung. Reife bei Typ 5 bedeutet, die gesammelte innere Klarheit auch mit anderen zu teilen, statt sie nur f\u00fcr sich zu behalten.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Der Wind / Das aufziehende Unwetter: Achtsamkeit, Warnung</h3>
      ${bild("wetter-6-unwetter.jpg", "Blitz \u00fcber Bergen, aufziehende Gewitterwolken")}
      <p class="vb-intro">Der Wind, der das Kommende ank\u00fcndigt, das Barometer, das f\u00e4llt, die Wolken, die sich \u00fcber den Bergen auft\u00fcrmen \u2013 das ist reine Wachsamkeit, das Lesen von Signalen, bevor die eigentliche Gefahr \u00fcberhaupt da ist. Genau das ist die Gabe der Sechs: Sie sp\u00fcren Risiken, bevor andere sie sehen, sie sind die "Wetterf\u00fchligen" jeder Gruppe, diejenigen, die als Erste merken, wenn sich etwas zusammenbraut. Die Sorge-und-Angst-Dynamik dieses Typs zeigt sich darin, dass der aufziehende Wind selbst noch kein Sturm ist \u2013 aber Sechser erleben ihn oft schon so, als w\u00e4re die Katastrophe bereits eingetroffen, und r\u00fcsten sich entsprechend. Mut bedeutet bei diesem Typ nicht, keine Angst zu haben, sondern: den Wind sp\u00fcren, ernst nehmen \u2013 und ihn trotzdem nicht vorschnell zum Orkan zu erkl\u00e4ren.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Der Regenbogen / Das Sommergewitter: Dynamisch, bunt</h3>
      ${bild("wetter-7-regenbogen.jpg", "Regenbogen vor der Abendsonne nach einem Sommerregen")}
      <p class="vb-intro">Ein Sommergewitter ist intensiv, kurz, wechselhaft \u2013 und danach, wenn die Sonne wieder durch die Wolken bricht, erscheint der Regenbogen als Belohnung, als sichtbarer Beweis, dass aus Aufruhr sofort wieder Freude und Farbe entstehen kann. Das ist die Bewegung der Sieben: schnelle Wechsel, viele Farben und Optionen gleichzeitig im Blick, die F\u00e4higkeit, aus praktisch jeder Situation etwas Positives, Leuchtendes zu ziehen. Die Kehrseite: Ein Regenbogen ist fl\u00fcchtig, er verschwindet in dem Moment, in dem man versucht, ihn festzuhalten oder ihm hinterherzulaufen \u2013 ein Bild f\u00fcr die Schwierigkeit vieler Siebener, bei einer Erfahrung, einem Gef\u00fchl oder einer Verpflichtung wirklich zu bleiben, statt zum n\u00e4chsten "bunten" Reiz weiterzuziehen. Reife bei diesem Typ zeigt sich, wenn er lernt, auch bei bedecktem Himmel zu bleiben, ohne sofort zum n\u00e4chsten Regenbogen zu fliehen.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Der Vulkanausbruch / Der Sturm: Rohe Gewalt, Transformation</h3>
      ${bild("wetter-8-vulkan.jpg", "Vulkanausbruch mit Lava und Aschewolke")}
      <p class="vb-intro">Rohe, ungefilterte Kraft, die sich unaufhaltsam Bahn bricht \u2013 ein Vulkanausbruch zerst\u00f6rt alles in seinem unmittelbaren Weg, schafft aber zugleich neuen, au\u00dfergew\u00f6hnlich fruchtbaren Boden, auf dem sp\u00e4ter mehr w\u00e4chst als zuvor. Das ist die Acht: Intensit\u00e4t, Durchsetzungskraft, der Instinkt, sofort die Kontrolle zu \u00fcbernehmen, sobald irgendwo Schw\u00e4che oder Bedrohung gesp\u00fcrt wird. Der Ausbruch reinigt gewisserma\u00dfen die Atmosph\u00e4re, bringt aber auch Verw\u00fcstung, wenn die Kraft unkontrolliert bleibt und niemand sie kanalisiert. Die Reifung der Acht liegt genau darin, die eigene "Lava-Kraft" bewusst zu lenken \u2013 Schutz und Aufbau statt blo\u00dfer Zerst\u00f6rung, echte F\u00fchrung statt reiner Dominanz. Ein Vulkan, der wei\u00df, wohin seine Kraft flie\u00dfen soll, ver\u00e4ndert eine Landschaft zum Guten.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Der stille See / Das weite Meer: Absolute Ruhe, Verbindung</h3>
      ${bild("wetter-9-stiller-see.jpg", "Stiller See bei Sonnenuntergang mit ruhiger Wasserspiegelung")}
      <p class="vb-intro">Die spiegelglatte Oberfl\u00e4che eines stillen Sees bei Sonnenuntergang zeigt den Himmel, die Ufer, die B\u00e4ume \u2013 perfekt, ohne eigene Bewegung, die diesen Frieden st\u00f6ren w\u00fcrde. Genau das ist der tiefste Wunsch der Neun: Verbindung, Harmonie, Nicht-Konflikt, das Gef\u00fchl, mit der Umgebung eins zu sein, statt sich gegen sie zu behaupten. Aber ein See ohne jede Str\u00f6mung kann mit der Zeit stagnieren \u2013 ebenso wie Neuner sich selbst, ihre eigenen W\u00fcnsche und Priorit\u00e4ten, "vergessen" k\u00f6nnen, um den \u00e4u\u00dferen Frieden um jeden Preis zu bewahren. Das weite Meer im Hintergrund erinnert daran, dass unter der ruhigen Oberfl\u00e4che enorme Kraft und Tiefe liegen \u2013 die eigene Pr\u00e4senz, der eigene Wille, den die Neun oft erst bewusst entdecken und beanspruchen muss, um wirklich lebendig zu sein.</p>

      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"wolkenformationen-der-9-typen", label:"Wolkenformationen der 9 Typen"},
        {route:"berge-der-9-typen", label:"Berge der 9 Typen"},
        {route:"baerenarten-der-9-typen", label:"B\u00e4renarten der 9 Typen"},
      ])}
    </div>
  `);
}

function architekturRaumgestaltungDer9TypenPage() {
  const bild = (datei, alt) => `<img src="./assets/${datei}" alt="${alt}"
        style="width:100%;max-width:640px;display:block;margin:1rem auto 1.2rem;border-radius:12px;cursor:zoom-in;" />`;
  return shell(`
    <div class="page-container">
      ${pageHeader("Architektur & Raumgestaltung der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <h1 style="font-family:'EB Garamond',serif;font-size:2rem;color:var(--ink);margin:1.2rem 0 0.5rem;line-height:1.2;">Architektur & Raumgestaltung der 9 Typen</h1>
      <p class="psycho-intro">Wie wir R\u00e4ume bauen und bewohnen, spiegelt unsere innere Haltung wider. Jeder Baustil tr\u00e4gt ein eigenes Lebensgef\u00fchl in sich \u2013 Klarheit oder W\u00e4rme, Repr\u00e4sentation oder R\u00fcckzug, Dramatik oder Stabilit\u00e4t. Neun Architektur- und Raumkonzepte, neun Enneagrammprinzipien.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Minimalismus / Bauhaus: Klare Linien, funktionale Perfektion</h3>
      ${bild("architektur-1-bauhaus.jpg", "Bauhaus-Geb\u00e4ude mit klaren geometrischen Linien")}
      <p class="vb-intro">Bauhaus-Architektur verzichtet auf jedes Ornament, das keine Funktion erf\u00fcllt \u2013 jede Linie, jede Fl\u00e4che ist so reduziert, wie sie sein muss, und nicht mehr. Genau das ist die Handschrift der Eins: eine tief sitzende Sehnsucht nach der einen richtigen, korrekten Form, in der nichts \u00fcberfl\u00fcssig ist und nichts fehlt. Klare Kanten, rechte Winkel, keine Schn\u00f6rkel \u2013 Ordnung wird hier nicht als Einschr\u00e4nkung erlebt, sondern als die einzig ehrliche Antwort auf die Frage, wie ein Raum sein sollte. Die Kehrseite: Ein Raum, der nur noch Funktion kennt, kann kalt wirken, ein Zuhause ohne Weichheit. Reife bei Typ 1 zeigt sich, wenn die klare Form bestehen bleibt, aber W\u00e4rme und Leben in sie einziehen d\u00fcrfen.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Kompakter Landhausstil / Hygge: Gem\u00fctlich, einladend</h3>
      ${bild("architektur-2-hygge.jpg", "Gem\u00fctliches Hygge-Wohnzimmer mit warmem Licht und vielen Sitzgelegenheiten")}
      <p class="vb-intro">Der Landhausstil und das d\u00e4nische Hygge-Gef\u00fchl leben von weichen Textilien, warmem Licht und vor allem: von Sitzgelegenheiten f\u00fcr andere. Ein Sofa, das f\u00fcr vier gedacht ist, ein Tisch, an dem noch ein Stuhl mehr Platz findet \u2013 dieser Raum ist von Anfang an auf Besuch, auf N\u00e4he, auf gemeinsames Ankommen hin gebaut. Genau das ist die Zwei: ein Zuhause schaffen, in dem sich andere geborgen f\u00fchlen, noch bevor die eigenen Bed\u00fcrfnisse \u00fcberhaupt zur Sprache kommen. Die Gefahr liegt darin, dass der Raum irgendwann mehr f\u00fcr G\u00e4ste eingerichtet ist als f\u00fcr die Bewohnerin selbst. Reife bedeutet, sich die gem\u00fctlichste Ecke auch f\u00fcr sich selbst zu reservieren.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Penthouse / Moderne Glas-Architektur: Repr\u00e4sentativ, zukunftsorientiert</h3>
      ${bild("architektur-3-glasfassade.jpg", "Moderne Glasfassade eines Wolkenkratzers")}
      <p class="vb-intro">Glasfassaden und Penthouses sind Architektur, die gesehen werden will \u2013 sie reflektieren Licht, Status und Fortschritt, oft schon von Weitem sichtbar \u00fcber der \u00fcbrigen Stadt. Kein Detail ist zuf\u00e4llig: Jede Sichtachse, jede Skyline-Aussicht ist so platziert, dass sie beeindruckt. Das ist die Drei: ein Zuhause als B\u00fchne, als sichtbares Zeugnis von Erfolg, das keine Erkl\u00e4rung braucht, weil es f\u00fcr sich selbst spricht. Die Kehrseite dieser gl\u00e4sernen Perfektion: Wer st\u00e4ndig repr\u00e4sentiert, hat oft keinen Ort mehr, an dem er einfach nur unperfekt sein darf. Reife bei Typ 3 entsteht, wenn Wert nicht mehr an der Wirkung der R\u00e4ume h\u00e4ngt, sondern im Inneren ruht.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Gothik / Boho-Chic / Art Nouveau: Dramatisch, individuell</h3>
      ${bild("architektur-4-jugendstil.jpg", "Jugendstil-Fassade mit kunstvollen, individuellen Details")}
      <p class="vb-intro">Jugendstil-Fassaden und gotische Bauten verweigern sich der Wiederholung \u2013 jede Verzierung ist einzigartig, jedes Fenster erz\u00e4hlt eine eigene kleine Geschichte, jedes Detail tr\u00e4gt Ausdruck statt blo\u00dfer Funktion. Das ist die tiefste Sprache der Vier: ein Raum muss die eigene Einzigartigkeit sichtbar machen, muss Bedeutung, Geschichte, Gef\u00fchl in sich tragen, sonst bleibt er leer. Dramatische Farben, ungew\u00f6hnliche Formen, gesammelte Fundst\u00fccke \u2013 jedes Element ist Ausdruck einer inneren Wahrheit. Die Gefahr: Ein Raum, der so sehr auf Besonderheit ausgerichtet ist, dass er nie fertig, nie in Ruhe ankommen kann. Reife zeigt sich, wenn die Sch\u00f6nheit bleibt, ohne dass st\u00e4ndig neue Dramatik nachgeliefert werden muss.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Brutalismus / Tiny House: Autark, auf das Wesentliche reduziert</h3>
      ${bild("architektur-5-brutalismus.jpg", "Brutalistisches Betongeb\u00e4ude mit klaren, massiven Formen")}
      <p class="vb-intro">Rohbeton, unverkleidet, ehrlich in seiner Materialit\u00e4t \u2013 Brutalismus zeigt genau das, was er ist, ohne Fassade, ohne Dekoration, die vom Wesentlichen ablenken w\u00fcrde. Ebenso das Tiny House: ein Raum, radikal reduziert auf das, was wirklich gebraucht wird, autark, unabh\u00e4ngig von unn\u00f6tigem Ballast. Das ist die F\u00fcnf: R\u00fcckzug in einen gesch\u00fctzten, klar begrenzten Raum, in dem jede Ressource \u2013 Zeit, Energie, Besitz \u2013 bewusst eingeteilt ist, damit nichts verschwendet wird. Die Kehrseite: Ein Raum, der so sehr auf Autarkie ausgelegt ist, dass er andere gar nicht mehr hereinl\u00e4sst. Reife bei Typ 5 hei\u00dft, die eigene Festung auch einmal f\u00fcr andere zu \u00f6ffnen.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Festungs-Architektur / Klassische Klinker-Siedlungen: Solide, best\u00e4ndig</h3>
      ${bild("architektur-6-festung.jpg", "Massive Festung mit dicken Steinmauern")}
      <p class="vb-intro">Eine Festung ist so gebaut, dass sie jedem Angriff standh\u00e4lt \u2013 dicke Mauern, wenige, gut kontrollierbare Zug\u00e4nge, ein Ort, an dem man sich sicher f\u00fchlt, weil man wei\u00df, was ihn sch\u00fctzt. Klassische Klinker-Siedlungen tragen dieselbe Botschaft in b\u00fcrgerlicherem Ma\u00dfstab: solide Bausubstanz, die seit Generationen h\u00e4lt und nichts dem Zufall \u00fcberl\u00e4sst. Das ist die Sechs: Sicherheit entsteht durch Struktur, durch Verl\u00e4sslichkeit, durch das Wissen, was im Ernstfall tr\u00e4gt. Ein Zuhause, das Halt gibt, weil es gepr\u00fcft und bew\u00e4hrt ist. Die Gefahr: Mauern, die so dick werden, dass sie auch das Vertrauen aussperren. Reife bei Typ 6 zeigt sich, wenn Sicherheit nicht mehr nur von au\u00dfen, sondern auch von innen kommt.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Lofts / Glamping-Architektur: Offen, verspielt, hell</h3>
      ${bild("architektur-7-loft.jpg", "Offenes, helles Loft mit flie\u00dfenden Raum\u00fcberg\u00e4ngen")}
      <p class="vb-intro">Ein Loft kennt keine festen W\u00e4nde \u2013 K\u00fcche, Wohnen, Arbeiten flie\u00dfen ineinander, jederzeit l\u00e4sst sich der Raum neu nutzen, neu erleben, nichts ist endg\u00fcltig festgelegt. Glamping-Architektur tr\u00e4gt dieselbe Leichtigkeit ins Freie: Komfort ohne Enge, Offenheit statt Begrenzung, immer die M\u00f6glichkeit, spontan weiterzuziehen. Das ist die Sieben: ein Raum, der Optionen offenh\u00e4lt, der Licht, Luft und Bewegungsfreiheit \u00fcber feste Struktur stellt, weil Festlegung wie Einengung wirkt. Die Kehrseite: So viel Offenheit kann auch bedeuten, dass sich nie ein wirkliches Zuhause-Gef\u00fchl einstellt. Reife bei Typ 7 entsteht, wenn ein offener Raum auch zum Bleiben einl\u00e4dt, nicht nur zum Weiterziehen.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Industrial Style / Monumentalarchitektur: Massiv, imposant</h3>
      ${bild("architektur-8-industrial.jpg", "Industrial-Interieur mit Ziegelmauer, Stahl und gro\u00dfen Fenstern")}
      <p class="vb-intro">Roher Backstein, sichtbare Stahltr\u00e4ger, massive Fensterfronten \u2013 Industrial Style verbirgt nichts von seiner Kraft, im Gegenteil, er stellt sie aus. Monumentalarchitektur geht noch weiter: Bauten, die allein durch ihre Gr\u00f6\u00dfe Respekt einfordern, die keinen Zweifel daran lassen, wer hier den Raum bestimmt. Das ist die Acht: ein Zuhause als Ausdruck von St\u00e4rke, unverstellter Pr\u00e4senz, Kontrolle \u00fcber das eigene Territorium. Nichts wird verkleinert oder besch\u00f6nigt, jede Struktur bleibt sichtbar. Die Gefahr: Ein Raum, der so massiv wirkt, dass Verletzlichkeit darin keinen Platz mehr findet. Reife bei Typ 8 zeigt sich, wenn hinter der starken Fassade auch Weichheit zugelassen wird.</p>

      <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Organische Architektur (Hundertwasser/Steiner): Integriert in die Natur</h3>
      ${bild("architektur-9-organisch.jpg", "Hundertwasserhaus mit bunter, organisch geschwungener Fassade")}
      <p class="vb-intro">Hundertwassers Bauten kennen keine gerade Linie, keinen rechten Winkel, der die Natur unterbrechen w\u00fcrde \u2013 Fassaden wachsen wie Baumst\u00e4mme, D\u00e4cher tragen Erde und Pflanzen, das Haus wird Teil der Landschaft statt Widerspruch zu ihr. Genau das ist die Neun: ein Raum, der nicht gegen die Umgebung behauptet wird, sondern mit ihr verschmilzt, in dem Grenzen weich und durchl\u00e4ssig bleiben, weil Harmonie wichtiger ist als Abgrenzung. Weiche Formen, warme Farben, kein Element, das sich in den Vordergrund dr\u00e4ngt. Die Kehrseite: Ein Haus ohne klare Kontur kann auch bedeuten, dass die Bewohnerin selbst darin verschwimmt. Reife bei Typ 9 entsteht, wenn die organische Weichheit bleibt, aber die eigene Pr\u00e4senz darin klar sp\u00fcrbar wird. Mehr zu Hundertwasser als sexuellem Typ 9 (SX9w8) im Portr\u00e4t weiter unten verlinkt.</p>

      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"wetter-naturphaenomene-der-9-typen", label:"Wetter- und Naturph\u00e4nomene der 9 Typen"},
        {route:"beziehungen", label:"Beziehungen der 9 Typen"},
        {route:"arbeitsverhalten-der-9-typen", label:"Arbeitsverhalten der 9 Typen"},
        {route:"beruehmte-hundertwasser", label:"Portr\u00e4t: Friedensreich Hundertwasser (SX9w8)"},
      ])}
    </div>
  `);
}

function eulenartenDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Eulenarten der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Die Zuordnung von neun Eulenarten zu den neun Enneagrammprinzipien ist eine kreative Methode, um die vielf\u00e4ltigen Aspekte und Charakteristika dieser Eulen und deren Merkmale mit den verschiedenen Pers\u00f6nlichkeitstypen des Enneagramms zu verbinden. Eulen sind seit der Antike Symbole der Weisheit, Stille und inneren Schau \u2014 jede Art auf ihre ganz eigene Weise.</p>
      <img src="./assets/eulenarten-der-9-typen.jpg" alt="Eulenarten der 9 Typen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Schleiereule: Pr\u00e4zision und Perfektion</h3>
        <p class="vb-intro">Schleiereulen haben ein klares, strukturiertes Jagdmuster und sind f\u00fcr ihre Effizienz und Pr\u00e4zision bekannt. Ihre methodische Natur und ihr Streben nach Perfektion spiegeln die Eigenschaften des Reformers Typ 1 wider. Das Gesicht der Schleiereule ist ein akustisches Pr\u00e4zisionsinstrument: Die herzf\u00f6rmige Scheibe b\u00fcndelt Schallwellen wie eine Parabolantenne und leitet sie zu den asymmetrisch platzierten Ohren \u2014 dadurch kann sie im absoluten Dunkel eine Maus unter Schnee orten, allein durch das Ger\u00e4usch ihrer Schritte. Kein Lebewesen hat ein genaueres Geh\u00f6r. Fehler macht die Schleiereule nicht \u2014 sie kann es sich nicht leisten. Die Leidenschaft des Zorns zeigt sich als innere Anspannung, wenn die Jagd nicht dem inneren Standard entspricht.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Bartkauz: F\u00fcrsorge und stille Hilfsbereitschaft</h3>
        <p class="vb-intro">Der Bartkauz ist bekannt f\u00fcr seine f\u00fcrsorgliche Natur gegen\u00fcber seinen Jungen und seine F\u00e4higkeit, in einer Vielzahl von Umgebungen zu \u00fcberleben und anderen Eulen bei der Aufzucht zu helfen, wenn n\u00f6tig. Der Bartkauz ist eine der gr\u00f6\u00dften Eulen der Welt \u2014 und eine der stillsten. Er jagt lautlos, warnt andere vor Gefahren und zeigt eine ausgepr\u00e4gte Brutf\u00fcrsorge: Bartkauz-M\u00e4nnchen bringen ihrer br\u00fctenden Partnerin regelm\u00e4\u00dfig Nahrung, auch wenn die Bedingungen hart sind. Er dient, ohne zu dr\u00e4ngen. Die Leidenschaft des Stolzes zeigt sich als tiefes Bed\u00fcrfnis, gebraucht zu werden \u2014 der Besch\u00fctzer im Stillen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Schnee-Eule: Leistung und Anpassungsf\u00e4higkeit</h3>
        <p class="vb-intro">Schnee-Eulen sind beeindruckende J\u00e4ger, die unter den harten Bedingungen der Arktis \u00fcberleben. Ihre F\u00e4higkeit, sich an extreme Bedingungen anzupassen und erfolgreich zu jagen, reflektiert den leistungsorientierten Typ 3. Die Schnee-Eule ist das einzige Tier, das ganzj\u00e4hrig in der Arktis jagt \u2014 bei Temperaturen bis minus 50 Grad, im Winter ohne Licht. Sie zieht keine Grenzen zwischen Nacht und Tag, zwischen Sturm und Stille: Sie jagt, wenn Beute da ist. Ihr wei\u00dfes Gefieder ist kein Schmuck, sondern Effizienz \u2014 perfekte Tarnung im Schnee. Die Leidenschaft der Eitelkeit zeigt sich als der Wille, sichtbar zu triumphieren.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Waldohreule: Einzigartigkeit und innere Tiefe</h3>
        <p class="vb-intro">Die Waldohreule besitzt ein auff\u00e4lliges Aussehen mit ihren markanten Federb\u00fcscheln, was sie deutlich von anderen Eulen unterscheidet. Ihre Besonderheit und das Anderssein entsprechen dem Individualisten Typ 4. Die Waldohreule ist der Waschb\u00e4r unter den Eulen: Wenn sie sich bedroht f\u00fchlt, streckt sie sich zu einem schlanken Ast, presst das Gefieder eng an den K\u00f6rper und wird fast unsichtbar zwischen Rinde und Borke. Diese F\u00e4higkeit zur Transformation \u2014 sichtbar sein, wenn sie will, unsichtbar, wenn n\u00f6tig \u2014 spiegelt die innere Welt des Typs 4 wider. Die Leidenschaft des Neids zeigt sich als Sehnsucht, gesehen zu werden ohne die Schutzmaske aufzugeben.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Habichtskauz: Beobachtung und analytische Stille</h3>
        <p class="vb-intro">Der Habichtskauz verh\u00e4lt sich ruhig und zur\u00fcckhaltend und setzt seine genaue Beobachtungsgabe gezielt ein, um Beute zu suchen \u2014 was dem beobachtenden Analytiker Typ 5 entspricht. Der Habichtskauz ist die gr\u00f6\u00dfte Eule der borealen W\u00e4lder \u2014 und eine der am schwersten zu beobachtenden. Er sitzt stundenlang regungslos auf einem hohen Ast, dreht den Kopf in kleinen, pr\u00e4zisen Bewegungen und wartet. Er rennt nicht der Beute hinterher \u2014 er wartet, bis er genug wei\u00df, und handelt dann mit absoluter Sicherheit. Sein Blick ist nicht aggressiv, sondern registrierend. Die Leidenschaft des Geizes zeigt sich als Sparsamkeit mit Energie und Pr\u00e4senz.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Steinkauz: Treue und soziale Wachsamkeit</h3>
        <p class="vb-intro">Steink\u00e4uze sind sozial und leben oft in der N\u00e4he menschlicher Siedlungen. Ihre Loyalit\u00e4t gegen\u00fcber ihren Partnern und ihre Bereitschaft, die Familie zu besch\u00fctzen, spiegeln die Eigenschaften des verl\u00e4sslichen Typs 6 wider. Der Steinkauz ist die Eule, die den Menschen am n\u00e4chsten lebt: Er nistet in alten Obstg\u00e4rten, Scheunen und Mauerl\u00f6chern, direkt neben dem Bauernhof. Er kennt jede Ecke seines Reviers auswendig und reagiert auf jede Ver\u00e4nderung mit sichtbarer Alarmierung. Sein Pfeifton in der D\u00e4mmerung ist ein Signal: Ich bin hier, ich beobachte, alles ist unter Kontrolle. Die Leidenschaft der Angst zeigt sich als permanente Wachheit, die nie ganz zur Ruhe kommt.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Sperbereule: Lebhaftigkeit und Jagdfreude</h3>
        <p class="vb-intro">Die Sperbereule ist eine mittelgro\u00dfe Eule, die in den offenen W\u00e4ldern und auf Wiesen lebt. Sie ist f\u00fcr ihre akrobatischen Flugman\u00f6ver und ihre schnellen Jagdtechniken bekannt, was ihre lebhafte, abenteuerlustige Natur zeigt. Die Sperbereule ist die einzige Eule, die \u00fcberwiegend tagaktiv ist \u2014 sie jagt im Sonnenlicht, sichtbar f\u00fcr alle. Sie fliegt in langen, wellenf\u00f6rmigen B\u00f6gen, st\u00fcrzt blitzschnell auf Beute und ist in st\u00e4ndiger Bewegung. Anders als ihre nachtaktiven Verwandten sucht sie nicht die Stille, sondern das Licht. Die Leidenschaft der V\u00f6llerei zeigt sich als unstillbarer Hunger nach Aktion und dem n\u00e4chsten Ziel am Horizont.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Turkmenischer Uhu: Dominanz und Territorialit\u00e4t</h3>
        <p class="vb-intro">Der Turkmenische Uhu ist eine sehr durchsetzungsstarke Eule. Die territoriale Aggression und seine starke Vitalpr\u00e4senz sowie Pr\u00e4senz und Durchsetzungsf\u00e4higkeit spiegeln den Herausforderer Typ 8 wider. Der Turkmenische Uhu ist eine der gr\u00f6\u00dften Eulen der Welt \u2014 sein Revier kann Hunderte von Quadratkilometern umfassen, und er verteidigt es mit einer Konsequenz, die selbst gro\u00dfe Greifv\u00f6gel meidet. Sein Ruf in der Nacht ist unverwechselbar tief und weit tragend: ein Signal, das nicht einl\u00e4dt, sondern warnt. Er teilt seinen Raum nicht \u2014 und braucht es nicht. Die Leidenschaft der Gier zeigt sich als unbedingter Wille zur Kontrolle \u00fcber den eigenen Bereich.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Zwergohreule: Stille Harmonie und Anpassung</h3>
        <p class="vb-intro">Zwergohreulchen sind klein und unauff\u00e4llig und bevorzugen friedliche und ruhige Umgebungen. Ihre friedliche und ausgeglichene Natur entspricht der harmoniesuchenden Natur des friedliebenden Typs 9. Die Zwergohreule ist die kleinste Eule Europas \u2014 und die unauff\u00e4lligste. Sie nistet in Baumh\u00f6hlen, die andere liegen lie\u00dfen, jagt leise Insekten und Kleingetier und f\u00e4llt in keiner Umgebung auf. Ihr Ruf ist ein sanftes, rhythmisches Pfeifen, das sich harmonisch in die Ger\u00e4uschkulisse der Nacht einf\u00fcgt. Sie braucht keine Aufmerksamkeit und sucht keinen Konflikt. Die Leidenschaft der Tr\u00e4gheit zeigt sich als tiefer Wunsch, dass die Nacht ruhig bleibt und alles seinen gewohnten Gang geht.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"wolfsarten-der-9-typen", label:"Wolfsarten der 9 Typen"},
        {route:"papageienarten-der-9-typen", label:"Papageienarten der 9 Typen"},
        {route:"vogelarten-der-9-typen", label:"Vogelarten der 9 Typen"},
      ])}
    </div>
  `);
}

function papageienartenDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Papageienarten der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Die Zuordnung von neun Papageienarten zu den neun Enneagrammprinzipien ist eine kreative Methode, um die vielf\u00e4ltigen Aspekte und Charakteristika dieser Papageien und deren Merkmale mit den verschiedenen Pers\u00f6nlichkeitstypen des Enneagramms zu verbinden. Jede Art spiegelt auf faszinierende Weise das Wesen eines Typs \u2014 vom analytischen Graupapagei bis zum friedliebenden Nymphensittich.</p>
      <img src="./assets/papageienarten-der-9-typen.jpg" alt="Papageienarten der 9 Typen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Graupapagei: Intelligenz und Pr\u00e4zision</h3>
        <p class="vb-intro">Der Graupapagei ist bekannt f\u00fcr seine au\u00dferordentliche Intelligenz und die F\u00e4higkeit, W\u00f6rter und Konzepte genau nachzuahmen. Er kann sehr ordentlich sein und mag eine strukturierte Umgebung \u2014 Eigenschaften, die dem perfektionistischen Typ 1 entsprechen. Der Graupapagei gilt als der kognitiv begabteste Vogel der Welt: Forscher wie Irene Pepperberg haben gezeigt, dass er nicht nur W\u00f6rter nachahmt, sondern ihre Bedeutung versteht und abstrakt denken kann \u2014 Mengen, Farben, Formen, Abwesenheit. Er unterscheidet zwischen richtig und falsch, korrekt und inkorrekt. Wenn etwas nicht stimmt, zeigt er es an. Die Leidenschaft des Zorns zeigt sich als innere Unruhe, wenn Dinge nicht so laufen, wie sie laufen sollten.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Gelbhaubenkakadu: F\u00fcrsorge und soziale Bindung</h3>
        <p class="vb-intro">Der Gelbhaubenkakadu ist sehr sozial und zeigt starke Bindungen zu seinen Partnern. Er ist \u00e4u\u00dferst neugierig und kann sehr anh\u00e4nglich sein, was ihn f\u00fcr seine F\u00fcrsorglichkeit und sein Bed\u00fcrfnis nach sozialer Interaktion bekannt macht \u2014 Eigenschaften, die dem Helfer-Typ 2 entsprechen. Gelbhaubenkakadus leiden unter Einsamkeit auf eine Weise, die man nur als emotionalen Schmerz beschreiben kann: Sie zupfen sich Federn aus, schreien, werden depressiv. Ihre Bindungsf\u00e4higkeit ist au\u00dfergew\u00f6hnlich \u2014 sie w\u00e4hlen einen Partner und bleiben ihm ein Leben lang treu. Die Leidenschaft des Stolzes zeigt sich im tiefen Bed\u00fcrfnis, gebraucht und geliebt zu werden.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Blaustirnamazone: Selbstbewusstsein und Auftritt</h3>
        <p class="vb-intro">Amazonenpapageien sind selbstbewusst und besitzen eine starke Pers\u00f6nlichkeit. Sie sind sehr neugierig und lernen schnell, was sie in ihrer Gruppe erfolgreich macht \u2014 Eigenschaften, die den leistungsorientierten Typ 3 widerspiegeln. Die Blaustirnamazone ist ein Vogel mit B\u00fchneninstinkt: Sie liebt Zuschauer, sie liebt Reaktionen, und sie lernt mit einer Geschwindigkeit, die andere Papageien besch\u00e4mt. Ihr Gefieder ist knallig, ihr Auftritt ist laut, ihre Pr\u00e4senz ist unmittelbar. Sie berechnet \u2014 nicht im kalten Sinne, sondern im Sinne eines Wesens, das immer wei\u00df, was in einer sozialen Situation gerade gefragt ist. Die Leidenschaft der Eitelkeit zeigt sich als Hunger nach Bewunderung und Resonanz.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Hyazinthara: Tiefe, Einzigartigkeit, intensive Bindung</h3>
        <p class="vb-intro">Hyazintharas sind bekannt f\u00fcr ihre lebhaften Farben und ihre einzigartige, intensive Pers\u00f6nlichkeit. Sie pflegen tiefe emotionale Bindungen zu ihren Partnern und besitzen eine starke Pr\u00e4senz als seltene Wesen \u2014 Eigenschaften, die dem Individualisten-Typ 4 entsprechen. Der Hyazinthara ist der gr\u00f6\u00dfte flugf\u00e4hige Papagei der Welt \u2014 und einer der seltensten. Sein kobaltblaues Gefieder hat keine Entsprechung in der Vogelwelt. Er bildet Paarbindungen von einer Intensit\u00e4t und Exklusivit\u00e4t, die Beobachter regelm\u00e4\u00dfig verbl\u00fcfft: Hyazintharas verbringen fast ihre gesamte Zeit miteinander, abseits der Gruppe. Die Leidenschaft des Neids zeigt sich als tiefe Sehnsucht nach vollst\u00e4ndiger Verbindung.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Kakadu: Beobachtung und distanziertes Interesse</h3>
        <p class="vb-intro">Kakadus sind sehr intelligent und lernen liebend gern neue Dinge. Sie k\u00f6nnen \u00e4u\u00dferst neugierig sein und haben ein gro\u00dfes beobachtendes, distanziertes Interesse an ihrer Umgebung \u2014 was gut zum analytischen Typ 5 passt. Der Kakadu l\u00f6st Probleme mit einer Geduld und Methodik, die an Wissenschaftler erinnert: Er dreht ein Objekt in alle Richtungen, bevor er handelt. In der Wildnis entdeckte man, dass Kakadus Werkzeuge benutzen \u2014 und das Wissen dar\u00fcber innerhalb ihrer Gruppe weitergeben, ohne es zu zeigen. Sie teilen Wissen selektiv. Die Leidenschaft des Geizes zeigt sich als Sparsamkeit mit N\u00e4he und Zuneigung \u2014 Vertrauen muss verdient werden.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Senegalpapagei: Loyalit\u00e4t und Vorsicht</h3>
        <p class="vb-intro">Senegalpapageien \u2014 fr\u00fcher Mohrenkopfpapagei \u2014 sind sehr loyal und besitzen eine starke Bindung zu ihren Partnern oder Pflegern. Sie sind vorsichtig und zur\u00fcckhaltend gegen\u00fcber Fremden, was den verl\u00e4sslichen und loyalen Typ 6 unterstreicht. Der Senegalpapagei w\u00e4hlt seine Vertrauenspersonen mit gro\u00dfer Sorgfalt \u2014 und wenn er sich einmal entschieden hat, ist diese Bindung fast unzerbrechlich. Neuen Menschen oder Situationen begegnet er mit demonstrativer Skepsis: Er beobachtet zuerst, pr\u00fcft dann, und gibt sich erst viel sp\u00e4ter zu erkennen. Die Leidenschaft der Angst zeigt sich als permanente Wachheit \u2014 ein inneres Sicherheitssystem, das nie ganz abschaltet.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Halsbandsittich: Lebendigkeit und Abenteuerlust</h3>
        <p class="vb-intro">Halsbandsittiche sind lebhaft und abenteuerlustig. Sie leben es, das Besondere, neue Erfahrungen zu machen und besitzen eine ansteckende Begeisterung f\u00fcr das Leben \u2014 typische Eigenschaften des Typ 7. Der Halsbandsittich ist einer der anpassungsf\u00e4higsten Papageien \u00fcberhaupt: Er lebt urspr\u00fcnglich in S\u00fcdasien und Afrika, hat aber inzwischen in \u00fcber 100 St\u00e4dten weltweit verwilderte Populationen aufgebaut \u2014 London, Amsterdam, K\u00f6ln, Tokio. Er findet \u00fcberall Nahrung, \u00fcberall Nistm\u00f6glichkeiten, \u00fcberall Gesellschaft. Jeder neue Ort ist eine Gelegenheit. Die Leidenschaft der V\u00f6llerei zeigt sich als unersch\u00f6pflicher Appetit auf das Neue.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Molukkenkakadu: St\u00e4rke und Dominanz</h3>
        <p class="vb-intro">Molukkenkakadus sind sehr selbstbewusst und dominant. Sie zeigen oft F\u00fchrungsqualit\u00e4ten und besitzen eine starke Pr\u00e4senz \u2014 typische Eigenschaften des Typ 8. Der Molukkenkakadu ist einer der gr\u00f6\u00dften Kakadus der Welt und einer der lautesten V\u00f6gel \u00fcberhaupt: Sein Ruf kann \u00fcber einen Kilometer weit geh\u00f6rt werden. Er setzt seine Haube in Momenten der Erregung oder Dominanz auf \u2014 ein visuelles Signal, das unmissverst\u00e4ndlich ist. Er akzeptiert keine Unterordnung, die er nicht selbst gew\u00e4hlt hat. Wenn er liebt, liebt er absolut; wenn er k\u00e4mpft, k\u00e4mpft er absolut. Die Leidenschaft der Gier zeigt sich als Hunger nach Einfluss und vollst\u00e4ndiger Kontrolle \u00fcber seine Umgebung.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Nymphensittich: Sanftmut und Harmonie</h3>
        <p class="vb-intro">Nymphensittiche sind sanfte und friedliche Zeitgenossen. Sie streben nach Harmonie und vermeiden Konflikte \u2014 was gut zum friedliebenden, sanften Typ 9 passt. Der Nymphensittich ist der meistgehaltene Papagei der Welt \u2014 nicht wegen seiner Sch\u00f6nheit oder Intelligenz, sondern wegen seines Wesens: Er ist unkompliziert, angenehm, vertr\u00e4glich. Er singt leise vor sich hin, pflegt seinen Partner mit sanften Schnabelber\u00fchrungen und bleibt selbst in unruhigen Umgebungen auffallend gelassen. Er braucht keine Aufmerksamkeit \u2014 er ist einfach da. Die Leidenschaft der Tr\u00e4gheit zeigt sich als tiefer Wunsch, dass alles bleibt, wie es ist \u2014 ruhig, warm, zusammen.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"eulenarten-der-9-typen", label:"Eulenarten der 9 Typen"},
        {route:"vogelarten-der-9-typen", label:"Vogelarten der 9 Typen"},
        {route:"blumenarten-der-9-typen", label:"Blumenarten der 9 Typen"},
      ])}
    </div>
  `);
}

function blumenartenDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Blumenarten der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Die Zuordnung von neun Blumenarten zu den neun Enneagrammprinzipien ist eine kreative Methode, um die vielf\u00e4ltigen Aspekte und Charakteristika dieser Blumen und deren Merkmale mit den verschiedenen Pers\u00f6nlichkeitstypen des Enneagramms zu verbinden. Jede Blume tr\u00e4gt ein archetypisches Wesen in sich \u2014 von der makellosen Reinheit der Lilie bis zur stillen Erleuchtung der Lotusblume.</p>
      <img src="./assets/blumenarten-der-9-typen.jpg" alt="Blumenarten der 9 Typen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Lilie: Reinheit und Perfektion</h3>
        <p class="vb-intro">Die Lilie symbolisiert Reinheit, Perfektion und Integrit\u00e4t \u2014 Werte, die gut zu den hohen Standards und dem Streben nach Vollkommenheit des Typs 1 passen. Die Lilie ist eine der \u00e4ltesten Kulturpflanzen der Welt: In \u00c4gypten, Griechenland und im christlichen Abendland steht sie f\u00fcr Unbeflecktheit und moralische Vollkommenheit. Ihre geometrisch pr\u00e4zisen Bl\u00fctenbl\u00e4tter \u00f6ffnen sich in einer Ordnung, die keine Abweichung kennt. Der Duft ist klar, stark und unverkennbar \u2014 er l\u00e4sst keine Ambiguit\u00e4t zu. F\u00fcr den Typ 1 ist die Lilie ein Spiegel: Sch\u00f6nheit als Ergebnis innerer Korrektheit, nicht als Zufall. Die Leidenschaft des Zorns zeigt sich als Schmerz, wenn die Wirklichkeit hinter dem Ideal zur\u00fcckbleibt.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Pfingstrose: Liebe und F\u00fcrsorge</h3>
        <p class="vb-intro">Die Pfingstrose steht f\u00fcr Mitgef\u00fchl und Gro\u00dfz\u00fcgigkeit \u2014 Eigenschaften, die den hilfsbereiten und liebevollen Charakter des Typs 2 unterstreichen. Keine andere Blume \u00f6ffnet sich so vollst\u00e4ndig: Die Pfingstrose entfaltet Dutzende von Bl\u00fctenbl\u00e4ttern in konzentrischen Lagen, eine Geste der totalen \u00d6ffnung. Sie duftet s\u00fc\u00df und einladend und wird seit Jahrhunderten als Geschenk der Zuneigung \u00fcberreicht. In der Volksmedizin war sie Heilpflanze f\u00fcr Herz und Geist. Der Typ 2 erkennt sich in ihr: im \u00fcberw\u00e4ltigenden Geben, im Wunsch, andere mit Sch\u00f6nheit und W\u00e4rme zu umh\u00fcllen. Die Leidenschaft des Stolzes zeigt sich als das tiefe Bed\u00fcrfnis, unentbehrlich zu sein.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Calla: Eleganz und Erfolg</h3>
        <p class="vb-intro">Die Calla symbolisiert Eleganz und Erfolg \u2014 was die ambitionierte und zielorientierte Natur des Typs 3 widerspiegelt. Die Calla ist die Blume der Architekten und Designer: ihr Kelch ist eine einzige, makellose Linie, kein \u00fcberfl\u00fcssiges Detail. In Hochzeitsarrangements und auf B\u00fchnen ist sie Stammgast \u2014 immer dort, wo Auftritt z\u00e4hlt. Pablo Picasso malte sie, Diego Riveras Frida Kahlo liebte sie. Die Calla l\u00e4sst sich nicht von anderen Blumen \u00fcbert\u00f6nen: Sie steht, und alle anderen treten zur\u00fcck. Die Leidenschaft der Eitelkeit zeigt sich als totale Identifikation mit dem eigenen Image \u2014 der Wunsch, unvergesslich zu wirken.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Iris: Individualit\u00e4t und Tiefe</h3>
        <p class="vb-intro">Die Iris steht f\u00fcr Kreativit\u00e4t und Individualit\u00e4t \u2014 was den einzigartigen und k\u00fcnstlerischen Charakter des Typs 4 widerspiegelt. Die Iris gibt es in \u00fcber 300 Arten und fast jeder Farbe des Spektrums \u2014 keine andere Blume zeigt so viel Variation innerhalb einer einzigen Gattung. Van Gogh malte die Iris mit einer Obsession, die ihn selbst \u00fcberraschte: Er nannte sie \u201edie violette Seele des S\u00fcdens". Ihr dreifaches Bl\u00fctenblatt-System symbolisiert seit der Antike die Verbindung von Himmel, Erde und Unterwelt \u2014 ein Wesen, das zwischen den Welten existiert. Die Leidenschaft des Neids zeigt sich als das Gef\u00fchl, einzigartig zu sein und dennoch nicht ganz verstanden zu werden.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Veilchen: Stille Weisheit und Beobachtung</h3>
        <p class="vb-intro">Das Veilchen symbolisiert bescheidene Weisheit und stille Nachdenklichkeit \u2014 was gut zur zur\u00fcckhaltenden und nachdenklichen Natur des Typs 5 entspricht. Das Veilchen w\u00e4chst in stillen Winkeln, unter B\u00e4umen, an schattigen H\u00e4ngen \u2014 nie im Rampenlicht. Es ist eine der kleinsten Bl\u00fcten im Garten und gleichzeitig eine der hartn\u00e4ckigsten: Es verbreitet sich leise, wurzelt tief und kehrt jedes Jahr wieder. In der Antike galt es als Pflanze der Philosophen \u2014 Nahrung des Geistes, Schutz des Denkens. Das Veilchen macht kein Aufsehen. Es ist einfach da, und wer genau hinschaut, entdeckt eine Sch\u00f6nheit, die sich nicht aufdr\u00e4ngt. Die Leidenschaft des Geizes zeigt sich als Sparsamkeit mit Pr\u00e4senz.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Vergissmeinnicht: Treue und Verl\u00e4sslichkeit</h3>
        <p class="vb-intro">Das Vergissmeinnicht steht f\u00fcr Treue und Best\u00e4ndigkeit \u2014 was den verl\u00e4sslichen und loyalen Charakter des Typs 6 unterstreicht. Der Name sagt alles: Diese kleine blaue Blume ist das universale Symbol f\u00fcr Erinnerung, Treue und das Versprechen, nicht zu vergessen. In mittelalterlichen Legenden warf ein Ritter, der seiner Geliebten Blumen pfl\u00fcckte und dabei in den Fluss fiel, ihr noch im Sturz die Blumen zu mit den Worten: \u201eVergiss mein nicht!" Das Vergissmeinnicht fragt nicht nach Aufmerksamkeit \u2014 es w\u00e4chst in gro\u00dfen Teppichen, jede Bl\u00fcte f\u00fcr sich winzig, zusammen un\u00fcbersehbar. Die Leidenschaft der Angst zeigt sich als tiefer Wunsch, nicht verlassen zu werden.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Sonnenblume: Freude und Optimismus</h3>
        <p class="vb-intro">Die Sonnenblume symbolisiert Freude und Optimismus \u2014 was gut zur lebhaften und positiven Natur des Typs 7 passt. Die Sonnenblume tut buchst\u00e4blich, was ihr Name verspricht: Junge Sonnenblumen drehen sich t\u00e4glich der Sonne entgegen, von Ost nach West \u2014 ein Ph\u00e4nomen namens Heliotropismus, das Biologen als aktive Suche nach Licht beschreiben. Sie w\u00e4chst schneller als fast jede andere Gartenpflanze, erreicht H\u00f6hen von \u00fcber drei Metern und tr\u00e4gt K\u00f6pfe, die selbst wie kleine Sonnen aussehen. Vincent van Gogh malte sie als Symbol der Freundschaft und des Lebens. Die Leidenschaft der V\u00f6llerei zeigt sich als unstillbarer Hunger nach Helligkeit und Erlebnis.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Gladiolus: St\u00e4rke und Entschlossenheit</h3>
        <p class="vb-intro">Der Gladiolus steht f\u00fcr St\u00e4rke und Entschlossenheit \u2014 passend zur kraftvollen und durchsetzungsstarken Natur des Typs 8. Der Name kommt vom lateinischen \u201egladius" \u2014 das Schwert. Kein Zufall: Der Gladiolus w\u00e4chst wie eine Klinge aus dem Boden, gerade, aufrecht, unbeugbar. Im antiken Rom wurden Gladiatoren nach dem Sieg mit Gladiolen beworfen \u2014 die Blume der K\u00e4mpfer, der \u00dcberwinder. Ihr St\u00e4ngel tr\u00e4gt die Bl\u00fcten in einer Linie von unten nach oben, als w\u00fcrden sie einen Weg zeigen: geradlinig, entschlossen, ohne Umwege. Die Leidenschaft der Gier zeigt sich als ungestillter Hunger nach Kraft und Einfluss \u2014 die Klinge, die immer nach oben zeigt.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Lotusblume: Harmonie und innerer Friede</h3>
        <p class="vb-intro">Die Lotusblume symbolisiert Frieden und Harmonie \u2014 was gut zur ausgeglichenen und harmonischen Natur des Typs 9 passt. Die Lotusblume w\u00e4chst im Schlamm und erhebt sich t\u00e4glich makellos \u00fcber die Wasseroberfl\u00e4che \u2014 ein Bild, das in buddhistischer und hinduistischer Tradition f\u00fcr Erleuchtung und den Weg durch das Leiden steht. Ihr Geheimnis: Die Oberfl\u00e4che ihrer Bl\u00fctenbl\u00e4tter ist so strukturiert, dass Schmutz einfach abperlt \u2014 der Lotus-Effekt, den die Wissenschaft erst im 20. Jahrhundert vollst\u00e4ndig verstand. F\u00fcr den Typ 9 ist die Lotusblume ein tiefes Bild: Sie ruht im Tr\u00fcben, ohne davon ber\u00fchrt zu werden. Die Leidenschaft der Tr\u00e4gheit zeigt sich als tiefer Wunsch nach diesem Frieden \u2014 unber\u00fchrt, schwebend, ganz.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"papageienarten-der-9-typen", label:"Papageienarten der 9 Typen"},
        {route:"hunderassen-der-9-typen", label:"Hunderassen der 9 Typen"},
        {route:"vogelarten-der-9-typen", label:"Vogelarten der 9 Typen"},
      ])}
    </div>
  `);
}

function kampfkunstartenDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Kampfkunstarten der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Als Kampfkunstarten bezeichnet man Stile, die Fertigkeiten und Techniken der ernsthaften k\u00f6rperlichen Auseinandersetzung mit einem Gegner unterrichten. Jede der hier aufgef\u00fchrten Kampfk\u00fcnste besitzt in ihrem Kern prim\u00e4r eines der Enneagramm-Muster, welches genau der innersten Philosophie der jeweiligen Kampfkunst entspricht.</p>
      <img src="./assets/kampfkunstarten-der-9-typen.jpg" alt="Kampfkunstarten der 9 Enneagrammtypen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Karate: Pr\u00e4zision und unbestechliche Form</h3>
        <p class="vb-intro">Karate ist die Kampfkunst der exakten Linie. Jede Technik hat eine einzige richtige Ausf\u00fchrung \u2014 der Winkel der Faust, die Stellung des Fu\u00dfes, der Zeitpunkt des Ausatmens beim Schlag sind bis ins Detail festgelegt und werden \u00fcber Jahre in den Kata, den festen Bewegungsformen, immer wieder wiederholt, bis keine Abweichung mehr m\u00f6glich ist. Es gibt kein \u201eungef\u00e4hr richtig" \u2014 nur richtig oder falsch. Genau das entspricht der inneren Welt des Typs 1: dem Streben nach dem einen korrekten Weg, der Disziplin, die eigene Ausf\u00fchrung so lange zu verfeinern, bis sie dem inneren Ideal entspricht. Der Karateka \u00fcbt nicht, um zu gewinnen, sondern um die Form zu vervollkommnen \u2014 der Sieg \u00fcber den Gegner ist nur die logische Folge der perfektionierten Technik. Die Leidenschaft des Zorns zeigt sich hier als kontrollierte, kanalisierte Kraft: Jeder Schlag ist Ausdruck von Ordnung, nicht von Wut.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Ringen: K\u00f6rperlicher Kontakt und f\u00fcrsorgliche Kontrolle</h3>
        <p class="vb-intro">Ringen ist die \u00e4lteste aller Kampfk\u00fcnste \u2014 und die intimste. Anders als bei distanzierten Schlagk\u00fcnsten gibt es hier keinen Abstand: Man h\u00e4lt den Gegner, sp\u00fcrt sein Gewicht, seinen Atem, seine n\u00e4chste Bewegung, bevor sie geschieht. Der Ringer gewinnt nicht durch Verletzen, sondern durch Kontrolle \u00fcber den K\u00f6rper des anderen \u2014 durch Umklammern, F\u00fchren, Zu-Boden-Bringen, ohne zu schlagen. Das entspricht der Beziehungsdynamik des Typs 2: der Wunsch nach engem, direktem Kontakt, das Bed\u00fcrfnis, den anderen so gut zu \u201elesen", dass man seine n\u00e4chste Bewegung schon sp\u00fcrt, bevor er selbst sie kennt. Ringen ist F\u00fcrsorge und Dominanz zugleich \u2014 man h\u00e4lt den anderen fest, angeblich um ihn zu bezwingen, tats\u00e4chlich aber, um in Verbindung zu bleiben. Die Leidenschaft des Stolzes zeigt sich als das Bed\u00fcrfnis, im Griff unentbehrlich zu sein.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Kung Fu: Virtuosit\u00e4t und beeindruckende Wirkung</h3>
        <p class="vb-intro">Kung Fu (genauer: Wushu) ist die Kampfkunst der tausend Stile und der sichtbaren Meisterschaft. Es gibt kaum eine andere Kampfkunst mit so vielf\u00e4ltigen, akrobatischen und visuell beeindruckenden Bewegungsformen \u2014 vom Tigerstil \u00fcber den Kranich- bis zum Affenstil. Kung-Fu-Meister werden seit Jahrhunderten in Legenden, Filmen und Shaolin-Vorf\u00fchrungen zu Ikonen: Bruce Lee machte Kung Fu weltber\u00fchmt, weil es Kraft, Eleganz und Show in einer einzigen Bewegungssprache vereint. Genau das entspricht dem Typ 3: dem Wunsch, durch sichtbare Exzellenz zu beeindrucken, die eigene F\u00e4higkeit so zu perfektionieren, dass sie Bewunderung erzeugt. Kung Fu ist niemals nur funktional \u2014 es ist immer auch Darbietung, ein Bild von K\u00f6nnen, das Wirkung erzielen will. Die Leidenschaft der Eitelkeit zeigt sich als Identifikation mit der makellosen, bestaunten Ausf\u00fchrung.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Judo: Der eigene Weg durch die Kraft des anderen</h3>
        <p class="vb-intro">Judo bedeutet w\u00f6rtlich \u201eder sanfte Weg" \u2014 sein Gr\u00fcnder Jigoro Kano entwickelte es aus dem Grundsatz, dass man nicht gegen die Kraft des Gegners k\u00e4mpft, sondern sie aufnimmt, umlenkt und f\u00fcr den eigenen Wurf nutzbar macht. Ein kleinerer, leichterer Judoka kann einen viel st\u00e4rkeren Gegner besiegen, wenn er dessen Bewegung und Energie versteht und sie in eine neue, eigene Richtung lenkt. Das ist die zutiefst individualistische Logik des Typs 4: nicht die direkte Konfrontation zu suchen, sondern aus dem, was von au\u00dfen kommt \u2014 auch aus Schmerz, auch aus fremder Kraft \u2014 etwas ganz Eigenes, Unverwechselbares zu formen. Jeder Wurf im Judo ist eine kleine Transformation: fremde Energie wird zur eigenen Bewegung. Die Leidenschaft des Neids zeigt sich als das tiefe Gef\u00fchl, den eigenen, unverwechselbaren Weg erst im Umgang mit dem finden zu m\u00fcssen, was einem fehlt oder entgegensteht.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Taekwondo: Distanz, Reichweite und technische Klarheit</h3>
        <p class="vb-intro">Taekwondo ist die Kampfkunst der Distanz. Anders als Ringen oder Judo sucht sie explizit den Abstand zum Gegner \u2014 ihre charakteristischen, weit ausholenden Beintechniken erlauben es, einen Angriff zu setzen, ohne in direkten K\u00f6rperkontakt zu geraten. Taekwondo ist zugleich eine der am klarsten systematisierten Kampfk\u00fcnste: ein durchdachtes G\u00fcrtelsystem, exakt katalogisierte Techniken, ein hoher Anteil an theoretischem und analytischem Verst\u00e4ndnis der Bewegungsmechanik. Das entspricht der Welt des Typs 5: dem Bed\u00fcrfnis nach Abstand als Schutz, der Vorliebe f\u00fcr klare, durchdachte Systeme, der Sicherheit, die aus genauer Analyse statt aus k\u00f6rperlicher N\u00e4he entsteht. Der Taekwondoin trifft aus der Distanz \u2014 pr\u00e4zise, kalkuliert, ohne sich in ein Handgemenge zu begeben. Die Leidenschaft des Geizes zeigt sich als sparsamer Einsatz von N\u00e4he: Kontakt nur im genau kalkulierten Moment.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Faustkampf: Wachsamkeit, Deckung und gepr\u00fcftes Vertrauen</h3>
        <p class="vb-intro">Der klassische Faustkampf \u2014 der Vorl\u00e4ufer des modernen Boxens, in vielen Kulturen als reine waffenlose Auseinandersetzung von Faust gegen Faust \u00fcberliefert \u2014 lebt von einem einzigen Grundprinzip: der st\u00e4ndigen Wachsamkeit. Wer die Deckung auch nur f\u00fcr einen Moment senkt, wird getroffen. Der Faustk\u00e4mpfer beobachtet unabl\u00e4ssig die kleinsten Signale im Gesicht und in der Schulterhaltung des Gegners, um dessen n\u00e4chsten Schlag vorherzuahnen. Das entspricht der Grundhaltung des Typs 6: der permanenten inneren Wachsamkeit, dem Scannen der Umgebung nach Gefahr, dem Bed\u00fcrfnis, erst zu pr\u00fcfen, bevor man sich \u00f6ffnet. Faustkampf ist keine Kunst der gro\u00dfen Gesten, sondern der kleinen, st\u00e4ndigen Korrekturen \u2014 Schritt f\u00fcr Schritt, Deckung f\u00fcr Deckung, im Zweifel lieber einmal zu viel gepr\u00fcft als einmal zu wenig. Die Leidenschaft der Angst zeigt sich als nie ganz abschaltende innere Alarmbereitschaft.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Kickboxen: Tempo, Vielfalt und explosive Energie</h3>
        <p class="vb-intro">Kickboxen verbindet Faustst\u00f6\u00dfe und Fu\u00dftritte zu einem schnellen, abwechslungsreichen, kombinationsreichen Kampfstil, der st\u00e4ndig neue Optionen er\u00f6ffnet \u2014 Kombinationen aus Boxen, Karate, Taekwondo und Muay Thai flie\u00dfen hier zusammen. Es ist eine der energiereichsten, tempointensivsten Kampfsportarten \u00fcberhaupt: hohe Schlagfrequenz, wechselnde Distanzen, st\u00e4ndige Bewegung. Kein Moment gleicht dem anderen, kein Kampf verl\u00e4uft nach festem Schema. Das entspricht der Lebendigkeit des Typs 7: dem Bed\u00fcrfnis nach Abwechslung, Tempo und einer F\u00fclle an M\u00f6glichkeiten, der Abneigung gegen starre, eint\u00f6nige Wiederholung. Der Kickboxer sucht nicht die eine perfekte Technik, sondern die gr\u00f6\u00dftm\u00f6gliche Bandbreite an Optionen \u2014 F\u00e4uste, F\u00fc\u00dfe, Knie, Kombinationen ohne Ende. Die Leidenschaft der V\u00f6llerei zeigt sich als unstillbarer Hunger nach immer neuen Reizen und Bewegungsm\u00f6glichkeiten.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Boxen: Direkte Kraft und kompromisslose Konfrontation</h3>
        <p class="vb-intro">Boxen ist die reinste, direkteste Form der k\u00f6rperlichen Konfrontation, die es im Kampfsport gibt \u2014 keine Tritte, keine W\u00fcrfe, keine Ausweichman\u00f6ver in andere Techniken, nur die Faust, die geradlinig auf den Gegner trifft. Zwei Menschen stehen sich gegen\u00fcber, ohne Ablenkung, ohne Umweg, und messen ihre Kraft in ihrer klarsten Ausprägung. Boxen verlangt, den Schmerz auszuhalten und zur\u00fcckzuschlagen, den eigenen Willen \u00fcber die Ersch\u00f6pfung zu stellen. Das entspricht der Grundhaltung des Typs 8: der Vorliebe f\u00fcr die direkte, unverstellte Auseinandersetzung, dem Misstrauen gegen\u00fcber Umwegen und Taktiken, die die eigentliche Kraftfrage verschleiern. Der Boxer verhandelt nicht \u2014 er tritt an, steht durch und schl\u00e4gt zur\u00fcck. Die Leidenschaft der Gier (\u00dcberma\u00df) zeigt sich als der Drang, die eigene Kraft bis an die Grenze und dar\u00fcber hinaus zu sp\u00fcren und zu beweisen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Aikido: Harmonie statt Konfrontation</h3>
        <p class="vb-intro">Aikido ist die einzige gro\u00dfe Kampfkunst, die keinen eigenen Angriff kennt \u2014 ihr Begr\u00fcnder Morihei Ueshiba entwickelte sie ausdr\u00fccklich als \u201eWeg der Harmonisierung der Energie". Der Aikidoka greift nicht an, er l\u00f6st die Angriffsenergie des Gegners auf, indem er sich mit ihr verbindet, sie umlenkt und in einen kreisf\u00f6rmigen, harmlosen Wurf \u00fcberf\u00fchrt \u2014 ohne Kraft gegen Kraft zu setzen. Am Ende der Technik steht im Idealfall kein besiegter Gegner, sondern eine wiederhergestellte Ordnung, in der niemand ernsthaft verletzt wurde. Das entspricht der tiefsten Sehnsucht des Typs 9: Konflikt nicht durch Konfrontation, sondern durch Harmonisierung aufzul\u00f6sen, die Energie des Gegen\u00fcbers nicht zu brechen, sondern in etwas Friedliches zu wandeln. Aikido ist Kampfkunst als Vers\u00f6hnung \u2014 St\u00e4rke, die sich nicht durchsetzt, sondern integriert. Die Leidenschaft der Tr\u00e4gheit zeigt sich als tiefer Wunsch, dass am Ende jeder Bewegung wieder Ruhe und Einklang stehen.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"hunderassen-der-9-typen", label:"Hunderassen der 9 Typen"},
        {route:"blumenarten-der-9-typen", label:"Blumenarten der 9 Typen"},
        {route:"superpower-der-9-typen", label:"Superpower der 9 Typen"},
      ])}
    </div>
  `);
}

function grimmsMaerchenDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Grimms M\u00e4rchen der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Kaum eine Erz\u00e4hlform tr\u00e4gt archetypisches Wissen so unmittelbar weiter wie das M\u00e4rchen. In wenigen, klaren Bildern erz\u00e4hlen die Grimm'schen M\u00e4rchen von genau jenen inneren K\u00e4mpfen, Sehns\u00fcchten und Erl\u00f6sungswegen, die auch das Enneagramm beschreibt \u2014 Neid, Stolz, Tr\u00e4gheit, Gier, Angst, nicht als abstrakte Begriffe, sondern als Hexen, W\u00f6lfe, verzauberte Prinzen und tapfere Schneiderlein. Genau deshalb sind M\u00e4rchen f\u00fcr Kinder so wichtig: Sie lassen die Grundprinzipien dieser Welt fr\u00fch und auf einer Ebene erfahrbar werden, die kein Sachbuch erreicht \u2014 auch wenn sie manchmal unbequem, ja grausam sind. Denn sie erz\u00e4hlen von der Wirklichkeit, nicht von einer besch\u00f6nigten Version davon. Das Vorlesen von M\u00e4rchen ist heute seltener geworden, als es sein sollte \u2014 dabei br\u00e4uchten gerade Kinder diese fr\u00fchen, archetypischen Landkarten der Seele.</p>
      <img src="./assets/grimms-maerchen-der-9-typen.jpg" alt="Grimms M\u00e4rchen und Enneagramm-Strukturen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />

      <div style="display:flex;flex-wrap:wrap;gap:0.5rem;justify-content:center;margin:0 0 2rem;padding:1rem;background:var(--paper);border-radius:10px;border:1px solid var(--line);">
        <span style="font-size:0.8rem;font-weight:700;color:var(--gray-mid);width:100%;text-align:center;margin-bottom:0.3rem;">Schnellzugriff \u2014 direkt zum Typ</span>
        ${[1,2,3,4,5,6,7,8,9].map(n => `<a href="javascript:void(0)" onclick="document.getElementById('grimm-typ-${n}').scrollIntoView({behavior:'smooth',block:'start'})" style="font-size:0.85rem;font-weight:700;padding:0.3rem 0.7rem;border-radius:6px;background:linear-gradient(160deg, ${typeColor(n)}22, ${typeColor(n)}0d);color:${typeColor(n)};text-decoration:none;border:1px solid ${typeColor(n)};">Typ ${n}</a>`).join("")}
      </div>

      <div class="vb-section" style="max-width:100%;">

        <h3 id="grimm-typ-1" style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Der Froschk\u00f6nig \u00b7 K\u00f6nig Drosselbart \u00b7 Der Eisenofen</h3>
        <p class="vb-intro">Alle drei M\u00e4rchen erz\u00e4hlen von Verwandlung durch Prinzipientreue \u2014 davon, dass Erl\u00f6sung nicht durch Gef\u00fchl, sondern durch das Einhalten des rechten Weges geschieht. Genau das ist die innerste Logik des Typs 1.</p>
        <p class="vb-intro"><strong>Der Froschk\u00f6nig:</strong> Die Prinzessin verspricht dem Frosch aus Not, ihn als Gef\u00e4hrten zu akzeptieren \u2014 und muss dieses Versprechen sp\u00e4ter gegen ihren Ekel halten. Erst als sie ihr Wort tats\u00e4chlich einl\u00f6st, nicht weil sie will, sondern weil es richtig ist, l\u00f6st sich der Zauber. Ein Urbild des Typ-1-Prinzips: Nicht das Gef\u00fchl entscheidet, sondern die Verpflichtung, die man eingegangen ist.</p>
        <p class="vb-intro"><strong>K\u00f6nig Drosselbart:</strong> Eine hochm\u00fctige Prinzessin, die jeden Bewerber verspottet, wird durch eine harte Lektion in Demut gef\u00fchrt \u2014 verkleidet als Bettler muss sie ihren eigenen Hochmut am eigenen Leib erfahren, bevor sie zur wahren, ungek\u00fcnstelten Integrit\u00e4t finden kann. Die L\u00e4uterung falschen Stolzes zu echter Rechtschaffenheit ist ein zentrales Typ-1-Motiv.</p>
        <p class="vb-intro"><strong>Der Eisenofen:</strong> Ein verzauberter Prinz kann nur erl\u00f6st werden, wenn eine treue Gef\u00e4hrtin eine Reihe schwieriger, genau einzuhaltender Aufgaben erf\u00fcllt \u2014 und selbst als sie gegen eine einzige Regel verst\u00f6\u00dft, muss sie den Fehler durch beharrliches, korrektes Handeln wiedergutmachen. Erl\u00f6sung als Belohnung f\u00fcr Beharrlichkeit trotz R\u00fcckschl\u00e4gen.</p>

        <h3 id="grimm-typ-2" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Rotk\u00e4ppchen \u00b7 Rapunzel \u00b7 Der s\u00fc\u00dfe Brei</h3>
        <p class="vb-intro">Diese drei M\u00e4rchen kreisen um F\u00fcrsorge, N\u00e4he und Nahrung \u2014 und um deren Schattenseite: Geben, Binden und N\u00e4hren, das aus dem Gleichgewicht ger\u00e4t. Ein Kernthema des Typs 2.</p>
        <p class="vb-intro"><strong>Rotk\u00e4ppchen:</strong> Ein M\u00e4dchen bringt liebevoll Essen zur kranken Gro\u00dfmutter \u2014 und wird durch ihre eigene Gutgl\u00e4ubigkeit und Grenzenlosigkeit zur Beute des Wolfs. Ein Bild daf\u00fcr, wie das reine Bed\u00fcrfnis zu geben und zu versorgen blind machen kann f\u00fcr Gefahr und f\u00fcr die eigenen Grenzen.</p>
        <p class="vb-intro"><strong>Rapunzel:</strong> Eine Zauberin sperrt ein M\u00e4dchen aus vermeintlicher F\u00fcrsorge in einen Turm und l\u00e4sst niemanden an sie heran \u2014 die Schattenseite der Typ-2-Energie in Reinform: Liebe, die zu Besitz und Kontrolle wird, F\u00fcrsorge, die den anderen einsperrt statt ihn wachsen zu lassen.</p>
        <p class="vb-intro"><strong>Der s\u00fc\u00dfe Brei:</strong> Ein magischer Topf, der auf Zuruf endlos Brei kocht, ger\u00e4t au\u00dfer Kontrolle und \u00fcberflutet das ganze Dorf. Ein treffendes Bild f\u00fcr ungebremstes Geben und N\u00e4hren, das \u2014 einmal in Gang gesetzt \u2014 sich selbst nicht mehr zu stoppen wei\u00df.</p>

        <h3 id="grimm-typ-3" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Marienkind \u00b7 Doktor Allwissend \u00b7 Der Meisterdieb</h3>
        <p class="vb-intro">In allen drei Geschichten geht es um Image, T\u00e4uschung und die Frage, was einen wirklichen Wert schafft \u2014 Leistung, Schein oder Wahrheit. Der zentrale Konflikt des Typs 3.</p>
        <p class="vb-intro"><strong>Marienkind:</strong> Ein M\u00e4dchen \u00f6ffnet aus Neugier eine verbotene T\u00fcr, leugnet die Tat jedoch beharrlich, um ihr Bild der Unschuld zu wahren \u2014 und verliert daf\u00fcr ihre Stimme. Erst das ehrliche Bekenntnis, das Ablegen der Fassade, bringt die Erl\u00f6sung. Image gegen Wahrheit \u2014 ein Kernthema von Typ 3.</p>
        <p class="vb-intro"><strong>Doktor Allwissend:</strong> Ein einfacher Bauer gibt sich durch geschickte Inszenierung als allwissender Gelehrter aus \u2014 und hat tats\u00e4chlich Erfolg, allein durch die \u00fcberzeugende Darstellung, nicht durch echtes Wissen. Ein M\u00e4rchen \u00fcber die Kraft (und Gefahr) der reinen Selbstdarstellung.</p>
        <p class="vb-intro"><strong>Der Meisterdieb:</strong> Ein gewiefter Held beweist seine F\u00e4higkeiten durch spektakul\u00e4re, \u00f6ffentlich bestaunte Kunstst\u00fccke \u2014 sein Wert bemisst sich an der Wirkung vor Publikum, nicht an stiller Tugend. Leistung als B\u00fchne, auf der man gl\u00e4nzen muss.</p>

        <h3 id="grimm-typ-4" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Schneewittchen \u00b7 Vom Fischer und seiner Frau \u00b7 Jorinde und Joringel</h3>
        <p class="vb-intro">Drei Geschichten \u00fcber Einzigartigkeit, unstillbare Sehnsucht und den Schmerz des Verlusts \u2014 Grundmelodien des Typs 4.</p>
        <p class="vb-intro"><strong>Schneewittchen:</strong> Die Stiefmutter kann die einzigartige Sch\u00f6nheit der Tochter nicht ertragen und verfolgt sie bis zum vermeintlichen Tod. Ein M\u00e4rchen \u00fcber Neid auf das Besondere im anderen, \u00fcber Isolation, Verlust der eigenen Mitte \u2014 und die Wiedererweckung durch echte, unverstellte Liebe.</p>
        <p class="vb-intro"><strong>Vom Fischer und seiner Frau:</strong> Eine Frau w\u00fcnscht sich immer mehr \u2014 vom H\u00e4uschen zum Palast, vom K\u00f6nig zum Papst, zuletzt will sie sein wie Gott selbst \u2014 und verliert am Ende alles. Der endlose Hunger nach dem, was fehlt, als Kern der Erz\u00e4hlung.</p>
        <p class="vb-intro"><strong>Jorinde und Joringel:</strong> Zwei Liebende werden durch eine Verzauberung brutal getrennt, die Sehnsucht nach der verlorenen Verbindung zieht sich \u00fcber Jahre \u2014 bis Beharrlichkeit und ein magisches Zeichen die Wiedervereinigung erm\u00f6glichen. Sehnsucht, Verlust und das Festhalten an dem, was einmal ganz war.</p>

        <h3 id="grimm-typ-5" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 H\u00e4nsel und Gretel \u00b7 Das tapfere Schneiderlein \u00b7 Rumpelstilzchen</h3>
        <p class="vb-intro">Drei Geschichten, in denen Verstand, Wissen und List \u00fcber rohe Kraft siegen \u2014 die \u00dcberlebensstrategie des Typs 5.</p>
        <p class="vb-intro"><strong>H\u00e4nsel und Gretel:</strong> Im Wald ausgesetzte Kinder \u00fcberleben nicht durch Kraft, sondern durch Scharfsinn \u2014 Brotkrumen als Orientierungssystem, eine kluge List, um der Hexe zu entkommen. \u00dcberleben durch Denken, nicht durch k\u00f6rperliche St\u00e4rke.</p>
        <p class="vb-intro"><strong>Das tapfere Schneiderlein:</strong> Ein kleiner, k\u00f6rperlich unterlegener Schneider besiegt Riesen und Einh\u00f6rner allein durch Cleverness, Sprache und geschickte T\u00e4uschung. Der Intellekt als \u00fcberlegene Waffe gegen\u00fcber roher Gewalt \u2014 ein Urbild des Typ-5-Prinzips.</p>
        <p class="vb-intro"><strong>Rumpelstilzchen:</strong> Das Wissen um den geheimen Namen des M\u00e4nnchens wird zur einzigen Rettung der K\u00f6nigin \u2014 Wissen als Schl\u00fcssel zur Macht, als das eine entscheidende Detail, das \u00fcber Sieg oder Niederlage entscheidet.</p>

        <h3 id="grimm-typ-6" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Phobisch: Der Wolf und die sieben Gei\u00dflein \u00b7 Kontraphobisch: M\u00e4rchen von einem, der auszog, das F\u00fcrchten zu lernen</h3>
        <p class="vb-intro">Der Typ 6 zeigt sich im Enneagramm in zwei gegens\u00e4tzlichen Auspr\u00e4gungen \u2014 der phobischen (vorsichtig-wachsamen) und der kontraphobischen (der Angst aktiv entgegentretenden) Variante. Beide finden sich hier exemplarisch.</p>
        <p class="vb-intro"><strong>Der Wolf und die sieben Gei\u00dflein (phobisch):</strong> Die Gei\u00dfenmutter warnt eindringlich vor dem Wolf, der sich als sie selbst tarnt \u2014 die Gei\u00dflein m\u00fcssen lernen, jedes Zeichen genau zu pr\u00fcfen, bevor sie vertrauen. Wachsamkeit und Misstrauen als \u00dcberlebensstrategie, Sicherheit durch st\u00e4ndige Pr\u00fcfung.</p>
        <p class="vb-intro"><strong>M\u00e4rchen von einem, der auszog, das F\u00fcrchten zu lernen (kontraphobisch):</strong> Ein junger Mann, der buchst\u00e4blich keine Angst empfinden kann, sucht sie aktiv \u2014 er stellt sich Geistern, Toten und Ungeheuern, um endlich das Gruseln zu lernen. Die Angst nicht zu vermeiden, sondern ihr direkt entgegenzugehen, um sie zu bezwingen \u2014 die kontraphobische Spielart des Typs 6.</p>

        <h3 id="grimm-typ-7" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Hans im Gl\u00fcck \u00b7 Bruder Lustig \u00b7 Der Spielhansel</h3>
        <p class="vb-intro">Drei Figuren, die dem Ernst des Lebens mit Leichtigkeit, Witz und best\u00e4ndiger Umdeutung begegnen \u2014 die Grundhaltung des Typs 7.</p>
        <p class="vb-intro"><strong>Hans im Gl\u00fcck:</strong> Hans tauscht seinen Lohn immer wieder gegen etwas scheinbar Geringeres \u2014 bis er am Ende mit leeren H\u00e4nden dasteht und sich trotzdem als der gl\u00fccklichste Mensch der Welt f\u00fchlt. Die Kunst, jeden Verlust positiv umzudeuten und sich nie von der eigenen guten Laune abbringen zu lassen.</p>
        <p class="vb-intro"><strong>Bruder Lustig:</strong> Ein schlitzohriger, ewig hungriger und ewig fr\u00f6hlicher Ex-Soldat schwindelt sich mit Witz, Chuzpe und einer geh\u00f6rigen Portion Regelbruch durchs Leben \u2014 sogar mit dem Teufel und dem Heiligen Petrus handelt er noch. Lebensfreude, die sich von keiner Autorit\u00e4t einschr\u00e4nken l\u00e4sst.</p>
        <p class="vb-intro"><strong>Der Spielhansel:</strong> Eine Gestalt, die das Leben als Spiel begreift, immer in Bewegung, immer auf der Suche nach der n\u00e4chsten Unterhaltung \u2014 ein Sinnbild f\u00fcr die Rastlosigkeit und den Facettenreichtum, mit dem Typ 7 der Langeweile entkommt.</p>

        <h3 id="grimm-typ-8" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Der starke Hans \u00b7 Der junge Riese \u00b7 Lieb und Leid teilen</h3>
        <p class="vb-intro">Drei Geschichten \u00fcber rohe Kraft, Schutzinstinkt und die Frage, wie sich Macht mit Loyalit\u00e4t verbindet \u2014 zentrale Themen des Typs 8.</p>
        <p class="vb-intro"><strong>Der starke Hans:</strong> Ein Junge mit \u00fcbermenschlicher Kraft bezwingt R\u00e4uber und ein Ungeheuer, um Schw\u00e4chere zu befreien und zu besch\u00fctzen. Kraft, die sich nicht in Zerst\u00f6rung ersch\u00f6pft, sondern sich in den Dienst der Schwachen stellt \u2014 der positive Kern von Typ 8.</p>
        <p class="vb-intro"><strong>Der junge Riese:</strong> Ein k\u00f6rperlich \u00fcberm\u00e4chtiger junger Mann wehrt sich gegen die Ausbeutung durch seinen Vater und sp\u00e4ter durch andere, die seine Kraft f\u00fcr ihre Zwecke missbrauchen wollen. Das Thema Gerechtigkeit und Selbstbehauptung durch St\u00e4rke gegen Unterdr\u00fcckung.</p>
        <p class="vb-intro"><strong>Lieb und Leid teilen:</strong> Ein starker Mann verspricht seiner Braut, mit ihr sowohl Freude als auch Leid zu teilen \u2014 und wird buchst\u00e4blich auf diese Zusage gepr\u00fcft. Loyalit\u00e4t und Besch\u00fctzerprinzip, die auch die eigene Verwundbarkeit nicht verleugnen.</p>

        <h3 id="grimm-typ-9" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Das blaue Licht \u00b7 Der faule Heinz \u00b7 Die 12 faulen Knechte</h3>
        <p class="vb-intro">Drei Geschichten \u00fcber R\u00fcckzug, Tr\u00e4gheit und die untersch\u00e4tzte, oft \u00fcbersehene innere Kraft \u2014 das Spannungsfeld des Typs 9.</p>
        <p class="vb-intro"><strong>Das blaue Licht:</strong> Ein treuer Soldat wird nach Jahren des Dienstes achtlos fortgeschickt und \u00fcbersehen \u2014 bis er eine magische, verborgene Kraft entdeckt, die ihm endlich zu seinem Recht verhilft. Ein Bild f\u00fcr die stille, oft \u00fcbergangene Kraft, die im R\u00fcckzug schlummert und erst geweckt werden muss.</p>
        <p class="vb-intro"><strong>Der faule Heinz:</strong> Eine Figur, die sich mit bemerkenswertem Erfindungsreichtum jeder Anstrengung entzieht und lieber noch mehr Aufwand betreibt, um Arbeit zu vermeiden, als die Arbeit selbst zu tun. Tr\u00e4gheit als zentrales Motiv, der Widerstand gegen jede Form von Aktivit\u00e4t, die den inneren Frieden st\u00f6ren k\u00f6nnte.</p>
        <p class="vb-intro"><strong>Die 12 faulen Knechte:</strong> Eine ganze Gruppe von Knechten, die sich gegenseitig in ihrer Arbeitsvermeidung best\u00e4tigt und mit immer neuen Ausreden dem Handeln entgeht. Kollektive Tr\u00e4gheit und Konfliktvermeidung durch beharrliches Nicht-Tun.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"bagua-zonen-der-9-typen", label:"Bagua-Zonen der 9 Typen"},
        {route:"kampfkunstarten-der-9-typen", label:"Kampfkunstarten der 9 Typen"},
        {route:"limericks", label:"Die 9 Enneagramm-Limericks"},
      ])}
    </div>
  `);
}

function enneagrammEmotionalitaetPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Enneagramm und Emotionalit\u00e4t", "Schaubilder \u00b7 Emotionen & Bewusstsein")}
      <p class="psycho-intro">Emotionalit\u00e4t ist im Enneagramm bewusst wertfrei zu verstehen. Sie ist weder gut noch schlecht \u2014 sie ist Energie, die eine Richtung sucht. Im bewussten Zustand kann Emotionalit\u00e4t eine besondere Qualit\u00e4t sein: ein Segen f\u00fcr andere und f\u00fcr sich selbst, eine Quelle von W\u00e4rme, Tiefe und lebendiger Verbindung. In unbewussten Phasen des Lebens jedoch kann dieselbe Emotionalit\u00e4t genauso zum Fluch werden \u2014 f\u00fcr die Mitmenschen und pl\u00f6tzlich auch f\u00fcr die betroffene Person selbst. Es ist dieselbe Kraft, die tr\u00e4gt oder \u00fcberflutet, verbindet oder verstrickt \u2014 je nachdem, wie viel Bewusstheit ihr zur Seite steht.</p>
      <img src="./assets/enneagramm-emotionalitaet.jpg" alt="Enneagramm und Emotionalit\u00e4t \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />

      <div class="vb-section" style="max-width:100%;">
        <h2 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:var(--ink);">Zwei Gesichter derselben Kraft</h2>
        <p class="vb-intro">Jeder der neun Typen tr\u00e4gt eine eigene emotionale Grundf\u00e4rbung \u2014 eine Art, wie Gef\u00fchl entsteht, sich zeigt, gestaut oder ausgedr\u00fcckt wird. Diese F\u00e4rbung ist an sich neutral. Erst der Grad an Bewusstheit entscheidet, ob sie zur Gabe oder zur Last wird. Im bewussten Zustand wird Emotionalit\u00e4t zu einem Instrument der Wahrnehmung: Sie macht empf\u00e4nglich f\u00fcr die Not und die Freude anderer, sie verleiht Ausdruck Tiefe, sie schafft echte N\u00e4he. Im unbewussten Zustand dagegen l\u00e4uft dieselbe Emotionalit\u00e4t ungefiltert \u2014 sie \u00fcberschwemmt, manipuliert, verwirrt oder erstarrt, ohne dass die Person es zun\u00e4chst selbst bemerkt.</p>
        <p class="vb-intro">Das Schaubild zeigt f\u00fcr jeden Typ diese doppelte M\u00f6glichkeit: die Qualit\u00e4t, die entsteht, wenn Emotionalit\u00e4t bewusst gelebt wird \u2014 und die Verzerrung, die entsteht, wenn sie unbewusst das Steuer \u00fcbernimmt. Es ist derselbe Rohstoff, nur mit unterschiedlichem Grad an innerer Beobachtung.</p>
      </div>

      <div style="display:flex;flex-wrap:wrap;gap:0.5rem;justify-content:center;margin:1rem 0 2rem;padding:1rem;background:var(--paper);border-radius:10px;border:1px solid var(--line);">
        <span style="font-size:0.8rem;font-weight:700;color:var(--gray-mid);width:100%;text-align:center;margin-bottom:0.3rem;">Schnellzugriff \u2014 direkt zum Typ</span>
        ${[1,2,3,4,5,6,7,8,9].map(n => `<a href="javascript:void(0)" onclick="document.getElementById('emo-typ-${n}').scrollIntoView({behavior:'smooth',block:'start'})" style="font-size:0.85rem;font-weight:700;padding:0.3rem 0.7rem;border-radius:6px;background:linear-gradient(160deg, ${typeColor(n)}22, ${typeColor(n)}0d);color:${typeColor(n)};text-decoration:none;border:1px solid ${typeColor(n)};">Typ ${n}</a>`).join("")}
      </div>

      <div class="vb-section" style="max-width:100%;">

        <h3 id="emo-typ-1" style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2014 Die Emotionalit\u00e4t der Richtigkeit</h3>
        <p class="vb-intro">Beim Typ 1 zeigt sich Emotionalit\u00e4t selten roh, sondern meist gefiltert durch das innere Gericht: Bevor ein Gef\u00fchl gezeigt wird, wird gepr\u00fcft, ob es angemessen ist. Bewusst gelebt wird daraus eine warme, verl\u00e4ssliche Anteilnahme \u2014 ein Gef\u00fchl, das genau dort ansetzt, wo es wirklich gebraucht wird, ohne \u00dcbertreibung, aber mit echtem Ernst.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE1):</strong> Bewusst zeigt sich eine stille, f\u00fcrsorgliche Sorgfalt im Allt\u00e4glichen \u2014 Gef\u00fchl, das sich in Ordnung und Verl\u00e4sslichkeit ausdr\u00fcckt. Unbewusst kann daraus permanente innere Anspannung werden, ein st\u00e4ndiges \u00c4rgergef\u00fchl \u00fcber das, was nicht stimmt, das sich in Reizbarkeit oder stillem Groll entl\u00e4dt.</p>
        <p class="vb-intro"><strong>Sozial (SO1):</strong> Bewusst wird Emotionalit\u00e4t zu engagiertem Verantwortungsgef\u00fchl f\u00fcr das Ganze \u2014 ein Mitgef\u00fchl, das sich f\u00fcr gerechte Verh\u00e4ltnisse einsetzt. Unbewusst kippt es in moralische Emp\u00f6rung, in ein Gef\u00fchl der eigenen Rechtschaffenheit, das andere klein macht.</p>
        <p class="vb-intro"><strong>Sexuell (SX1):</strong> Bewusst entsteht eine leidenschaftliche, fast missionarische Intensit\u00e4t im Gef\u00fchl f\u00fcr den anderen \u2014 Emotionalit\u00e4t als Antrieb, die Welt f\u00fcr den Partner besser zu machen. Unbewusst wird daraus Kontrolle im Gewand der F\u00fcrsorge, ein Gef\u00fchl, das dem anderen die eigene Sicht der Dinge aufdr\u00e4ngt.</p>

        <h3 id="emo-typ-2" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2014 Die Emotionalit\u00e4t der Zuwendung</h3>
        <p class="vb-intro">Beim Typ 2 ist Emotionalit\u00e4t von Anfang an nach au\u00dfen gerichtet: auf das Gef\u00fchl des anderen, auf dessen Bed\u00fcrfnis, auf die Beziehung. Bewusst gelebt wird daraus echte Empathie \u2014 ein Gef\u00fchl, das tr\u00e4gt, ohne zu vereinnahmen. Unbewusst wird dasselbe Gef\u00fchl zum Mittel, gebraucht zu werden.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE2):</strong> Bewusst zeigt sich eine liebevolle, fast kindliche W\u00e4rme im engen Kreis \u2014 ein Gef\u00fchl, das Geborgenheit schafft. Unbewusst wird daraus Anh\u00e4nglichkeit und ein stilles Fordern von Aufmerksamkeit, das sich hinter Charme verbirgt.</p>
        <p class="vb-intro"><strong>Sozial (SO2):</strong> Bewusst entsteht ein gro\u00dfz\u00fcgiges, gemeinschaftsstiftendes Mitgef\u00fchl, das viele einschlie\u00dft. Unbewusst kippt es in ein Gef\u00fchl von Unentbehrlichkeit \u2014 die Emotionalit\u00e4t wird zum Beweis der eigenen Wichtigkeit f\u00fcr die Gruppe.</p>
        <p class="vb-intro"><strong>Sexuell (SX2):</strong> Bewusst zeigt sich eine tiefe, hingebungsvolle Intensit\u00e4t in der N\u00e4he zu einem einzelnen Menschen \u2014 verf\u00fchrerische W\u00e4rme, die wirklich beim anderen ist. Unbewusst wird daraus emotionale Vereinnahmung, ein Gef\u00fchl, das den anderen besitzen will, um sich selbst gesehen zu f\u00fchlen.</p>

        <h3 id="emo-typ-3" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2014 Die Emotionalit\u00e4t der Leistung</h3>
        <p class="vb-intro">Beim Typ 3 wird Gef\u00fchl h\u00e4ufig zuerst reguliert, dann erst zugelassen \u2014 es darf nicht im Weg stehen. Bewusst gelebt wird daraus eine ansteckende, motivierende emotionale Energie, die andere mitrei\u00dft. Unbewusst wird Gef\u00fchl zur Nebensache, verdr\u00e4ngt zugunsten von Funktion und Erfolg.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE3):</strong> Bewusst zeigt sich ruhige, sachliche W\u00e4rme, die sich in Zuverl\u00e4ssigkeit und stiller F\u00fcrsorge ausdr\u00fcckt. Unbewusst wird Gef\u00fchl komplett dem Funktionieren untergeordnet \u2014 Ersch\u00f6pfung und innere Leere, die nach au\u00dfen nicht sichtbar werden d\u00fcrfen.</p>
        <p class="vb-intro"><strong>Sozial (SO3):</strong> Bewusst entsteht begeisternde, teamstiftende Energie \u2014 ein Gef\u00fchl, das andere f\u00fcr ein gemeinsames Ziel entflammt. Unbewusst wird Emotionalit\u00e4t zur Inszenierung, zum Mittel, bewundert zu werden, ohne dass echte Verletzlichkeit gezeigt wird.</p>
        <p class="vb-intro"><strong>Sexuell (SX3):</strong> Bewusst zeigt sich intensive, anziehende Leidenschaft, echte Begeisterungsf\u00e4higkeit f\u00fcr den Partner und das gemeinsame Projekt. Unbewusst wird daraus ein Gef\u00fchl, das vor allem beeindrucken will \u2014 N\u00e4he, die an Erfolg und Attraktivit\u00e4t gekn\u00fcpft bleibt.</p>

        <h3 id="emo-typ-4" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2014 Die Emotionalit\u00e4t der Tiefe</h3>
        <p class="vb-intro">Beim Typ 4 ist Emotionalit\u00e4t die eigentliche Muttersprache \u2014 hier wird das Gef\u00fchl direkter erlebt und ausgedr\u00fcckt als bei jedem anderen Typ. Bewusst gelebt wird daraus eine seltene F\u00e4higkeit, Gef\u00fchl in Sch\u00f6nheit, Kunst und echte Begegnung zu verwandeln. Unbewusst wird dieselbe Intensit\u00e4t zur Falle, aus der kein Weg herauszuf\u00fchren scheint.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE4):</strong> Bewusst zeigt sich stille, standhafte emotionale Tiefe, die auch schwere Gef\u00fchle tr\u00e4gt, ohne daran zu zerbrechen. Unbewusst wird daraus z\u00e4her, stiller Leidensdruck \u2014 ein Gef\u00fchl von Entbehrung, das sich kaum mitteilt und innerlich zehrt.</p>
        <p class="vb-intro"><strong>Sozial (SO4):</strong> Bewusst entsteht eine F\u00e4higkeit, das eigene Leid in etwas zu verwandeln, das anderen Trost und Verst\u00e4ndnis schenkt. Unbewusst kippt es in das Gef\u00fchl, mit dem eigenen Schmerz besonders und unverstanden zu sein \u2014 Scham, die sich zur\u00fcckzieht oder anklagt.</p>
        <p class="vb-intro"><strong>Sexuell (SX4):</strong> Bewusst zeigt sich vulkanische, unmittelbare emotionale Ehrlichkeit, die echte, ungesch\u00f6nte N\u00e4he erm\u00f6glicht. Unbewusst wird daraus dramatische Auf- und Abw\u00e4rtsbewegung, ein Gef\u00fchl, das N\u00e4he sucht, indem es Konflikt und Intensit\u00e4t provoziert.</p>

        <h3 id="emo-typ-5" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2014 Die Emotionalit\u00e4t des R\u00fcckzugs</h3>
        <p class="vb-intro">Beim Typ 5 wird Gef\u00fchl zun\u00e4chst nicht ausgedr\u00fcckt, sondern beobachtet \u2014 oft aus sicherer innerer Distanz. Bewusst gelebt wird daraus eine seltene emotionale Klarheit: Gef\u00fchl, das nicht \u00fcberschwemmt, sondern pr\u00e4zise erkannt und dann bewusst geteilt wird. Unbewusst wird dieselbe Distanz zur Mauer.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE5):</strong> Bewusst zeigt sich eine ruhige, in sich gefestigte Gen\u00fcgsamkeit, die anderen Sicherheit vermittelt. Unbewusst wird daraus emotionale Abschottung \u2014 R\u00fcckzug in ein kleines, kontrolliertes Refugium, aus dem Gef\u00fchl kaum noch nach au\u00dfen dringt.</p>
        <p class="vb-intro"><strong>Sozial (SO5):</strong> Bewusst entsteht ein sachliches, aber echtes Interesse am inneren Leben anderer \u2014 Gef\u00fchl, das \u00fcber Verstehen ausgedr\u00fcckt wird. Unbewusst kippt es in \u00fcberlegene Distanz, ein Gef\u00fchl, das sich hinter Wissen und Beobachtung versteckt, statt sich zu zeigen.</p>
        <p class="vb-intro"><strong>Sexuell (SX5):</strong> Bewusst zeigt sich \u00fcberraschend intensive, fast schw\u00e4rmerische Hingabe an einen einzelnen Menschen oder ein Thema. Unbewusst wird daraus verzehrende innere Vertiefung, die sich \u00e4u\u00dferlich kaum zeigt und den anderen im Ungewissen l\u00e4sst.</p>

        <h3 id="emo-typ-6" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2014 Die Emotionalit\u00e4t der Wachsamkeit</h3>
        <p class="vb-intro">Beim Typ 6 ist Gef\u00fchl eng mit Sicherheit verkn\u00fcpft \u2014 es entsteht als Antwort auf wahrgenommene Bedrohung oder Verbindung. Bewusst gelebt wird daraus loyale, verl\u00e4ssliche W\u00e4rme und ein feines Gesp\u00fcr f\u00fcr die Gef\u00fchle anderer. Unbewusst wird dieselbe Sensibilit\u00e4t zur Quelle st\u00e4ndiger innerer Unruhe.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE6):</strong> Bewusst zeigt sich warme, famili\u00e4re Verbundenheit, die Sicherheit im engen Kreis schafft. Unbewusst wird daraus \u00e4ngstliche Anh\u00e4nglichkeit \u2014 ein Gef\u00fchl, das sich an Vertraute klammert, aus Furcht vor dem Alleinsein.</p>
        <p class="vb-intro"><strong>Sozial (SO6):</strong> Bewusst entsteht Loyalit\u00e4t und emotionales Engagement f\u00fcr die Gruppe, echtes Pflichtgef\u00fchl. Unbewusst kippt es in Misstrauen und die Suche nach klaren Autorit\u00e4ten, an denen sich das eigene Gef\u00fchl festmachen kann.</p>
        <p class="vb-intro"><strong>Sexuell (SX6):</strong> Bewusst zeigt sich mutige, kraftvolle emotionale Intensit\u00e4t, die N\u00e4he direkt und ungesch\u00fctzt sucht. Unbewusst wird daraus impulsive Heftigkeit \u2014 ein Gef\u00fchl, das die eigene Angst durch Angriff statt durch R\u00fcckzug beantwortet.</p>

        <h3 id="emo-typ-7" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2014 Die Emotionalit\u00e4t der Begeisterung</h3>
        <p class="vb-intro">Beim Typ 7 sucht Gef\u00fchl instinktiv die leichte, angenehme Seite \u2014 schwere Emotionen werden schnell umgedeutet oder \u00fcberspielt. Bewusst gelebt wird daraus ansteckende Lebensfreude, die auch andere aus schweren Momenten holt. Unbewusst wird dieselbe Leichtigkeit zur Flucht.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE7):</strong> Bewusst zeigt sich praktische, erdende Fr\u00f6hlichkeit, die Sicherheit mit Genuss verbindet. Unbewusst wird daraus rastlose Ablenkung \u2014 ein Gef\u00fchl, das st\u00e4ndig nach dem n\u00e4chsten angenehmen Reiz sucht, um Unruhe nicht sp\u00fcren zu m\u00fcssen.</p>
        <p class="vb-intro"><strong>Sozial (SO7):</strong> Bewusst entsteht gro\u00dfz\u00fcgige, idealistische Begeisterung, die andere f\u00fcr eine gute Sache mitrei\u00dft. Unbewusst kippt es in Selbstaufopferung mit verstecktem Groll \u2014 Gef\u00fchl, das gibt, aber innerlich z\u00e4hlt, was es zur\u00fcckbekommt.</p>
        <p class="vb-intro"><strong>Sexuell (SX7):</strong> Bewusst zeigt sich intensive, verzaubernde Begeisterungsf\u00e4higkeit, die andere mit ihrer Vision ansteckt. Unbewusst wird daraus impulsive Idealisierung \u2014 ein Gef\u00fchl, das sich schnell verliebt, um ebenso schnell zu entt\u00e4uschen und weiterzuziehen.</p>

        <h3 id="emo-typ-8" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2014 Die Emotionalit\u00e4t der Kraft</h3>
        <p class="vb-intro">Beim Typ 8 wird Gef\u00fchl selten als solches benannt \u2014 es zeigt sich h\u00e4ufig als Handlung, als Energie, als Pr\u00e4senz. Bewusst gelebt wird daraus starke, besch\u00fctzende Zuwendung, die anderen Sicherheit gibt. Unbewusst wird dieselbe Kraft zur Wucht, die \u00fcberrollt.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE8):</strong> Bewusst zeigt sich robuste, unkomplizierte F\u00fcrsorge \u2014 Gef\u00fchl, das sich in Handeln und Versorgen ausdr\u00fcckt. Unbewusst wird daraus Dickfelligkeit, ein \u00dcberspielen eigener Verletzlichkeit durch immer mehr Kontrolle.</p>
        <p class="vb-intro"><strong>Sozial (SO8):</strong> Bewusst entsteht loyale, aufopfernde Kraft im Dienst einer Gruppe oder Sache, ein Gef\u00fchl von Verantwortung, das tr\u00e4gt. Unbewusst kippt es in autorit\u00e4res Dominanzverhalten \u2014 Emotionalit\u00e4t, die keine Gegenmeinung duldet.</p>
        <p class="vb-intro"><strong>Sexuell (SX8):</strong> Bewusst zeigt sich intensive, hingebungsvolle Leidenschaft, die den Partner ganz und kompromisslos liebt. Unbewusst wird daraus besitzergreifende Heftigkeit \u2014 ein Gef\u00fchl, das N\u00e4he mit Kontrolle verwechselt.</p>

        <h3 id="emo-typ-9" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2014 Die Emotionalit\u00e4t der Harmonie</h3>
        <p class="vb-intro">Beim Typ 9 wird eigenes Gef\u00fchl h\u00e4ufig zuerst zur\u00fcckgestellt, um Frieden zu wahren \u2014 die eigene Emotionalit\u00e4t tritt hinter die der anderen zur\u00fcck. Bewusst gelebt wird daraus eine seltene, umfassende F\u00e4higkeit zum Mitgef\u00fchl, die viele Perspektiven zugleich halten kann. Unbewusst wird dieselbe F\u00e4higkeit zum Verschwinden im Gef\u00fchl anderer.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE9):</strong> Bewusst zeigt sich stille, tragende Gelassenheit, die Geborgenheit ausstrahlt, ohne viel Aufhebens zu machen. Unbewusst wird daraus emotionale Bet\u00e4ubung \u2014 ein R\u00fcckzug in Gewohnheit und Ablenkung, um das eigene Gef\u00fchl gar nicht erst sp\u00fcren zu m\u00fcssen.</p>
        <p class="vb-intro"><strong>Sozial (SO9):</strong> Bewusst entsteht eine warme, verbindende Pr\u00e4senz, die Gruppen zusammenh\u00e4lt, ohne sich in den Vordergrund zu dr\u00e4ngen. Unbewusst kippt es in Selbstverleugnung \u2014 ein Gef\u00fchl, das sich f\u00fcr alle einsetzt, nur f\u00fcr sich selbst nicht.</p>
        <p class="vb-intro"><strong>Sexuell (SX9):</strong> Bewusst zeigt sich intensive, verschmelzende Hingabe an einen geliebten Menschen \u2014 Gef\u00fchl, das sich ganz auf den anderen einl\u00e4sst. Unbewusst wird daraus Selbstaufgabe, ein Verlust der eigenen Identit\u00e4t im Gef\u00fchl und in den Vorlieben des Partners.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("sprache-unserer-beziehungen", "Wie die 9 Typen N\u00e4he, Bindung und Gef\u00fchl in Beziehungen erleben \u2014 und was jeder Typ braucht, um emotional wirklich anzukommen.", "Die Sprache unserer Beziehungen")}
        ${bookTip("sprache-der-sexualit\u00e4t", "Emotionalit\u00e4t und Instinkt im Zusammenspiel \u2014 wie sich Gef\u00fchl und Begehren bei den 9 Typen und ihren Subtypen verbinden.", "Die Sprache unserer Sexualit\u00e4t")}
        ${bookTip("die-verborgene-dynamik-der-27-subtypen", "Die 27 Subtypen im Detail \u2014 Normal-, Verst\u00e4rkungs- und Kontratyp jedes Enneagrammtyps ausf\u00fchrlich erl\u00e4utert.", "Die verborgene Dynamik der 27 Subtypen")}
      </div>
      ${relatedLinks([
        {route:"basisemotionen", label:"Basisemotionen der 9 Typen"},
        {route:"zornverhalten", label:"Zornverhalten der 9 Typen"},
        {route:"leidenschaft-und-wunde", label:"Leidenschaft und Wunde"},
      ])}
    </div>
  `);
}

function enneagrammInstinktPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Enneagramm und Instinkt", "Schaubilder \u00b7 Emotionen & Bewusstsein")}
      <p class="psycho-intro">Instinkt ist im Enneagramm die unmittelbare, k\u00f6rperliche Antriebskraft \u2014 die Energie, die handelt, bevor der Verstand fertig gedacht hat. Auch sie ist an sich wertfrei: weder gut noch schlecht, sondern reine Lebenskraft, die Richtung sucht. Bewusst gelebt wird Instinkt zu gesunder Pr\u00e4senz, zu Tatkraft, die im richtigen Moment zupackt, und zu einem verl\u00e4sslichen Gesp\u00fcr f\u00fcr das, was jetzt gebraucht wird. Unbewusst wird dieselbe Energie zu Impulsivit\u00e4t, zu Reaktion ohne Innehalten \u2014 der K\u00f6rper handelt, bevor die Person selbst begreift, warum.</p>
      <img src="./assets/enneagramm-instinkt.jpg" alt="Enneagramm und Instinkt \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />

      <div class="vb-section" style="max-width:100%;">
        <h2 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:var(--ink);">Zwei Gesichter derselben Kraft</h2>
        <p class="vb-intro">Jeder der neun Typen tr\u00e4gt eine eigene instinktive Grundf\u00e4rbung \u2014 eine Art, wie K\u00f6rperenergie entsteht, sich staut oder in Handlung entl\u00e4dt. Diese F\u00e4rbung ist an sich neutral. Erst der Grad an Bewusstheit entscheidet, ob sie zur verl\u00e4sslichen inneren Kompassnadel wird oder zum blinden Reflex. Im bewussten Zustand wird Instinkt zu einem Instrument der Wahrnehmung: Er macht handlungsf\u00e4hig, verankert im K\u00f6rper, verleiht Pr\u00e4senz und ein feines Gesp\u00fcr f\u00fcr den richtigen Moment. Im unbewussten Zustand dagegen l\u00e4uft dieselbe instinktive Kraft ungefiltert \u2014 sie \u00fcberrollt, verh\u00e4rtet, erstarrt oder verausgabt sich, ohne dass die Person es zun\u00e4chst selbst bemerkt.</p>
        <p class="vb-intro">Das Schaubild zeigt f\u00fcr jeden Typ diese doppelte M\u00f6glichkeit: die Qualit\u00e4t, die entsteht, wenn Instinkt bewusst gelebt wird \u2014 und die Verzerrung, die entsteht, wenn er unbewusst das Steuer \u00fcbernimmt. Es ist dieselbe K\u00f6rperenergie, nur mit unterschiedlichem Grad an innerer Beobachtung.</p>
      </div>

      <div style="display:flex;flex-wrap:wrap;gap:0.5rem;justify-content:center;margin:1rem 0 2rem;padding:1rem;background:var(--paper);border-radius:10px;border:1px solid var(--line);">
        <span style="font-size:0.8rem;font-weight:700;color:var(--gray-mid);width:100%;text-align:center;margin-bottom:0.3rem;">Schnellzugriff \u2014 direkt zum Typ</span>
        ${[1,2,3,4,5,6,7,8,9].map(n => `<a href="javascript:void(0)" onclick="document.getElementById('ins-typ-${n}').scrollIntoView({behavior:'smooth',block:'start'})" style="font-size:0.85rem;font-weight:700;padding:0.3rem 0.7rem;border-radius:6px;background:linear-gradient(160deg, ${typeColor(n)}22, ${typeColor(n)}0d);color:${typeColor(n)};text-decoration:none;border:1px solid ${typeColor(n)};">Typ ${n}</a>`).join("")}
      </div>

      <div class="vb-section" style="max-width:100%;">

        <h3 id="ins-typ-1" style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2014 Der Instinkt der Richtigkeit</h3>
        <p class="vb-intro">Beim Typ 1 ist Instinkt eng an inneren Widerstand gekoppelt: Der K\u00f6rper spannt sich an, wo etwas nicht stimmt, noch bevor der Verstand es benennt. Bewusst gelebt wird daraus pr\u00e4zise, zupackende Tatkraft, die im richtigen Moment korrigiert, ohne zu \u00fcberkorrigieren.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE1):</strong> Bewusst zeigt sich ein wacher, k\u00f6rperlich verankerter Sinn f\u00fcr Ordnung im eigenen Umfeld \u2014 Instinkt, der pragmatisch anpackt. Unbewusst wird daraus chronische muskul\u00e4re Anspannung, ein K\u00f6rper, der st\u00e4ndig im Anschlag steht.</p>
        <p class="vb-intro"><strong>Sozial (SO1):</strong> Bewusst entsteht entschlossene, auf das Ganze gerichtete Handlungskraft, die Missst\u00e4nde unmittelbar angeht. Unbewusst kippt es in reflexhafte Belehrung, einen K\u00f6rper, der sich aufrichtet, um andere zurechtzuweisen.</p>
        <p class="vb-intro"><strong>Sexuell (SX1):</strong> Bewusst zeigt sich intensive, fast feurige Energie, die den Partner mitrei\u00dft und gemeinsam ver\u00e4ndert. Unbewusst wird daraus impulsive Ungeduld \u2014 ein K\u00f6rper, der dr\u00e4ngt, bevor der andere bereit ist.</p>

        <h3 id="ins-typ-2" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2014 Der Instinkt der Zuwendung</h3>
        <p class="vb-intro">Beim Typ 2 flie\u00dft instinktive Energie sofort nach au\u00dfen, in Richtung des anderen \u2014 der K\u00f6rper bewegt sich, bevor der Kopf entscheidet, zu helfen. Bewusst gelebt wird daraus warme, verl\u00e4ssliche Pr\u00e4senz, die sp\u00fcrt, wo sie gebraucht wird.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE2):</strong> Bewusst zeigt sich verspielte, k\u00f6rpernahe Zuneigung im engen Kreis \u2014 Instinkt, der N\u00e4he unmittelbar sucht und schenkt. Unbewusst wird daraus rastlose Betriebsamkeit, ein K\u00f6rper, der st\u00e4ndig etwas f\u00fcr andere tun muss, um sich zu beruhigen.</p>
        <p class="vb-intro"><strong>Sozial (SO2):</strong> Bewusst entsteht tatkr\u00e4ftige, gemeinschaftsstiftende Energie, die viele gleichzeitig im Blick beh\u00e4lt. Unbewusst kippt es in \u00fcberzogenen Aktivismus \u2014 ein K\u00f6rper, der sich verausgabt, um unentbehrlich zu bleiben.</p>
        <p class="vb-intro"><strong>Sexuell (SX2):</strong> Bewusst zeigt sich anziehende, hingebungsvolle K\u00f6rperpr\u00e4senz, ganz auf den einen Menschen gerichtet. Unbewusst wird daraus instinktives Werben um Aufmerksamkeit, das keine Pause kennt.</p>

        <h3 id="ins-typ-3" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2014 Der Instinkt der Leistung</h3>
        <p class="vb-intro">Beim Typ 3 ist Instinkt eng mit Tempo und Effizienz verbunden \u2014 der K\u00f6rper geht in Bewegung, sobald ein Ziel erkennbar ist. Bewusst gelebt wird daraus m\u00fchelose, ansteckende Tatkraft, die andere ins Handeln bringt.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE3):</strong> Bewusst zeigt sich unerm\u00fcdliche, bodenst\u00e4ndige Schaffenskraft, die Sicherheit durch stetiges Tun schafft. Unbewusst wird daraus Getriebenheit \u2014 ein K\u00f6rper, der nicht abschalten kann, weil Stillstand sich wie Gefahr anf\u00fchlt.</p>
        <p class="vb-intro"><strong>Sozial (SO3):</strong> Bewusst entsteht dynamische, teamf\u00fchrende Energie, die ein gemeinsames Vorhaben voranbringt. Unbewusst kippt es in ruheloses Statusstreben \u2014 ein K\u00f6rper in permanenter Selbstoptimierung.</p>
        <p class="vb-intro"><strong>Sexuell (SX3):</strong> Bewusst zeigt sich magnetische, selbstsichere K\u00f6rperpr\u00e4senz, die anzieht, ohne zu inszenieren. Unbewusst wird daraus rastlose Selbstdarstellung, die Energie in Wirkung statt in echte N\u00e4he steckt.</p>

        <h3 id="ins-typ-4" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2014 Der Instinkt der Intensit\u00e4t</h3>
        <p class="vb-intro">Beim Typ 4 sucht Instinkt das Besondere, das intensiv Erlebte \u2014 der K\u00f6rper reagiert stark auf Sch\u00f6nheit und Schmerz gleicherma\u00dfen. Bewusst gelebt wird daraus tiefe, verk\u00f6rperte Ausdruckskraft, die Erfahrung in Gestalt verwandelt.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE4):</strong> Bewusst zeigt sich z\u00e4he, standhafte K\u00f6rperkraft, die auch schwere Phasen durchtr\u00e4gt. Unbewusst wird daraus stille Ersch\u00f6pfung, ein K\u00f6rper, der Entbehrung stumm aush\u00e4lt, statt sie auszudr\u00fccken.</p>
        <p class="vb-intro"><strong>Sozial (SO4):</strong> Bewusst entsteht die F\u00e4higkeit, eigene Intensit\u00e4t in Ausdruck zu verwandeln, der andere ber\u00fchrt. Unbewusst kippt es in demonstrative Zur\u00fcckgezogenheit, einen K\u00f6rper, der sich sichtbar aus dem Get\u00fcmmel entfernt.</p>
        <p class="vb-intro"><strong>Sexuell (SX4):</strong> Bewusst zeigt sich vulkanische, unmittelbare K\u00f6rperenergie, die echte Intensit\u00e4t in Beziehung bringt. Unbewusst wird daraus dramatische Eskalation, ein K\u00f6rper, der N\u00e4he \u00fcber Zuspitzung sucht.</p>

        <h3 id="ins-typ-5" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2014 Der Instinkt des R\u00fcckzugs</h3>
        <p class="vb-intro">Beim Typ 5 wird instinktive Energie zuerst zur\u00fcckgehalten, gespart, beobachtet \u2014 der K\u00f6rper h\u00e4lt sich zur\u00fcck, bevor er handelt. Bewusst gelebt wird daraus ruhige, \u00f6konomische Kraft, die genau dann da ist, wenn sie gebraucht wird.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE5):</strong> Bewusst zeigt sich stille Gen\u00fcgsamkeit, ein K\u00f6rper, der mit wenig auskommt und dabei ganz bei sich bleibt. Unbewusst wird daraus fast vollst\u00e4ndiger R\u00fcckzug aus dem eigenen K\u00f6rper, ein Leben vorwiegend im Kopf.</p>
        <p class="vb-intro"><strong>Sozial (SO5):</strong> Bewusst entsteht sachliche, beobachtende Pr\u00e4senz, die sich punktuell und gezielt einbringt. Unbewusst kippt es in distanzierte Passivit\u00e4t, einen K\u00f6rper, der lieber analysiert als handelt.</p>
        <p class="vb-intro"><strong>Sexuell (SX5):</strong> Bewusst zeigt sich \u00fcberraschend intensive Hingabe an einen Menschen oder ein Thema, sobald Vertrauen besteht. Unbewusst wird daraus verzehrende innere Vertiefung, die sich k\u00f6rperlich kaum mehr zeigt.</p>

        <h3 id="ins-typ-6" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2014 Der Instinkt der Wachsamkeit</h3>
        <p class="vb-intro">Beim Typ 6 ist der K\u00f6rper st\u00e4ndig auf Signale von Gefahr oder Sicherheit geeicht \u2014 Instinkt zeigt sich als feine Alarmbereitschaft. Bewusst gelebt wird daraus schnelle, treffsichere Reaktionsf\u00e4higkeit, die sch\u00fctzt, ohne zu l\u00e4hmen.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE6):</strong> Bewusst zeigt sich vorsorgende, bodenst\u00e4ndige Wachsamkeit, die Sicherheit im Alltag herstellt. Unbewusst wird daraus nerv\u00f6se Anspannung, ein K\u00f6rper, der st\u00e4ndig auf das n\u00e4chste Problem vorbereitet ist.</p>
        <p class="vb-intro"><strong>Sozial (SO6):</strong> Bewusst entsteht loyale, verl\u00e4ssliche Pr\u00e4senz im Dienst der Gruppe. Unbewusst kippt es in misstrauische \u00dcberwachsamkeit, einen K\u00f6rper, der Autorit\u00e4ten pr\u00fcfend im Blick beh\u00e4lt.</p>
        <p class="vb-intro"><strong>Sexuell (SX6):</strong> Bewusst zeigt sich mutige, direkte K\u00f6rperkraft, die Angst in Konfrontation statt R\u00fcckzug verwandelt. Unbewusst wird daraus impulsive Angriffsbereitschaft, ein K\u00f6rper, der zuschl\u00e4gt, bevor er gepr\u00fcft hat.</p>

        <h3 id="ins-typ-7" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2014 Der Instinkt der Bewegung</h3>
        <p class="vb-intro">Beim Typ 7 will der K\u00f6rper in Bewegung bleiben, neue Reize aufnehmen, nichts verpassen \u2014 Instinkt zeigt sich als best\u00e4ndiger Drang nach vorn. Bewusst gelebt wird daraus lebendige, ansteckende Energie, die Schwung in jede Situation bringt.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE7):</strong> Bewusst zeigt sich praktische, genussfreudige K\u00f6rperlichkeit, die Sicherheit mit Erlebnis verbindet. Unbewusst wird daraus rastlose Betriebsamkeit, ein K\u00f6rper, der Ablenkung braucht, um Unruhe nicht zu sp\u00fcren.</p>
        <p class="vb-intro"><strong>Sozial (SO7):</strong> Bewusst entsteht gro\u00dfz\u00fcgige, mitrei\u00dfende Energie im Dienst einer guten Sache. Unbewusst kippt es in Selbst\u00fcberforderung, einen K\u00f6rper, der immer weiter gibt, bis die Reserven leer sind.</p>
        <p class="vb-intro"><strong>Sexuell (SX7):</strong> Bewusst zeigt sich intensive, faszinierende Pr\u00e4senz, die andere spontan mitrei\u00dft. Unbewusst wird daraus impulsive Reizsuche, ein K\u00f6rper, der von einer Begeisterung zur n\u00e4chsten springt.</p>

        <h3 id="ins-typ-8" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2014 Der Instinkt der Kraft</h3>
        <p class="vb-intro">Beim Typ 8 ist der K\u00f6rper selbst die Botschaft: kraftvoll, pr\u00e4sent, unmittelbar. Bewusst gelebt wird daraus besch\u00fctzende St\u00e4rke, die Raum h\u00e4lt, ohne ihn anderen zu nehmen.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE8):</strong> Bewusst zeigt sich robuste, unersch\u00fctterliche Pr\u00e4senz, die f\u00fcr sich und andere Sicherheit schafft. Unbewusst wird daraus kompromisslose H\u00e4rte, ein K\u00f6rper, der Verletzlichkeit gar nicht erst zul\u00e4sst.</p>
        <p class="vb-intro"><strong>Sozial (SO8):</strong> Bewusst entsteht kraftvolle, loyale F\u00fchrungsenergie im Dienst einer Gruppe. Unbewusst kippt es in dominantes Kontrollverhalten, einen K\u00f6rper, der Raum beansprucht, statt ihn zu teilen.</p>
        <p class="vb-intro"><strong>Sexuell (SX8):</strong> Bewusst zeigt sich hingebungsvolle, unmittelbare Leidenschaft, die den Partner ganz umfasst. Unbewusst wird daraus besitzergreifende Wucht, ein K\u00f6rper, der N\u00e4he mit \u00dcbernahme verwechselt.</p>

        <h3 id="ins-typ-9" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2014 Der Instinkt der Ruhe</h3>
        <p class="vb-intro">Beim Typ 9 zieht sich instinktive Energie oft zur\u00fcck, um Frieden zu wahren \u2014 der K\u00f6rper d\u00e4mpft sich selbst, bevor Konflikt entstehen kann. Bewusst gelebt wird daraus tragende, geerdete Pr\u00e4senz, die Sicherheit ausstrahlt, ohne sich aufzudr\u00e4ngen.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE9):</strong> Bewusst zeigt sich gem\u00fctliche, k\u00f6rperlich verankerte Gelassenheit, die Geborgenheit schafft. Unbewusst wird daraus Tr\u00e4gheit \u2014 ein K\u00f6rper, der sich in Gewohnheit und Bequemlichkeit bet\u00e4ubt.</p>
        <p class="vb-intro"><strong>Sozial (SO9):</strong> Bewusst entsteht verbindende, ausgleichende Energie, die Gruppen zusammenh\u00e4lt. Unbewusst kippt es in Selbstverleugnung, einen K\u00f6rper, der sich f\u00fcr alle einsetzt und dabei die eigene Energie vergisst.</p>
        <p class="vb-intro"><strong>Sexuell (SX9):</strong> Bewusst zeigt sich intensive, verschmelzende K\u00f6rperpr\u00e4senz, ganz auf den geliebten Menschen ausgerichtet. Unbewusst wird daraus energetisches Verschmelzen bis zur Selbstaufgabe, ein K\u00f6rper, der die eigenen Grenzen im anderen verliert.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("sprache-der-sexualit\u00e4t", "Instinkt und Emotionalit\u00e4t im Zusammenspiel \u2014 wie Begehren und K\u00f6rperenergie sich bei den 9 Typen und ihren Subtypen verbinden.", "Die Sprache unserer Sexualit\u00e4t")}
        ${bookTip("die-verborgene-dynamik-der-27-subtypen", "Die 27 Subtypen im Detail \u2014 Normal-, Verst\u00e4rkungs- und Kontratyp jedes Enneagrammtyps ausf\u00fchrlich erl\u00e4utert.", "Die verborgene Dynamik der 27 Subtypen")}
        ${bookTip("wer-du-wirklich-bist-band-1", "Die neun Typen in ihrer Tiefe \u2013 Schutzmuster, Leidenschaften und der Weg zur Essenz.", "Wer du wirklich bist \u2013 Band 1")}
      </div>
      ${relatedLinks([
        {route:"enneagramm-emotionalitaet", label:"Enneagramm und Emotionalit\u00e4t"},
        {route:"enneagramm-intellekt", label:"Enneagramm und Intellekt"},
        {route:"leidenschaft-und-wunde", label:"Leidenschaft und Wunde"},
      ])}
    </div>
  `);
}

function enneagrammIntellektPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Enneagramm und Intellekt", "Schaubilder \u00b7 Emotionen & Bewusstsein")}
      <p class="psycho-intro">Intellekt ist im Enneagramm die F\u00e4higkeit, innezuhalten, zu ordnen und zu verstehen, bevor gehandelt oder gef\u00fchlt wird. Auch er ist an sich wertfrei: weder gut noch schlecht, sondern geistige Klarheit, die eine Richtung sucht. Bewusst gelebt wird Intellekt zu echter Einsicht, zu \u00dcberblick, der Zusammenh\u00e4nge erkennt, ohne sich in ihnen zu verlieren. Unbewusst wird dieselbe F\u00e4higkeit zu Gr\u00fcbeln, zu Distanz, zu einem Kopf, der denkt, statt zu leben \u2014 Verstand, der sich zwischen die Person und die Welt schiebt.</p>
      <img src="./assets/enneagramm-intellekt.jpg" alt="Enneagramm und Intellekt \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />

      <div class="vb-section" style="max-width:100%;">
        <h2 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:var(--ink);">Zwei Gesichter derselben Kraft</h2>
        <p class="vb-intro">Jeder der neun Typen tr\u00e4gt eine eigene intellektuelle Grundf\u00e4rbung \u2014 eine Art, wie Verstand eingesetzt wird, um die Welt zu ordnen. Diese F\u00e4rbung ist an sich neutral. Erst der Grad an Bewusstheit entscheidet, ob sie zu klarer Einsicht wird oder zur Flucht vor dem eigenen Erleben. Im bewussten Zustand wird Intellekt zu einem Instrument der Wahrnehmung: Er schafft \u00dcberblick, erkennt Muster, verbindet Gef\u00fchl und Handlung mit Verst\u00e4ndnis. Im unbewussten Zustand dagegen l\u00e4uft derselbe Verstand ungefiltert \u2014 er gr\u00fcbelt, rechtfertigt, distanziert oder erstarrt in Analyse, ohne dass die Person es zun\u00e4chst selbst bemerkt.</p>
        <p class="vb-intro">Das Schaubild zeigt f\u00fcr jeden Typ diese doppelte M\u00f6glichkeit: die Qualit\u00e4t, die entsteht, wenn Intellekt bewusst gelebt wird \u2014 und die Verzerrung, die entsteht, wenn er unbewusst das Steuer \u00fcbernimmt. Es ist dieselbe geistige Kraft, nur mit unterschiedlichem Grad an innerer Beobachtung.</p>
      </div>

      <div style="display:flex;flex-wrap:wrap;gap:0.5rem;justify-content:center;margin:1rem 0 2rem;padding:1rem;background:var(--paper);border-radius:10px;border:1px solid var(--line);">
        <span style="font-size:0.8rem;font-weight:700;color:var(--gray-mid);width:100%;text-align:center;margin-bottom:0.3rem;">Schnellzugriff \u2014 direkt zum Typ</span>
        ${[1,2,3,4,5,6,7,8,9].map(n => `<a href="javascript:void(0)" onclick="document.getElementById('int-typ-${n}').scrollIntoView({behavior:'smooth',block:'start'})" style="font-size:0.85rem;font-weight:700;padding:0.3rem 0.7rem;border-radius:6px;background:linear-gradient(160deg, ${typeColor(n)}22, ${typeColor(n)}0d);color:${typeColor(n)};text-decoration:none;border:1px solid ${typeColor(n)};">Typ ${n}</a>`).join("")}
      </div>

      <div class="vb-section" style="max-width:100%;">

        <h3 id="int-typ-1" style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2014 Der Intellekt der Unterscheidung</h3>
        <p class="vb-intro">Beim Typ 1 ist Verstand darauf trainiert, richtig von falsch zu trennen \u2014 ein inneres Regelwerk pr\u00fcft jede Situation. Bewusst gelebt wird daraus klare, differenzierte Urteilskraft, die Nuancen erkennt, statt nur schwarz-wei\u00df zu sehen.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE1):</strong> Bewusst zeigt sich praktisches, l\u00f6sungsorientiertes Denken, das Ordnung im Alltag herstellt. Unbewusst wird daraus ein innerer Kritiker, der jedes Detail auf Fehler abklopft.</p>
        <p class="vb-intro"><strong>Sozial (SO1):</strong> Bewusst entsteht systemisches Denken, das gerechte Strukturen f\u00fcr alle im Blick hat. Unbewusst kippt es in rechthaberische Prinzipienreiterei, einen Verstand, der andere an der eigenen Norm misst.</p>
        <p class="vb-intro"><strong>Sexuell (SX1):</strong> Bewusst zeigt sich engagiertes, \u00fcberzeugendes Denken, das andere f\u00fcr eine bessere Sache gewinnt. Unbewusst wird daraus missionarischer Eifer, ein Verstand, der keine andere Sichtweise mehr zul\u00e4sst.</p>

        <h3 id="int-typ-2" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2014 Der Intellekt der Beziehung</h3>
        <p class="vb-intro">Beim Typ 2 denkt der Verstand vor allem in Beziehungen \u2014 wer braucht was, wer f\u00fchlt sich wie. Bewusst gelebt wird daraus feines soziales Gesp\u00fcr, das Bed\u00fcrfnisse erkennt, ohne sich selbst zu verlieren.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE2):</strong> Bewusst zeigt sich warmes, alltagsnahes Verst\u00e4ndnis f\u00fcr die Menschen im engen Kreis. Unbewusst wird daraus st\u00e4ndiges Mitdenken f\u00fcr andere, das die eigenen Gedanken kaum noch Raum l\u00e4sst.</p>
        <p class="vb-intro"><strong>Sozial (SO2):</strong> Bewusst entsteht strategisches Denken f\u00fcr das Wohl vieler, ein \u00dcberblick \u00fcber soziale Netzwerke. Unbewusst kippt es in berechnendes Taktieren, wer wem wie viel schuldet.</p>
        <p class="vb-intro"><strong>Sexuell (SX2):</strong> Bewusst zeigt sich intuitives Gesp\u00fcr f\u00fcr den einen Menschen, ein Verstand, der ganz auf ihn eingestimmt ist. Unbewusst wird daraus gr\u00fcbelndes Kreisen um die Frage, ob man geliebt genug ist.</p>

        <h3 id="int-typ-3" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2014 Der Intellekt der Wirksamkeit</h3>
        <p class="vb-intro">Beim Typ 3 ist Denken zielgerichtet und effizient \u2014 der Verstand plant den k\u00fcrzesten Weg zum Erfolg. Bewusst gelebt wird daraus klare, pragmatische Strategie, die andere mitnimmt statt nur zu funktionieren.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE3):</strong> Bewusst zeigt sich bodenst\u00e4ndiges, effizientes Organisationstalent, das Sicherheit durch kluges Handeln schafft. Unbewusst wird daraus st\u00e4ndiges Optimierungsdenken, das nie zur Ruhe kommt.</p>
        <p class="vb-intro"><strong>Sozial (SO3):</strong> Bewusst entsteht strategisches Denken, das ein Team klug zu einem gemeinsamen Ziel f\u00fchrt. Unbewusst kippt es in Image-Kalk\u00fcl, einen Verstand, der jede Wirkung genau berechnet.</p>
        <p class="vb-intro"><strong>Sexuell (SX3):</strong> Bewusst zeigt sich anziehendes, selbstbewusstes Denken, das den Partner durch echte Substanz \u00fcberzeugt. Unbewusst wird daraus permanente Selbstinszenierung im Kopf, bevor \u00fcberhaupt gehandelt wird.</p>

        <h3 id="int-typ-4" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2014 Der Intellekt der Bedeutung</h3>
        <p class="vb-intro">Beim Typ 4 sucht Verstand nicht Effizienz, sondern Bedeutung \u2014 was macht dieses Erleben einzigartig? Bewusst gelebt wird daraus tiefes, symbolisches Verst\u00e4ndnis, das Erfahrung in Sinn verwandelt.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE4):</strong> Bewusst zeigt sich stilles, standhaftes Nachdenken, das auch Schweres in Worte fassen kann. Unbewusst wird daraus z\u00e4hes Gr\u00fcbeln \u00fcber das eigene Ungen\u00fcgen.</p>
        <p class="vb-intro"><strong>Sozial (SO4):</strong> Bewusst entsteht die F\u00e4higkeit, eigenes Erleben in Worte zu fassen, die andere tr\u00f6sten. Unbewusst kippt es in st\u00e4ndigen Vergleich, einen Verstand, der die eigene Andersartigkeit immer wieder neu belegt.</p>
        <p class="vb-intro"><strong>Sexuell (SX4):</strong> Bewusst zeigt sich unmittelbares, ehrliches Denken, das N\u00e4he durch Klarheit schafft. Unbewusst wird daraus dramatisierendes Kopfkino, das jede Beziehung auf Zuspitzung pr\u00fcft.</p>

        <h3 id="int-typ-5" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2014 Der Intellekt des Verstehens</h3>
        <p class="vb-intro">Beim Typ 5 ist Denken das ureigene Zuhause \u2014 hier wird Verstand am direktesten und am liebsten eingesetzt. Bewusst gelebt wird daraus seltene Klarheit, ein \u00dcberblick, der komplexe Zusammenh\u00e4nge einfach macht.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE5):</strong> Bewusst zeigt sich konzentriertes, unabh\u00e4ngiges Fachwissen, das mit wenig Aufwand viel erreicht. Unbewusst wird daraus fast vollst\u00e4ndiger R\u00fcckzug ins Denken, weit weg vom eigenen K\u00f6rper und Gef\u00fchl.</p>
        <p class="vb-intro"><strong>Sozial (SO5):</strong> Bewusst entsteht Expertentum, das Wissen bereitwillig mit anderen teilt. Unbewusst kippt es in \u00fcberlegene Distanz, einen Verstand, der sich hinter Fachwissen verschanzt.</p>
        <p class="vb-intro"><strong>Sexuell (SX5):</strong> Bewusst zeigt sich intensive, vertiefte Besch\u00e4ftigung mit einem Menschen oder Thema. Unbewusst wird daraus geheimes, abgeschottetes Denken, das kaum geteilt wird.</p>

        <h3 id="int-typ-6" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2014 Der Intellekt der Absicherung</h3>
        <p class="vb-intro">Beim Typ 6 denkt der Verstand in Szenarien \u2014 was k\u00f6nnte schiefgehen, wie l\u00e4sst sich vorsorgen? Bewusst gelebt wird daraus kluge, realistische Weitsicht, die Risiken einsch\u00e4tzt, ohne sich in ihnen zu verlieren.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE6):</strong> Bewusst zeigt sich sorgf\u00e4ltiges, vorausschauendes Planen im Alltag, das Sicherheit schafft. Unbewusst wird daraus zerm\u00fcrbendes Durchdenken jedes Worst-Case-Szenarios.</p>
        <p class="vb-intro"><strong>Sozial (SO6):</strong> Bewusst entsteht loyales, systemisches Denken, das Verl\u00e4sslichkeit f\u00fcr die Gruppe schafft. Unbewusst kippt es in Misstrauen gegen\u00fcber Autorit\u00e4ten, einen Verstand, der st\u00e4ndig nach Beweisen sucht.</p>
        <p class="vb-intro"><strong>Sexuell (SX6):</strong> Bewusst zeigt sich mutiges, direktes Denken, das Unsicherheit in Handlung statt Gr\u00fcbeln verwandelt. Unbewusst wird daraus impulsives Schwarz-Wei\u00df-Denken, das keine Zwischent\u00f6ne mehr zul\u00e4sst.</p>

        <h3 id="int-typ-7" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2014 Der Intellekt der M\u00f6glichkeiten</h3>
        <p class="vb-intro">Beim Typ 7 springt der Verstand von Idee zu Idee, verkn\u00fcpft, assoziiert, sieht \u00fcberall Optionen. Bewusst gelebt wird daraus sprudelnde, kreative Klarheit, die Perspektiven er\u00f6ffnet, statt zu verwirren.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE7):</strong> Bewusst zeigt sich praktisches, l\u00f6sungsfreudiges Denken, das Genuss und Sicherheit klug verbindet. Unbewusst wird daraus sprunghafte Rastlosigkeit, ein Verstand, der bei keinem Gedanken lange bleibt.</p>
        <p class="vb-intro"><strong>Sozial (SO7):</strong> Bewusst entsteht idealistisches, verbindendes Denken, das andere f\u00fcr eine Vision begeistert. Unbewusst kippt es in Selbst\u00fcberforderung durch zu viele parallele Pl\u00e4ne.</p>
        <p class="vb-intro"><strong>Sexuell (SX7):</strong> Bewusst zeigt sich faszinierendes, vision\u00e4res Denken, das andere ansteckt. Unbewusst wird daraus impulsive Idealisierung, ein Verstand, der schnell begeistert und ebenso schnell weiterzieht.</p>

        <h3 id="int-typ-8" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2014 Der Intellekt der Klarheit</h3>
        <p class="vb-intro">Beim Typ 8 ist Denken direkt und unumwunden \u2014 der Verstand geht sofort zur Sache, ohne Umwege. Bewusst gelebt wird daraus strategische Klarheit, die komplexe Lagen schnell auf den Punkt bringt.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE8):</strong> Bewusst zeigt sich robustes, bodenst\u00e4ndiges Urteilsverm\u00f6gen, das f\u00fcr sich und andere Sicherheit organisiert. Unbewusst wird daraus kompromissloses Schwarz-Wei\u00df-Denken, das keine Graut\u00f6ne duldet.</p>
        <p class="vb-intro"><strong>Sozial (SO8):</strong> Bewusst entsteht weitsichtiges strategisches Denken im Dienst einer Gruppe oder Sache. Unbewusst kippt es in autorit\u00e4re Rechthaberei, einen Verstand, der keine Gegenrede ertr\u00e4gt.</p>
        <p class="vb-intro"><strong>Sexuell (SX8):</strong> Bewusst zeigt sich leidenschaftliches, entschlossenes Denken, ganz auf den Partner und das gemeinsame Vorhaben gerichtet. Unbewusst wird daraus besitzergreifendes Kontrolldenken.</p>

        <h3 id="int-typ-9" style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2014 Der Intellekt der Vermittlung</h3>
        <p class="vb-intro">Beim Typ 9 sucht Verstand instinktiv nach der verbindenden Perspektive \u2014 er kann viele Sichtweisen zugleich verstehen. Bewusst gelebt wird daraus weise, ausgleichende Klarheit, die vermittelt, ohne sich selbst zu verlieren.</p>
        <p class="vb-intro"><strong>Selbsterhaltend (SE9):</strong> Bewusst zeigt sich ruhiges, praktisches Denken, das den Alltag geschmeidig ordnet. Unbewusst wird daraus gedankliche Tr\u00e4gheit, ein Verstand, der sich lieber ablenkt als entscheidet.</p>
        <p class="vb-intro"><strong>Sozial (SO9):</strong> Bewusst entsteht verbindendes Denken, das unterschiedliche Standpunkte zusammenf\u00fchrt. Unbewusst kippt es in Selbstverleugnung, einen Verstand, der die eigene Meinung hintanstellt, um Konflikt zu vermeiden.</p>
        <p class="vb-intro"><strong>Sexuell (SX9):</strong> Bewusst zeigt sich intensives, einf\u00fchlsames Verstehen des geliebten Menschen. Unbewusst wird daraus Verschmelzung im Denken, ein Verstand, der die eigene Sicht ganz im anderen aufl\u00f6st.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("die-verborgene-dynamik-der-27-subtypen", "Die 27 Subtypen im Detail \u2014 Normal-, Verst\u00e4rkungs- und Kontratyp jedes Enneagrammtyps ausf\u00fchrlich erl\u00e4utert.", "Die verborgene Dynamik der 27 Subtypen")}
        ${bookTip("wer-du-wirklich-bist-band-1", "Die neun Typen in ihrer Tiefe \u2013 Schutzmuster, Leidenschaften und der Weg zur Essenz.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
      </div>
      ${relatedLinks([
        {route:"enneagramm-emotionalitaet", label:"Enneagramm und Emotionalit\u00e4t"},
        {route:"enneagramm-instinkt", label:"Enneagramm und Instinkt"},
        {route:"drei-zentren", label:"Die drei Zentren"},
      ])}
    </div>
  `);
}

function baguaZonenDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Bagua-Zonen der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Die Bagua-Zonen im Feng Shui teilen ein Haus, eine Wohnung oder auch einen einzelnen Raum in neun Lebensbereiche ein \u2014 und diese neun Bereiche entsprechen erstaunlich genau den neun Enneagramm-Mustern. Wenn man einen der neun Bereiche gezielt verbessern m\u00f6chte, kann man die jeweilige Zone bewusst mit Feng-Shui-Ma\u00dfnahmen aufwerten \u2014 und dabei zugleich verstehen, welches innere Prinzip dahintersteht.</p>
      <img src="./assets/bagua-zonen-der-9-typen.jpg" alt="Bagua-Zonen der 9 Enneagrammtypen im Feng Shui \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Ruhm: Integrit\u00e4t, die sichtbar wird</h3>
        <p class="vb-intro">Die Bagua-Zone \u201eRuhm" steht im Feng Shui f\u00fcr Ansehen, Reputation und die Art, wie man in der Welt wahrgenommen wird \u2014 nicht als lauter Erfolg, sondern als der gute Ruf, der aus rechtem Handeln erw\u00e4chst. Genau das ist die Logik des Typs 1: Er strebt nicht nach Ruhm um seiner selbst willen, sondern danach, als integer, korrekt und vertrauensw\u00fcrdig zu gelten. Sein Ansehen soll die Frucht seiner inneren Ordnung sein, nicht das Ziel seines Handelns. Im Feng Shui wird diese Zone traditionell mit Feuer, mit Licht und mit Symbolen der eigenen Werte gest\u00e4rkt \u2014 passend zu einem Typ, dessen Ruf untrennbar mit seinem inneren moralischen Kompass verbunden ist.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Partnerschaft: Beziehung als Lebensmittelpunkt</h3>
        <p class="vb-intro">Die Zone \u201ePartnerschaft" steht f\u00fcr Liebe, N\u00e4he und die Qualit\u00e4t aller engen Beziehungen \u2014 und das ist exakt das Zentrum, um das sich das Leben des Typs 2 dreht. Kein anderer Typ richtet seine Aufmerksamkeit so best\u00e4ndig auf das Wohl des anderen, auf das Gelingen von Verbindung, auf das feine Gesp\u00fcr daf\u00fcr, was der Partner oder Freund gerade braucht. Im Feng Shui wird diese Zone durch Paarsymbole, durch W\u00e4rme und durch bewusst geschaffene N\u00e4he aktiviert \u2014 ein Prinzip, das der Typ 2 ohnehin lebt: Er schafft N\u00e4he, noch bevor jemand danach fragt, weil Beziehung f\u00fcr ihn keine Erg\u00e4nzung des Lebens ist, sondern dessen Grundlage.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Karriere: Der sichtbare Weg nach vorn</h3>
        <p class="vb-intro">Die Zone \u201eKarriere" liegt im Feng Shui traditionell im Eingangsbereich \u2014 dort, wo der Lebensweg beginnt und wo Bewegung, Fluss und Fortschritt entstehen. Das trifft die Grundmotivation des Typs 3 punktgenau: Er ist der Typ, der vorankommen will, der Ziele setzt und erreicht, der seinen Wert \u00fcber sichtbare Leistung und Fortschritt definiert. Wo andere z\u00f6gern, bewegt sich der Typ 3 bereits weiter \u2014 Stillstand ist f\u00fcr ihn das gr\u00f6\u00dfte Unbehagen. Im Feng Shui wird diese Zone durch flie\u00dfendes Wasser, durch Klarheit und offene Wege gest\u00e4rkt \u2014 Sinnbilder f\u00fcr einen Menschen, dessen Energie st\u00e4ndig nach vorne dr\u00e4ngt.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Hilfreiche Freunde: Verb\u00fcndete f\u00fcr den eigenen Weg</h3>
        <p class="vb-intro">Die Zone \u201eHilfreiche Freunde" steht f\u00fcr Mentoren, Wegbegleiter und jene seltenen Menschen, die einen wirklich verstehen und unterst\u00fctzen \u2014 nicht die gro\u00dfe Menge, sondern die wenigen, echten Verbindungen. Genau das sucht der Typ 4: nicht oberfl\u00e4chliche Kontakte, sondern tiefe, authentische Begegnungen mit Menschen, die seine Einzigartigkeit sehen, ohne sie zu verbiegen. Er braucht keine Masse an Unterst\u00fctzung, sondern die eine Seelenverwandtschaft, die ihn in seinem So-Sein best\u00e4tigt. Im Feng Shui wird diese Zone durch Symbole der Unterst\u00fctzung von au\u00dfen aktiviert \u2014 passend zu einem Typ, der oft allein seinen Weg geht, aber zutiefst dankbar ist f\u00fcr jene wenigen, die ihn dabei wirklich begleiten.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Wissen: Der R\u00fcckzugsort des Verstehens</h3>
        <p class="vb-intro">Die Zone \u201eWissen" steht f\u00fcr Selbstkultivierung, Studium und stille innere Einkehr \u2014 der Raum, in dem man sich zur\u00fcckzieht, um zu verstehen. Kaum ein Typ verk\u00f6rpert dieses Prinzip so klar wie der Typ 5: Er zieht sich zur\u00fcck, um Wissen zu sammeln, Zusammenh\u00e4nge zu durchdringen und eine innere Landkarte der Welt zu bauen, bevor er sich ihr wieder zuwendet. Im Feng Shui wird diese Zone traditionell ruhig, ungest\u00f6rt und reduziert gestaltet \u2014 ein Ort f\u00fcr B\u00fccher, f\u00fcr Stille, f\u00fcr konzentriertes Denken. F\u00fcr den Typ 5 ist genau das keine Beliebigkeit, sondern Notwendigkeit: Nur im gesch\u00fctzten R\u00fcckzug kann er die Klarheit gewinnen, die er sp\u00e4ter wieder mit anderen teilt.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Familie: Der sichere Kreis</h3>
        <p class="vb-intro">Die Zone \u201eFamilie" steht f\u00fcr Zugeh\u00f6rigkeit, Verwurzelung und das tragende soziale Netz, das Halt gibt \u2014 und genau dieser Halt ist das, wonach der Typ 6 sich am meisten sehnt. Sicherheit entsteht f\u00fcr ihn nicht durch Alleingang, sondern durch verl\u00e4ssliche Bindung an eine Gruppe, eine Familie, ein System, dem er vertrauen kann und dem er selbst treu zur Seite steht. Im Feng Shui wird diese Zone durch Familienfotos, durch Symbole der Herkunft und durch stabile, geerdete Materialien gest\u00e4rkt \u2014 ein Prinzip, das der Typ 6 instinktiv versteht: Wurzeln sind kein R\u00fcckschritt, sondern die Basis, von der aus \u00fcberhaupt erst Vertrauen wachsen kann.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Kinder: Kreativit\u00e4t, Spiel und Zukunftsfreude</h3>
        <p class="vb-intro">Die Zone \u201eKinder" steht im Feng Shui f\u00fcr Kreativit\u00e4t, Spielfreude und neue Projekte \u2014 f\u00fcr alles, was aus reiner Lebensfreude entsteht und in die Zukunft weist. Das ist die ureigene Welt des Typs 7: Er lebt aus einer kindlichen Begeisterungsf\u00e4higkeit heraus, liebt es, Neues zu erschaffen, Ideen sprie\u00dfen zu lassen und das Leben als Abenteuer statt als Pflicht zu erleben. Im Feng Shui wird diese Zone durch Farben, durch Symbole der Fruchtbarkeit und durch Raum f\u00fcr spontanen Ausdruck aktiviert \u2014 ganz im Sinne eines Typs, der sich nie ganz von seiner spielerischen, neugierigen inneren Kindheit verabschiedet.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Reichtum: Ressourcen als Fundament der Freiheit</h3>
        <p class="vb-intro">Die Zone \u201eReichtum" steht f\u00fcr materiellen Wohlstand, Ressourcen und die F\u00fclle, aus der heraus man handlungsf\u00e4hig bleibt \u2014 und genau das ist f\u00fcr den Typ 8 von zentraler Bedeutung. Es geht ihm dabei selten um Besitz als Selbstzweck, sondern um Unabh\u00e4ngigkeit: Wer \u00fcber eigene Ressourcen verf\u00fcgt, muss sich niemandem unterordnen und kann andere sch\u00fctzen, die auf ihn angewiesen sind. Im Feng Shui wird diese Zone durch Symbole des Wachstums, durch bewusst gepflegte F\u00fclle und durch stabile, kraftvolle Elemente gest\u00e4rkt \u2014 passend zu einem Typ, f\u00fcr den St\u00e4rke immer auch bedeutet, Verantwortung f\u00fcr das eigene Territorium und die eigenen Leute zu \u00fcbernehmen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Tai-Chi (Gesundheit): Die stille Mitte von allem</h3>
        <p class="vb-intro">Die Zone \u201eTai-Chi" liegt im Zentrum des Bagua \u2014 sie steht f\u00fcr Gesundheit, Balance und jenen ruhenden Mittelpunkt, von dem aus alle anderen acht Lebensbereiche zusammengehalten werden. Kein Zufall, dass ausgerechnet der Typ 9 diesem Zentrum entspricht: Er ist der Vermittler, der Ausgleichende, derjenige, der von Natur aus das gro\u00dfe Ganze im Blick beh\u00e4lt und andere zueinanderf\u00fchrt, statt sich in einem einzelnen Lebensbereich zu verlieren. Im Feng Shui bleibt diese zentrale Zone bewusst frei, ruhig und ungest\u00f6rt \u2014 ein Bild, das die tiefste Sehnsucht des Typs 9 spiegelt: innerer Frieden als tragender Grund, aus dem heraus alles andere seinen Platz findet.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"kampfkunstarten-der-9-typen", label:"Kampfkunstarten der 9 Typen"},
        {route:"blumenarten-der-9-typen", label:"Blumenarten der 9 Typen"},
        {route:"superpower-der-9-typen", label:"Superpower der 9 Typen"},
      ])}
    </div>
  `);
}

function hunderassenDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Hunderassen der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Die Zuordnung von neun Hunderassen zu den neun Enneagrammprinzipien ist eine kreative Methode, um die symbolischen Eigenschaften und Charakteristika dieser unterschiedlichen Hunde mit den verschiedenen Pers\u00f6nlichkeitstypen des Enneagramms zu verbinden. Jede Rasse tr\u00e4gt ein unverwechselbares Wesen in sich \u2014 vom pr\u00e4zisen Border Collie bis zum sanftm\u00fctigen Berner Sennenhund.</p>
      <img src="./assets/hunderassen-der-9-typen.jpg" alt="Hunderassen der 9 Typen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Border Collie: Intelligenz und hohe Standards</h3>
        <p class="vb-intro">Der Border Collie ist bekannt daf\u00fcr, dass er hart arbeitet, gut trainierbar ist und hohe Standards in seiner Arbeit setzt \u2014 \u00e4hnlich dem Typ 1, der nach Perfektion und Ordnung strebt. Er gilt als intelligentester Hund der Welt: In Studien lernte ein Border Collie \u00fcber tausend W\u00f6rter und unterschied Objekte nach ihrer Form. Sein Blick \u2014 der ber\u00fchmte \u201eEye" \u2014 ist ein hypnotisches Fixieren des Schafes, das es in Bewegungslosigkeit einfrieren l\u00e4sst. Kein anderer Hund hat diese Technik entwickelt. F\u00fcr den Border Collie gibt es nur eine Art, eine Aufgabe zu erledigen: die richtige. Die Leidenschaft des Zorns zeigt sich als innere Unruhe, wenn Dinge nicht so laufen, wie sie laufen sollten.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 Golden Retriever: F\u00fcrsorge aus tiefstem Herzen</h3>
        <p class="vb-intro">Der Golden Retriever ist ein au\u00dferordentlich freundlicher, liebevoller und stets bereiter Begleiter, der seinem Besitzer zu gefallen und ihn zu unterst\u00fctzen wei\u00df \u2014 genau das, was zur f\u00fcrsorgerischen Natur des Typs 2 passt. Golden Retriever wurden als Therapiehunde, Blindenhunde und Rettungshunde eingesetzt \u2014 nicht wegen ihrer Kraft, sondern wegen ihrer unbedingten Zugewandtheit. Sie sp\u00fcren Schmerz und Trauer bei Menschen und reagieren mit K\u00f6rperkontakt und N\u00e4he. Ihr Stolz liegt nicht im Erfolg, sondern im Geliebtwerden f\u00fcrs Dasein. Die Leidenschaft des Stolzes zeigt sich als tiefer Wunsch, unentbehrlich zu sein.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Dobermann: Leistung, Wachsamkeit, Erfolg</h3>
        <p class="vb-intro">Doberm\u00e4nner sind athletische, intelligente und arbeitsfreudige Hunde, die oft in anspruchsvollen Rollen wie Wach- oder Diensthunden erfolgreich sind. Leistungsf\u00e4higkeit und Ehrgeiz spiegeln den Erfolg und das Streben von Typ 3 wider. Der Dobermann wurde von einem Steuereintreiber gez\u00fcchtet, der einen Hund wollte, der Respekt einfl\u00f6\u00dft und gleichzeitig intelligent genug ist, Situationen zu lesen. Das Ergebnis: ein Hund, der perfekt f\u00fcr die Rolle dressiert werden kann, die man von ihm erwartet. Sein Erscheinungsbild ist kalibriert \u2014 kein \u00fcberfl\u00fcssiges Fell, kein \u00fcberfl\u00fcssiger Charakter. Die Leidenschaft der Eitelkeit zeigt sich als totale Identifikation mit der Rolle.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Basset Hound: Tiefe, Einzigartigkeit, Ausdruck</h3>
        <p class="vb-intro">Basset Hounds blicken oft melancholisch und machen manchmal einen nachdenklichen oder traurigen Eindruck \u2014 was insgesamt gut zu den Eigenschaften von Typ 4 passt. Sie besitzen einen unverwechselbaren K\u00f6rperbau: kurze Beine, l\u00e4nglicher K\u00f6rper, h\u00e4ngende Ohren, die den Geruchssinn verst\u00e4rken, indem sie Duftmolek\u00fcle vom Boden aufwirbeln. Kein anderer Hund sieht so aus wie ein Basset \u2014 und kein anderer Hund tr\u00e4gt sein Wesen so offen im Gesicht. Sein Blick ist eine ganze Psychologie. Die Leidenschaft des Neids zeigt sich als Sehnsucht nach Verbindung bei gleichzeitigem Gef\u00fchl des Andersseins.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Shiba Inu: Unabh\u00e4ngigkeit und innere Welt</h3>
        <p class="vb-intro">Der Shiba Inu ist bekannt f\u00fcr seine Unabh\u00e4ngigkeit und Beobachtungsgabe. Seine ruhige und analytische Natur passt gut zu Typ 5, der oft zur\u00fcckgezogen und wissbegierig ist. Der Shiba Inu ist ein jahrtausendealter japanischer Jagdhund \u2014 einer der wenigen Hunde, die sich durch Domestizierung kaum ver\u00e4ndert haben. Er ist katzenhaft: putzt sich selbst, entscheidet selbst, w\u00e4hlt seine N\u00e4he sorgf\u00e4ltig. Er zeigt keine Zuneigung auf Befehl. Sein Vertrauen muss verdient werden, und wenn es einmal da ist, ist es tief und still. Die Leidenschaft des Geizes zeigt sich als Sparsamkeit mit Energie, Zeit und Zuneigung \u2014 nichts davon wird verschwendet.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Shetland Sheepdog: Loyalit\u00e4t und Wachsamkeit</h3>
        <p class="vb-intro">Die Shetland Sheepdogs sind \u00e4u\u00dferst loyal und wachsam, immer bereit, ihre Familie zu sch\u00fctzen. Dies spiegelt die Zuverl\u00e4ssigkeit und Treue des Typs 6 wider. Shelties wurden auf den sturmgepeitschten Shetlandinseln gez\u00fcchtet \u2014 eine raue Umgebung, die Hunde hervorgebracht hat, die lieber zweimal schauen als einmal handeln. Sie bellen bei Unbekanntem, pr\u00fcfen Situationen, beobachten Muster. Aber innerhalb ihrer Gruppe sind sie von einer Zuverl\u00e4ssigkeit, die kaum zu \u00fcbertreffen ist: sie folgen ihrer Familie wie ein Schatten. Die Leidenschaft der Angst zeigt sich als Hypervigilanz \u2014 ein inneres Fr\u00fchwarnsystem, das nie ganz abschaltet.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Dalmatiner: Energie, Verspieltheit, Neugier</h3>
        <p class="vb-intro">Dalmatiner sind lebhafte und neugierige Hunde, die gern spielen und neue Abenteuer erleben. Ihre fr\u00f6hliche und abenteuerliche Art passt gut zu Typ 7. Der Dalmatiner ist unm\u00f6glich zu \u00fcbersehen \u2014 sein gepunktetes Fell ist eine visuelle Einladung. Er wurde als Kutschenhund gez\u00fcchtet, der stundenlang neben Pferden laufen konnte ohne zu erm\u00fcden: ein Hund f\u00fcr Bewegung, Tempo, die n\u00e4chste Station. Im Zirkus war er Stammgast; in der Feuerwehr wurde er Maskottchen. Die Leidenschaft der V\u00f6llerei zeigt sich als unstillbarer Hunger nach Erlebnis, Kontakt und dem n\u00e4chsten Abenteuer.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Rottweiler: St\u00e4rke und Schutzinstinkt</h3>
        <p class="vb-intro">Rottweiler sind starke, selbstbewusste Hunde mit einem ausgepr\u00e4gten Schutzinstinkt, der gut zur durchsetzungsf\u00e4higen und sch\u00fctzenden Natur von Typ 8 passt. Der Rottweiler stammt von r\u00f6mischen Drover-Hunden ab, die Viehherden \u00fcber die Alpen trieben. In Rottweil wurden sie sp\u00e4ter als Metzgerhunde eingesetzt \u2014 sie zogen Karren und trugen das Geld ihres Herrn in Beuteln um den Hals, weil niemand es wagte, einen Rottweiler zu berauben. Der Rottweiler ist kein Aggressor \u2014 er ist ein Besch\u00fctzer. Die Leidenschaft der Gier zeigt sich als ungestillter Hunger nach Kontrolle und Sicherheit f\u00fcr die, die ihm anvertraut sind.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Berner Sennenhund: Sanftmut und Ausgeglichenheit</h3>
        <p class="vb-intro">Berner Sennenhunde sind bekannt f\u00fcr ihre sanfte und ausgeglichene Art. Sie sind freundlich und friedlich, was gut zur harmoniesuchenden und vermittelnden Natur von Typ 9 passt. Der Berner Sennenhund wurde in den Schweizer Alpen als Allrounder gez\u00fcchtet \u2014 er h\u00fctete Vieh, zog Karren und war Begleithund. Sein Wesen ist das eines Vermittlers: er streitet nicht, er dr\u00e4ngt nicht, er nimmt sich nicht mehr Raum als n\u00f6tig. In einer Gruppe von Hunden ist er derjenige, der Konflikte durch blo\u00dfes Dasein aufl\u00f6st. Die Leidenschaft der Tr\u00e4gheit zeigt sich als tiefer Wunsch, dass alles bleibt, wie es ist \u2014 gro\u00df, warm, ruhig, zusammen.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"blumenarten-der-9-typen", label:"Blumenarten der 9 Typen"},
        {route:"pferdearten-der-9-typen", label:"Pferdearten der 9 Typen"},
        {route:"baerenarten-der-9-typen", label:"B\u00e4renarten der 9 Typen"},
      ])}
    </div>
  `);
}

function pferdearteDer9TypenPage() {
  return shell(`
    <div class="page-container">
      ${pageHeader("Pferdearten der 9 Typen", "Schaubilder \u00b7 Archetypen")}
      <p class="psycho-intro">Die Zuordnung von neun Pferderassen zu den neun Enneagrammprinzipien ist eine kreative Methode, um die verschiedenen Aspekte und Charakteristika dieser Pferde mit den Pers\u00f6nlichkeitstypen des Enneagramms zu verbinden. Jede Rasse verk\u00f6rpert auf eindrucksvolle Weise die Wesensart ihres Typs \u2014 von der edlen Pr\u00e4zision des Lippizaners bis zur friedvollen Ausgeglichenheit des Connemara Ponys.</p>
      <img src="./assets/pferdearten-der-9-typen.jpg" alt="Pferdearten der 9 Typen \u2013 Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;" />
      <div class="vb-section" style="max-width:100%;">

        <h3 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Typ 1 \u2013 Lippizaner: Pr\u00e4zision als Lebensform</h3>
        <p class="vb-intro">Der Lippizaner verk\u00f6rpert mit seiner legend\u00e4ren Pr\u00e4zision und Disziplin den Reformer-Typ auf ideale Weise. Diese Rasse ist bekannt f\u00fcr ihre F\u00e4higkeiten in der klassischen Dressur, die h\u00f6chste Pr\u00e4zision und jahrelange, geduldige \u00dcbung erfordern. Der Lippizaner symbolisiert das Streben nach Perfektion und das Einhalten hoher Standards. Seine ruhige, kontrollierte Kraft und die F\u00e4higkeit, komplexe Bewegungen mit Anmut auszuf\u00fchren, spiegeln die Leidenschaft des Typs 1 wider: den inneren Antrieb zur Vollkommenheit, der manchmal als Zorn auf das Unvollkommene erlebt wird. Kein anderes Pferd hat sich so tief in die K\u00fcnste der Reiterei eingeschrieben \u2014 die Hohe Schule ist sein Reich, und in diesem Reich gibt es kein \u201eGut genug\u201c.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Typ 2 \u2013 American Quarter Horse: Im Dienst der anderen</h3>
        <p class="vb-intro">Das American Quarter Horse steht f\u00fcr Hilfsbereitschaft und die Freude daran, anderen zu dienen \u2014 genau wie der Helfer-Typ des Enneagramms. Diese Pferde sind freundlich, vielseitig und bereit, bei vielen Aufgaben zu helfen. Sie sind f\u00fcr ihre kooperative Natur und ihre Bereitschaft, anderen zu dienen, bekannt. Ihr Stolz liegt im Geben und im Gef\u00fchl, gebraucht zu werden. Als eines der vielseitigsten Arbeitspferde Nordamerikas \u2014 auf Ranch, Rodeo und Rennbahn gleicherma\u00dfen zu Hause \u2014 symbolisieren sie die herzliche Zugewandtheit und die F\u00fcrsorge, die den Typ 2 auszeichnen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Typ 3 \u2013 Englisches Vollblut: Geboren zum Gewinnen</h3>
        <p class="vb-intro">Das Englische Vollblut ist die Rasse, die mit Erfolg, Leistung und Wettbewerb identifiziert wird \u2014 ein perfektes Spiegelbild des Machers. Englische Vollbl\u00fcter sind f\u00fcr ihre Geschwindigkeit und ihren Erfolg im Rennsport bekannt. Sie verk\u00f6rpern Ehrgeiz, Zielbewusstsein und den Wunsch, erfolgreich zu sein. Ihr ganzes Wesen ist auf Leistung ausgerichtet: jede Muskelfaser, jeder Atemzug strebt nach dem Ziel. Die Leidenschaft der Eitelkeit \u2014 das Selbstbild als Gewinner \u2014 ist in dieser Rasse archetypisch verankert. Sie wurden nicht gez\u00fcchtet, um m\u00f6glichst gl\u00fccklich zu sein, sondern um m\u00f6glichst schnell zu sein \u2014 und das merkt man ihnen an.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Typ 4 \u2013 Araber: Sch\u00f6nheit und Einzigartigkeit</h3>
        <p class="vb-intro">Der Araber ist bekannt f\u00fcr seine Sch\u00f6nheit, Eleganz und ausgepr\u00e4gte Pers\u00f6nlichkeit \u2014 Eigenschaften, die den Individualisten-Typ widerspiegeln. Araber besitzen eine ausgepr\u00e4gte Pers\u00f6nlichkeit, Eleganz und Individualit\u00e4t. Sie strahlen Kreativit\u00e4t, Einzigartigkeit und Anmut aus. Ihr tiefer, ausdrucksstarker Blick und ihr sensibler Charakter machen sie unverwechselbar. Die Leidenschaft des Neids \u2014 das Gef\u00fchl, anders und zugleich nach Verbindung sehnend zu sein \u2014 dr\u00fcckt sich in ihrer innigen, aber auch eigenwilligen Art aus. Der Araber ist kein Pferd f\u00fcr jeden; wer ihn f\u00fchrt, muss ihn verstehen, nicht beherrschen wollen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Typ 5 \u2013 Mustang: Freiheit und inneres Wissen</h3>
        <p class="vb-intro">Der Mustang verk\u00f6rpert Unabh\u00e4ngigkeit, Autonomie und Weisheit \u2014 die Kernqualit\u00e4ten des Beobachters. Mustangs sind wilde Pferde, die oft zur\u00fcckgezogen und unabh\u00e4ngig leben. Sie symbolisieren den Wunsch nach Autonomie und Wissen sowie die F\u00e4higkeit, alleine zu \u00fcberleben. Der Mustang beobachtet die Welt aus der Distanz, zieht sich in seine innere Welt zur\u00fcck und akkumuliert Wissen, das er h\u00fctet wie einen Schatz. Jahrtausende in der Wildnis haben ihm eine Intelligenz eingraviert, die kein Z\u00fcchter reproduzieren kann: Er wei\u00df, wo Wasser ist, wo Gefahr lauert, wo die Herde sicher ist. Seine Leidenschaft \u2014 der Geiz mit Zeit, Energie und Vertrauen \u2014 zeigt sich im vorsichtigen Dosieren seiner N\u00e4he.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Typ 6 \u2013 Clydesdale: Loyalit\u00e4t als Kraft</h3>
        <p class="vb-intro">Das Clydesdale steht f\u00fcr Loyalit\u00e4t, Zuverl\u00e4ssigkeit und Gemeinschaftssinn \u2014 genau die Qualit\u00e4ten, die den Loyalisten auszeichnen. Clydesdales sind starke, zuverl\u00e4ssige Arbeitspferde. Sie stehen f\u00fcr Loyalit\u00e4t, Verl\u00e4sslichkeit und die Bereitschaft, hart zu arbeiten und ihrer Gemeinschaft zu unterst\u00fctzen. Ihre kolossale Kraft setzen sie nicht f\u00fcr sich selbst ein, sondern im Dienst der Gruppe \u2014 Feldarbeit, Transport, Last tragen, ohne zu klagen. Die Leidenschaft der Angst \u2014 das st\u00e4ndige Pr\u00fcfen, ob alles sicher ist \u2014 wandelt sich im Clydesdale in unersetzliche Treue: Wer ein Clydesdale einmal gef\u00fchrt hat, wei\u00df, dass er nicht wegrennt.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Typ 7 \u2013 Andalusier: Das Fest der Bewegung</h3>
        <p class="vb-intro">Der Andalusier steht f\u00fcr Lebhaftigkeit, Enthusiasmus und die Freude am Abenteuer \u2014 ein strahlendes Bild des Enthusiasten-Typs. Andalusier sind lebhaft, energisch und vielseitig. Sie lieben das Abenteuer und sind f\u00fcr ihre fr\u00f6hliche und enthusiastische Natur bekannt. Mit flie\u00dfender M\u00e4hne und federndem Schritt tanzen sie durchs Leben \u2014 jeder Moment ein neues Erlebnis, jede Begegnung eine neue Chance. Ihre Geschichte als Pferd der iberischen Ritter und Fiesta-Teilnehmer hat ihnen einen nat\u00fcrlichen Sinn f\u00fcr Spektakel gegeben: Der Andalusier tritt auf. Die Leidenschaft der V\u00f6llerei dr\u00fcckt sich in ihrem unersch\u00f6pflichen Appetit auf Bewegung, Reize und Kontakt aus.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Typ 8 \u2013 Shire Horse: Macht ohne Entschuldigung</h3>
        <p class="vb-intro">Das Shire Horse symbolisiert mit seiner imposanten Gr\u00f6\u00dfe, Kraft und Durchsetzungsf\u00e4higkeit den Herausforderer-Typ auf eindrucksvolle Weise. Shire Horses sind kraftvolle und dominante Pferde, die St\u00e4rke und Durchsetzungsverm\u00f6gen verk\u00f6rpern. Sie sind mutig und bereit, Herausforderungen anzunehmen. Ihr blo\u00dfes Auftreten bewegt ganze Landschaften \u2014 diese Pferde kennen kein Zur\u00fcckschrecken. Als die schwersten Pferde der Welt wurden sie eingesetzt, um Kriegsausr\u00fcstung zu ziehen, Fabriken anzutreiben, Hafen-Lasten zu bewegen. Die Leidenschaft der Gier zeigt sich als ungestillter Hunger nach Kraft, Einfluss und dem Gef\u00fchl, die Welt zu gestalten \u2014 oder zumindest den Pflug zu ziehen.</p>

        <h3 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Typ 9 \u2013 Connemara Pony: Harmonie als Heimat</h3>
        <p class="vb-intro">Das Connemara Pony ist bekannt f\u00fcr seine ruhige und ausgeglichene Natur \u2014 ein treffendes Bild des Vermittlers. Connemara Ponys sind ruhig und ausgeglichen. Sie sind freundlich und geduldig, streben nach Harmonie und sind leicht zu handhaben. Aus den rauhen Moorlandschaften Irlands stammen diese robusten, gen\u00fcgsamen Ponys, die mit allem zurechtkommen und niemandem zur Last fallen wollen. Sie passen sich jedem Reiter an, jedem Gel\u00e4nde, jedem Wetter \u2014 ohne Theater. Ihre Leidenschaft der Tr\u00e4gheit zeigt sich als tiefer Wunsch, den inneren Frieden nicht durch Konflikte st\u00f6ren zu lassen: Ein Connemara macht keinen \u00c4rger, und erwartet keinen.</p>

      </div>
      <div class="vb-section" style="max-width:100%;margin-top:2rem;">
        ${bookTip("wer-du-wirklich-bist-band-1", "\u00dcbersichten, Schaubilder und Typbeschreibungen \u2013 der erste Band der Trilogie, die das Enneagramm lebendig macht.", "Wer du wirklich bist \u2013 Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Vertiefte Typprofile und archetypische Betrachtungen \u2013 Band 2 der Rathmer-Trilogie.", "Wer du wirklich bist \u2013 Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypen, Heilungswege und das gro\u00dfe Bild \u2013 Band 3 als Abschluss der Trilogie.", "Wer du wirklich bist \u2013 Band 3")}
      </div>
      ${relatedLinks([
        {route:"hunderassen-der-9-typen", label:"Hunderassen der 9 Typen"},
        {route:"nagetierarten-der-9-typen", label:"Nagetierarten der 9 Typen"},
        {route:"baerenarten-der-9-typen", label:"B\u00e4renarten der 9 Typen"},
      ])}
    </div>
  `);
}


